  v.loop = false; v.muted = false;
  v.src = TEACHERS[id].dir + 'hero/intro-' + lang + '.mp4?v=' + TEACHER_HERO_V[id];
  v.onended = back;
  v.onerror = back;                       // clip missing → keep the idle loop, never a dead frame
