// Per-year geography/history derived from a country's social-studies topic list
function _primSocial(n, countryHistory) {
  const h = countryHistory && countryHistory.length ? countryHistory : ['الوطن وموقعه','التاريخ والحضارة','المدن الكبرى','البيئة الطبيعية','المجتمع والمواطنة'];
  // distribute topics across upper-primary grades; lower grades get gentle intro
  if (n <= 2) return [h[0]||'وطني','الأسرة والمدرسة','بيئتي من حولي'];
  return h.slice(0, 5);
}
function _primGrade(n, countryHistory) {
  const subs = [
    mkSubj('الرياضيات','🔢',S_MATH,..._PRIM_MATH[n]),
    mkSubj('اللغة العربية','📜',S_AR,..._PRIM_AR[n]),
    mkSubj('اللغة الإنجليزية','🗣️',S_EN,..._PRIM_EN[n]),
    mkSubj('العلوم','🔬',S_SCI,..._PRIM_SCI[n]),
  ];
  if (n >= 3) subs.push(mkSubj('الدراسات الاجتماعية','🌍',S_HIST,..._primSocial(n, countryHistory)));
  subs.push(mkSubj('التربية الإسلامية','☪️',S_ISL,..._PRIM_ISL[n]));
  return subs;
}
