// IGCSE schools continue into AS & A Level, so a Year 12/13 student picking "IGCSE / Cambridge"
// must find their subjects too. Shares the Cambridge A-Level list rather than duplicating it.
CURRICULA.igcse.grades.olevel = { label:'Year 10–11 (O Level)', subjects: CURRICULA.cambridge_olevel.grades.olevel.subjects };
CURRICULA.igcse.grades.as     = { label:'Year 12 (AS Level)',   subjects: CURRICULA.cambridge_alevel.grades.as.subjects };
CURRICULA.igcse.grades.a2     = { label:'Year 13 (A2 Level)',   subjects: CURRICULA.cambridge_alevel.grades.a2.subjects };

// Grade keys that no longer exist after IGCSE/American moved to one entry per year.
// Saved profiles still carry the old ones; map them to the nearest year instead of
// silently landing on Year 1 / Kindergarten.
// Egypt-first: the platform focuses on the Egyptian syllabus and the international systems taught
// in Egypt. These curricula keep working for anyone already on them but are not offered to new users.
const HIDDEN_CURRICULA = new Set(['saudi','uae','kuwait','qatar','bahrain','oman','jordan','palestine','lebanon',
  'syria','iraq','libya','sudan','yemen','morocco','algeria','tunisia','mauritania','cbse','icse','australian']);
function visibleCurricula() {
  return Object.entries(CURRICULA).filter(([k]) => !HIDDEN_CURRICULA.has(k) || k === S.curriculum);
}

function _legacyGrade(cur, g) {
  const m = { egypt:{ high:'prim1' }, egypt_lang:{ high:'prim1' }, igcse:{ primary:'y1', middle:'y7', alevel:'as' }, american:{ primary:'g1', middle:'g6', high:'g9' }, cambridge_alevel:{ high:'as' }, cambridge_olevel:{ high:'olevel' }, oxford_aqa:{ high:'igcse' }, ib:{ primary:'pyp', middle:'myp1', high:'dp1' }, cbse:{ primary:'c1', middle:'c6', high:'c11' }, icse:{ middle:'c9', high:'c11' }, australian:{ middle:'y7', high:'y11' }, canadian:{ middle:'g6', high:'g11' }, french_bac:{ middle:'sixieme', high:'premiere' }, german_abitur:{ high:'kl11' } };
  return (m[cur] && m[cur][g]) || g;
}
window.CURRICULA = CURRICULA;


