function viewPDF(url, viewUrl, subj, title) {
  S.textbookUrl        = url;
  S.textbookViewUrl    = (viewUrl && viewUrl !== 'undefined' && viewUrl !== '') ? viewUrl : url;
  S.textbookActiveSubj = subj  || '';
  S.textbookActiveTitle= title || '';
  render();
}

