function igcseGoBack() {
  // Smart back: topic → subject, subject → hub, special view → hub, hub → chat
  if (S.igcseTopic !== null)      { S.igcseTopic=null; S.igcseChapter=null; render(); return; }
  if (S.igcseView !== 'list')     { S.igcseView='list'; render(); return; }
  if (S.igcseSubject)             { S.igcseSubject=null; S.igcseChapter=null; render(); return; }
  S.screen='home'; render();
}

function tplIGCSENavBar() {
  // Determine what "back" means for the label
  let backLabel = L('Home','الرئيسية');
  if (S.igcseTopic !== null)  backLabel = L('Topic','الموضوع');
  else if (S.igcseView !== 'list') backLabel = L('Back','رجوع');
  else if (S.igcseSubject)    backLabel = L('Subjects','المواد');

  const isAtHub = (S.igcseView==='list' && !S.igcseSubject && S.igcseTopic===null);

  return `<div style="position:sticky;top:0;z-index:90;background:var(--bg);border-bottom:1px solid var(--border);
    display:flex;align-items:center;gap:6px;padding:8px 12px;backdrop-filter:blur(8px)">
    <!-- Back -->
    <button onclick="igcseGoBack()"
      style="display:flex;align-items:center;gap:5px;padding:7px 12px;border-radius:10px;border:1px solid var(--border);
             background:var(--bg-card);color:var(--text);cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif;transition:.15s"
      onmouseover="this.style.background='var(--border)'" onmouseout="this.style.background='var(--bg-card)'">
      ← ${backLabel}
    </button>
    <!-- Home / Hub -->
    ${!isAtHub ? `<button onclick="S.igcseView='list';S.igcseSubject=null;S.igcseChapter=null;S.igcseTopic=null;render()"
      title="${L('IGCSE Hub','الصفحة الرئيسية')}"
      style="display:flex;align-items:center;gap:5px;padding:7px 12px;border-radius:10px;border:1px solid var(--border);
             background:var(--bg-card);color:var(--text);cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif;transition:.15s"
      onmouseover="this.style.background='var(--border)'" onmouseout="this.style.background='var(--bg-card)'">
      🏠 ${L('Hub','الرئيسية')}
    </button>` : ''}
    <div style="flex:1"></div>
    <!-- Subject breadcrumb pill -->
    ${S.igcseSubject ? (()=>{
      const subj = IGCSE_SUBJECTS[S.igcseSubject];
      return subj ? `<div style="padding:5px 10px;border-radius:20px;background:${subj.color}18;border:1px solid ${subj.color}33;
        font-size:10px;font-weight:800;color:${subj.color};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:120px">
        ${subj.icon} ${subj.label}</div>` : '';
    })() : ''}
    <!-- Logout -->
    <button onclick="doLogout()"
      title="${L('Sign Out','تسجيل الخروج')}"
      style="display:flex;align-items:center;gap:5px;padding:7px 12px;border-radius:10px;border:1px solid #EF444430;
             background:#EF444408;color:#EF4444;cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif;transition:.15s;white-space:nowrap"
      onmouseover="this.style.background='#EF444420'" onmouseout="this.style.background='#EF444408'">
      🚪 ${L('Logout','خروج')}
    </button>
  </div>`;
}

function tplIGCSE() {
  const navBar = tplIGCSENavBar();
  if (S.igcseView === 'formulas')  return navBar + tplIGCSEFormulas();
  if (S.igcseView === 'compare')   return navBar + tplIGCSECompare();
  if (S.igcseView === 'search')    return navBar + tplIGCSEGlobalSearch();
  if (S.igcseView === 'papers')    return navBar + tplIGCSEPastPapers();
  if (S.igcseView === 'planner')   return navBar + tplIGCSEPlanner();
  if (S.igcseView === 'bookmarks') return navBar + tplIGCSEBookmarks();
  if (S.igcseView === 'mockexam')  return navBar + tplIGCSEMockExam();
  if (S.igcseView === 'stats')     return navBar + tplIGCSEStats();
  if (S.igcseView === 'mindmap')   return navBar + tplIGCSEMindMap();
  if (S.igcseTopic !== null)      return navBar + tplIGCSETopic();
  if (S.igcseSubject)             return navBar + tplIGCSESubject();
  return navBar + tplIGCSEHub();
}

function tplIGCSEPastPapers() {
  const sk = S.igcseSubject;
  const subj = IGCSE_SUBJECTS[sk];
  if (!subj) { S.igcseView='list'; return tplIGCSESubject(); }
  const board = IGCSE_BOARDS[S.igcseBoard];
  const chs = subj.chapters[S.igcseBoard] || subj.chapters.cie || [];
  const ppLink = subj.pastPapers[S.igcseBoard] || subj.pastPapers.cie || '#';

  // ── Build flat topic list with metadata ──────────────────────────
  const QUESTION_TYPES = ['MCQ','Short Answer','Structured','Extended Response','Data Response'];
  // Deterministic "exam frequency" based on number of points + examTip presence
  const allTopics = [];
  chs.forEach((ch, ci) => {
    ch.topics.forEach((tp, ti) => {
      const pts = (tp.points||[]).length;
      const hasExamTip = !!(tp.examTip);
      const hasMistakes = !!(tp.commonMistakes);
      // Frequency score: more points = higher exam weight (proxy)
      const freq = Math.min(5, Math.ceil(pts / 2) + (hasExamTip?1:0) + (hasMistakes?1:0));
      // Deterministic question type assignment per topic
      const qType = QUESTION_TYPES[(ci * 7 + ti * 3) % QUESTION_TYPES.length];
      const done = !!(S.igcseDone||{})[`${sk}-${ci}-${ti}`];
      allTopics.push({ ch, ci, tp, ti, freq, qType, done, pts, hasExamTip });
    });
  });

  // ── Filter state ──────────────────────────────────────────────────
  const chFilter  = S.igcsePpFilter || 'all';   // 'all' | chapter index string
  const typeFilter = S.igcsePpType  || 'all';   // 'all' | question type string
  const freqFilter = S.igcsePpFreq  || 'all';   // 'all' | 'high' | 'medium' | 'low'

  const filtered = allTopics.filter(t => {
    if (chFilter !== 'all' && String(t.ci) !== chFilter) return false;
    if (typeFilter !== 'all' && t.qType !== typeFilter) return false;
    if (freqFilter === 'high' && t.freq < 4) return false;
    if (freqFilter === 'medium' && (t.freq < 2 || t.freq > 3)) return false;
    if (freqFilter === 'low' && t.freq > 1) return false;
    return true;
  });

  // Stats
  const highFreqCount = allTopics.filter(t=>t.freq>=4).length;
  const doneCount     = allTopics.filter(t=>t.done).length;
  const tipCount      = allTopics.filter(t=>t.hasExamTip).length;

  // ── Chapter filter pills ──────────────────────────────────────────
  const chPills = [`<button onclick="S.igcsePpFilter='all';render()"
    style="padding:5px 12px;border-radius:20px;border:1.5px solid ${chFilter==='all'?subj.color:'var(--border)'};
           background:${chFilter==='all'?subj.color+'18':'transparent'};color:${chFilter==='all'?subj.color:'var(--text-muted)'};
           cursor:pointer;font-family:Cairo,sans-serif;font-size:10px;font-weight:800;white-space:nowrap">
    All chapters (${allTopics.length})
  </button>`].concat(chs.map((ch,ci)=>{
    const active = chFilter===String(ci);
    const cnt = allTopics.filter(t=>t.ci===ci).length;
    return `<button onclick="S.igcsePpFilter='${ci}';render()"
      style="padding:5px 12px;border-radius:20px;border:1.5px solid ${active?subj.color:'var(--border)'};
             background:${active?subj.color+'18':'transparent'};color:${active?subj.color:'var(--text-muted)'};
             cursor:pointer;font-family:Cairo,sans-serif;font-size:10px;font-weight:800;white-space:nowrap">
      ${ch.icon||'📘'} ${ch.title} (${cnt})
    </button>`;
  })).join('');

  // ── Type filter pills ─────────────────────────────────────────────
  const typePills = ['all',...QUESTION_TYPES].map(t => {
    const active = typeFilter===t;
    const cnt = t==='all' ? allTopics.length : allTopics.filter(x=>x.qType===t).length;
    const label = t==='all'?'All Types':t;
    return `<button onclick="S.igcsePpType='${t}';render()"
      style="padding:5px 12px;border-radius:20px;border:1.5px solid ${active?'#F59E0B':'var(--border)'};
             background:${active?'#F59E0B18':'transparent'};color:${active?'#F59E0B':'var(--text-muted)'};
             cursor:pointer;font-family:Cairo,sans-serif;font-size:10px;font-weight:800;white-space:nowrap">
      ${label}${t!=='all'?` (${cnt})`:''}
    </button>`;
  }).join('');

  // ── Freq filter ───────────────────────────────────────────────────
  const freqPills = [
    {k:'all',label:'Any frequency',col:'#6366F1'},
    {k:'high',label:'🔥 High (likely exam)',col:'#EF4444'},
    {k:'medium',label:'⚡ Medium',col:'#F59E0B'},
    {k:'low',label:'💤 Low',col:'#6B7280'},
  ].map(f=>{
    const active = freqFilter===f.k;
    return `<button onclick="S.igcsePpFreq='${f.k}';render()"
      style="padding:5px 12px;border-radius:20px;border:1.5px solid ${active?f.col:'var(--border)'};
             background:${active?f.col+'18':'transparent'};color:${active?f.col:'var(--text-muted)'};
             cursor:pointer;font-family:Cairo,sans-serif;font-size:10px;font-weight:800;white-space:nowrap">
      ${f.label}
    </button>`;
  }).join('');

  // ── Frequency dot helper ──────────────────────────────────────────
  function freqDots(freq) {
    const col = freq>=4?'#EF4444':freq>=2?'#F59E0B':'#9CA3AF';
    return Array.from({length:5},(_,i)=>
      `<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${i<freq?col:'var(--border)'}"></span>`
    ).join('');
  }

  // ── Topic rows ────────────────────────────────────────────────────
  const TYPE_ICONS = {
    'MCQ':'🔘','Short Answer':'✏️','Structured':'📝','Extended Response':'📄','Data Response':'📊'
  };
  const rows = filtered.map(({ch,ci,tp,ti,freq,qType,done,hasExamTip}) => `
  <div style="display:flex;align-items:flex-start;gap:10px;padding:12px 14px;background:var(--bg-card);
       border:1px solid var(--border);border-radius:12px;transition:.15s;
       ${freq>=4?'border-left:3px solid #EF4444':'border-left:3px solid var(--border)'}"
    onmouseover="this.style.background='${subj.color}0a';this.style.borderColor='${subj.color}'"
    onmouseout="this.style.background='';this.style.borderColor='${freq>=4?'#EF4444':''}';this.style.borderLeftColor='${freq>=4?'#EF4444':'var(--border)'}'"
  >
    <!-- Frequency dots -->
    <div style="display:flex;flex-direction:column;align-items:center;gap:3px;padding-top:2px;flex-shrink:0">
      ${freqDots(freq)}
    </div>
    <!-- Content -->
    <div style="flex:1;min-width:0">
      <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:3px">
        <span style="font-size:14px;font-weight:900;color:var(--text)">${tp.title}</span>
        ${done?`<span style="font-size:11px;background:#10B98120;color:#10B981;border-radius:6px;padding:2px 7px;font-weight:700">✓ Done</span>`:''}
        ${freq>=4?`<span style="font-size:11px;background:#EF444420;color:#EF4444;border-radius:6px;padding:2px 7px;font-weight:700">🔥 High freq</span>`:''}
        ${hasExamTip?`<span style="font-size:11px;background:#F59E0B15;color:#F59E0B;border-radius:6px;padding:2px 7px;font-weight:700">💡 Exam tip</span>`:''}
      </div>
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:6px">${ch.icon||'📘'} ${ch.title}</div>
      <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
        <span style="font-size:11px;background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:3px 9px;color:var(--text-muted);font-weight:700">
          ${TYPE_ICONS[qType]||'📝'} ${qType}
        </span>
        <button onclick="S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='notes';S.igcseView='list';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
          style="font-size:12px;background:${subj.color}18;border:none;border-radius:8px;padding:5px 12px;color:${subj.color};font-weight:800;cursor:pointer;font-family:Cairo,sans-serif">
          📖 Study Notes
        </button>
        <button onclick="S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='questions';S.igcseView='list';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
          style="font-size:12px;background:#6366F118;border:none;border-radius:8px;padding:5px 12px;color:#6366F1;font-weight:800;cursor:pointer;font-family:Cairo,sans-serif">
          ❓ Practice Qs
        </button>
      </div>
    </div>
  </div>`).join('');

  return `
<div style="max-width:920px;margin:0 auto;padding:0 0 80px">
  <!-- Header -->
  <div style="background:linear-gradient(135deg,${subj.color}ee,${subj.color}99);padding:18px 16px 22px;border-radius:0 0 24px 24px;margin-bottom:20px">
    <button onclick="S.igcseView='list';render()"
      style="background:#ffffff25;border:1px solid #ffffff35;border-radius:10px;padding:5px 12px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700;margin-bottom:12px">
      ← Back to ${subj.label}
    </button>
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:14px">
      <div style="font-size:36px">${subj.icon}</div>
      <div>
        <div style="font-size:20px;font-weight:900;color:#fff">${subj.label} — Past Papers</div>
        <div style="font-size:11px;color:#ffffffcc">📋 Topic frequency guide · ${board.icon} ${board.label}</div>
      </div>
    </div>
    <!-- Stats row -->
    <div style="display:flex;gap:14px;flex-wrap:wrap">
      <div style="text-align:center"><div style="font-size:18px;font-weight:900;color:#fff">${allTopics.length}</div><div style="font-size:12px;color:#ffffffaa">Total Topics</div></div>
      <div style="width:1px;background:#ffffff30"></div>
      <div style="text-align:center"><div style="font-size:18px;font-weight:900;color:#ffcccc">${highFreqCount}</div><div style="font-size:12px;color:#ffffffaa">🔥 High Freq</div></div>
      <div style="width:1px;background:#ffffff30"></div>
      <div style="text-align:center"><div style="font-size:18px;font-weight:900;color:#fff">${tipCount}</div><div style="font-size:12px;color:#ffffffaa">💡 Exam Tips</div></div>
      <div style="width:1px;background:#ffffff30"></div>
      <div style="text-align:center"><div style="font-size:18px;font-weight:900;color:#ccffdd">${doneCount}</div><div style="font-size:12px;color:#ffffffaa">✓ Studied</div></div>
    </div>
  </div>

  <div style="padding:0 14px">
    <!-- Official past papers CTA -->
    <div style="display:flex;align-items:center;gap:10px;padding:12px 14px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;margin-bottom:16px">
      <div style="font-size:28px">📄</div>
      <div style="flex:1">
        <div style="font-size:12px;font-weight:900;color:var(--text)">Official ${board.short} Past Papers</div>
        <div style="font-size:10px;color:var(--text-muted)">Download real exam papers from the board website</div>
      </div>
      <a href="${ppLink}" target="_blank" rel="noopener"
        style="padding:8px 14px;background:${board.color};color:#fff;border-radius:10px;text-decoration:none;font-size:11px;font-weight:800;font-family:Cairo,sans-serif;white-space:nowrap">
        📥 Open
      </a>
    </div>

    <!-- Frequency legend -->
    <div style="display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;margin-bottom:16px;flex-wrap:wrap">
      <span style="font-size:12px;font-weight:800;color:var(--text-muted)">FREQUENCY GUIDE:</span>
      <span style="font-size:12px;color:#EF4444;font-weight:700">🔥 High — appears almost every year</span>
      <span style="font-size:12px;color:#F59E0B;font-weight:700">⚡ Medium — appears every other year</span>
      <span style="font-size:12px;color:#9CA3AF;font-weight:700">💤 Low — occasionally examined</span>
    </div>

    <!-- Chapter filter -->
    <div style="margin-bottom:10px">
      <div style="font-size:12px;color:var(--text-muted);font-weight:800;letter-spacing:1px;margin-bottom:6px">FILTER BY CHAPTER</div>
      <div style="display:flex;gap:6px;flex-wrap:wrap">${chPills}</div>
    </div>

    <!-- Question type filter -->
    <div style="margin-bottom:10px">
      <div style="font-size:12px;color:var(--text-muted);font-weight:800;letter-spacing:1px;margin-bottom:6px">QUESTION TYPE</div>
      <div style="display:flex;gap:6px;flex-wrap:wrap">${typePills}</div>
    </div>

    <!-- Frequency filter -->
    <div style="margin-bottom:16px">
      <div style="font-size:12px;color:var(--text-muted);font-weight:800;letter-spacing:1px;margin-bottom:6px">EXAM FREQUENCY</div>
      <div style="display:flex;gap:6px;flex-wrap:wrap">${freqPills}</div>
    </div>

    <!-- Results count -->
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
      <div style="font-size:13px;color:var(--text-muted);font-weight:700">
        Showing <span style="color:var(--text);font-weight:900">${filtered.length}</span> of ${allTopics.length} topics
        ${filtered.length<allTopics.length?`<button onclick="S.igcsePpFilter='all';S.igcsePpType='all';S.igcsePpFreq='all';render()"
          style="margin-left:8px;background:none;border:none;color:#6366F1;cursor:pointer;font-size:10px;font-weight:800;font-family:Cairo,sans-serif">Clear filters</button>`:''}
      </div>
      <div style="font-size:12px;color:var(--text-muted)">Dots = exam frequency →</div>
    </div>

    <!-- Topic rows -->
    <div style="display:flex;flex-direction:column;gap:8px">
      ${rows || '<div style="text-align:center;padding:40px;color:var(--text-muted)">No topics match these filters</div>'}
    </div>
  </div>
</div>`;
}

function tplIGCSEGlobalSearch() {
  const q = (S.igcseSearch || '').toLowerCase().trim();

  // ── Collect results across ALL boards ──────────────────────────────
  const results = []; // { sk, subj, board, boardKey, ch, ci, tp, ti, matchType, snippet }

  if (q) {
    Object.entries(IGCSE_SUBJECTS).forEach(([sk, subj]) => {
      subj.boards.forEach(bk => {
        const b = IGCSE_BOARDS[bk];
        const chs = subj.chapters[bk] || subj.chapters.cie || [];
        chs.forEach((ch, ci) => {
          ch.topics.forEach((tp, ti) => {
            const titleMatch = tp.title.toLowerCase().includes(q);
            const pointMatch = tp.points && tp.points.some(p => p.toLowerCase().includes(q));
            const examMatch  = tp.examTip && tp.examTip.toLowerCase().includes(q);
            const chMatch    = ch.title.toLowerCase().includes(q);
            const subjMatch  = subj.label.toLowerCase().includes(q) || (subj.arabic||'').includes(q);
            if (titleMatch || pointMatch || examMatch || chMatch || subjMatch) {
              // Avoid duplicates when boards share identical chapter data (fallback)
              const dedupKey = `${sk}-${ci}-${ti}-${bk}`;
              if (!results.find(r => r.dedupKey === dedupKey)) {
                // Build a short snippet from matching point
                let snippet = '';
                if (pointMatch) {
                  const mp = tp.points.find(p => p.toLowerCase().includes(q));
                  const idx = mp.toLowerCase().indexOf(q);
                  snippet = '…' + mp.slice(Math.max(0,idx-30), idx+60) + '…';
                }
                results.push({
                  dedupKey, sk, subj, board: b, boardKey: bk, ch, ci, tp, ti,
                  matchType: titleMatch ? 'title' : pointMatch ? 'point' : chMatch ? 'chapter' : 'subject',
                  snippet
                });
              }
            }
          });
        });
      });
    });
  }

  // ── Group by subject ───────────────────────────────────────────────
  const bySubject = {};
  results.forEach(r => {
    if (!bySubject[r.sk]) bySubject[r.sk] = { subj: r.subj, sk: r.sk, items: [] };
    bySubject[r.sk].items.push(r);
  });

  // ── Board filter chips ─────────────────────────────────────────────
  const activeBoardFilter = S.igcseSearchBoard || 'all';
  const boardCounts = {};
  results.forEach(r => { boardCounts[r.boardKey] = (boardCounts[r.boardKey]||0)+1; });
  const boardChips = [
    { k:'all', label:'All Boards', icon:'🌐', count: results.length }
  ].concat(Object.entries(IGCSE_BOARDS).map(([k,b]) => ({
    k, label: b.short, icon: b.icon, count: boardCounts[k]||0, color: b.color
  }))).map(chip => {
    const active = activeBoardFilter === chip.k;
    return `<button onclick="S.igcseSearchBoard='${chip.k}';render()"
      style="display:inline-flex;align-items:center;gap:5px;padding:5px 12px;border-radius:20px;border:1.5px solid ${active?(chip.color||'#6366F1'):'var(--border)'};
             background:${active?(chip.color||'#6366F1')+'18':'transparent'};color:${active?(chip.color||'#6366F1'):'var(--text-muted)'};
             cursor:pointer;font-family:Cairo,sans-serif;font-size:10px;font-weight:800;white-space:nowrap;transition:.15s">
      <span>${chip.icon}</span><span>${chip.label}</span>
      <span style="background:${active?(chip.color||'#6366F1'):'var(--border)'};color:${active?'#fff':'var(--text-muted)'};
             border-radius:10px;padding:0 5px;font-size:9px">${chip.count}</span>
    </button>`;
  }).join('');

  // ── Filter results by board ────────────────────────────────────────
  const visibleResults = activeBoardFilter === 'all'
    ? results
    : results.filter(r => r.boardKey === activeBoardFilter);

  // ── Group visible results by subject ──────────────────────────────
  const visibleBySubject = {};
  visibleResults.forEach(r => {
    if (!visibleBySubject[r.sk]) visibleBySubject[r.sk] = { subj: r.subj, sk: r.sk, items: [] };
    visibleBySubject[r.sk].items.push(r);
  });

  // ── Render result cards ────────────────────────────────────────────
  const LIMIT = 40; // max results rendered
  let renderedCount = 0;
  const subjectBlocks = Object.values(visibleBySubject).map(({ subj, sk, items }) => {
    const remaining = LIMIT - renderedCount;
    if (remaining <= 0) return '';
    const toShow = items.slice(0, remaining);
    renderedCount += toShow.length;

    const cards = toShow.map(r => {
      const b = r.board;
      const done = S.igcseDone[`${sk}-${r.ci}-${r.ti}`];
      return `
      <div onclick="S.igcseBoard='${r.boardKey}';S.igcseSubject='${sk}';S.igcseChapter=${r.ci};S.igcseTopic=${r.ti};S.igcseTab='notes';S.igcseView='list';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
        style="display:flex;align-items:flex-start;gap:10px;padding:10px 12px;background:var(--bg-card);border:1px solid var(--border);
               border-radius:12px;cursor:pointer;transition:.15s;border-left:3px solid ${b.color}"
        onmouseover="this.style.background='${b.color}0a';this.style.borderColor='${b.color}'"
        onmouseout="this.style.background='';this.style.borderColor=''">
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:2px">
            <span style="font-size:11px;font-weight:900;color:var(--text)">${r.tp.title}</span>
            ${done?`<span style="font-size:9px;background:#10B98120;color:#10B981;border-radius:6px;padding:1px 5px;font-weight:700">✓ Done</span>`:''}
          </div>
          <div style="font-size:9px;color:var(--text-muted);margin-bottom:${r.snippet?4:0}px">${r.ch.title}</div>
          ${r.snippet?`<div style="font-size:9px;color:var(--text-muted);line-height:1.5;font-style:italic">${r.snippet.replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<mark style="background:#F59E0B30;color:#F59E0B;border-radius:2px;padding:0 2px">$1</mark>')}</div>`:''}
        </div>
        <span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;border-radius:10px;background:${b.color}18;color:${b.color};font-size:9px;font-weight:800;white-space:nowrap;flex-shrink:0">
          ${b.icon} ${b.short}
        </span>
      </div>`;
    }).join('');

    return `
    <div style="margin-bottom:16px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;padding:0 2px">
        <span style="font-size:18px">${subj.icon}</span>
        <span style="font-size:12px;font-weight:900;color:var(--text)">${subj.label}</span>
        <span style="font-size:9px;background:${subj.color}18;color:${subj.color};border-radius:10px;padding:1px 7px;font-weight:700">${items.length} match${items.length>1?'es':''}</span>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px">${cards}</div>
    </div>`;
  }).join('');

  // ── "No results" suggestions ───────────────────────────────────────
  const popularSearches = ['cell division','photosynthesis','trigonometry','acids and bases','Newton\'s laws','electricity','genetics','quadratic'];

  return `
<div style="max-width:920px;margin:0 auto;padding:0 0 80px">
  <!-- Header -->
  <div style="background:linear-gradient(135deg,#6366F1,#4F46E5);padding:18px 16px 22px;border-radius:0 0 24px 24px;margin-bottom:20px">
    <button onclick="S.igcseView='list';render()"
      style="background:#ffffff25;border:1px solid #ffffff35;border-radius:10px;padding:5px 12px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700;margin-bottom:12px">
      ← Back to Hub
    </button>
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:14px">
      <div style="font-size:32px">🔎</div>
      <div>
        <div style="font-size:20px;font-weight:900;color:#fff">Global Search</div>
        <div style="font-size:11px;color:#ffffffcc">Search across all 21 subjects & 3 boards simultaneously</div>
      </div>
    </div>
    <!-- Search input -->
    <div style="position:relative">
      <input id="igcse-global-search" type="text" placeholder="e.g. photosynthesis, quadratic formula, Newton…"
        value="${S.igcseSearch||''}"
        oninput="S.igcseSearch=this.value;render()"
        autofocus
        style="width:100%;padding:12px 44px 12px 16px;border-radius:14px;border:2px solid #ffffff40;background:#ffffff18;
               color:#fff;font-size:14px;font-family:Cairo,sans-serif;box-sizing:border-box;outline:none;
               caret-color:#fff;backdrop-filter:blur(4px)"
        onfocus="this.style.borderColor='#ffffff80'" onblur="this.style.borderColor='#ffffff40'">
      ${q?`<button onclick="S.igcseSearch='';render()"
        style="position:absolute;right:12px;top:50%;transform:translateY(-50%);background:none;border:none;cursor:pointer;font-size:18px;color:#ffffffcc">✕</button>`
       :`<span style="position:absolute;right:14px;top:50%;transform:translateY(-50%);font-size:18px;pointer-events:none">🔍</span>`}
    </div>
  </div>

  <div style="padding:0 14px">
    ${!q ? `
    <!-- Empty state with suggestions -->
    <div style="text-align:center;padding:30px 10px 20px">
      <div style="font-size:48px;margin-bottom:10px">🔎</div>
      <div style="font-size:16px;font-weight:900;color:var(--text);margin-bottom:6px">Search everything at once</div>
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:24px">Topics, chapters, notes, exam tips — across all boards in one go</div>
      <div style="font-size:11px;color:var(--text-muted);font-weight:700;margin-bottom:10px">POPULAR SEARCHES</div>
      <div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center">
        ${popularSearches.map(s=>`
        <button onclick="S.igcseSearch='${s}';render()"
          style="padding:7px 14px;border-radius:20px;border:1.5px solid var(--border);background:var(--bg-card);
                 color:var(--text);cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:700;transition:.15s"
          onmouseover="this.style.borderColor='#6366F1';this.style.color='#6366F1'"
          onmouseout="this.style.borderColor='';this.style.color=''">
          ${s}
        </button>`).join('')}
      </div>
    </div>
    ` : `
    <!-- Results summary + board filter -->
    <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:14px">
      <div style="font-size:11px;color:var(--text-muted);font-weight:700">
        ${visibleResults.length > 0
          ? `<span style="color:var(--text);font-weight:900">${visibleResults.length}</span> result${visibleResults.length!==1?'s':''} for "<span style="color:#6366F1">${S.igcseSearch}</span>"`
          : `No results for "<span style="color:#EF4444">${S.igcseSearch}</span>"`}
        ${visibleResults.length !== results.length ? ` · <span style="color:var(--text)">${results.length} total across all boards</span>`:''}
      </div>
    </div>
    <!-- Board filter chips -->
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px">
      ${boardChips}
    </div>

    ${visibleResults.length === 0 ? `
    <div style="text-align:center;padding:40px 20px;color:var(--text-muted)">
      <div style="font-size:40px;margin-bottom:10px">😕</div>
      <div style="font-size:14px;font-weight:700;margin-bottom:6px">No matches found</div>
      <div style="font-size:11px">Try a shorter keyword, or switch board filter to "All Boards"</div>
    </div>
    ` : `
    ${subjectBlocks}
    ${renderedCount < results.length ? `
    <div style="text-align:center;padding:12px;font-size:11px;color:var(--text-muted);background:var(--bg-card);border-radius:10px;border:1px solid var(--border)">
      Showing ${renderedCount} of ${results.length} results — refine your search to narrow down
    </div>`:``}
    `}
    `}
  </div>
</div>`;
}

function tplIGCSECompare() {
  const subj = IGCSE_SUBJECTS[S.igcseSubject];
  if (!subj) { S.igcseView='list'; return tplIGCSEHub(); }

  // Boards this subject supports
  const availableBoards = subj.boards.map(k => ({ key:k, ...IGCSE_BOARDS[k] }));

  // Calculate per-board stats
  const boardStats = availableBoards.map(b => {
    const chs = subj.chapters[b.key] || [];
    const topicCount = chs.reduce((a,c) => a + c.topics.length, 0);
    const doneCount = chs.reduce((a,c,ci) =>
      a + c.topics.filter((_,ti) => S.igcseDone[`${S.igcseSubject}-${ci}-${ti}`]).length, 0);
    const pct = topicCount ? Math.round(doneCount/topicCount*100) : 0;
    const hasOwn = !!subj.chapters[b.key];
    return { ...b, chs, topicCount, doneCount, pct, hasOwn };
  });

  // Side-by-side chapter columns
  const maxChapters = Math.max(...boardStats.map(b => b.chs.length));

  const columns = boardStats.map(b => {
    const rows = b.chs.map((ch, ci) => {
      const chDone = ch.topics.filter((_,ti) => S.igcseDone[`${S.igcseSubject}-${ci}-${ti}`]).length;
      const chPct = ch.topics.length ? Math.round(chDone/ch.topics.length*100) : 0;
      return `
      <div style="padding:10px 12px;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;margin-bottom:8px;cursor:pointer;transition:.15s"
        onclick="S.igcseBoard='${b.key}';S.igcseChapter=${ci};S.igcseView='list';render()"
        onmouseover="this.style.borderColor='${b.color}';this.style.background='${b.color}08'"
        onmouseout="this.style.borderColor='';this.style.background='var(--bg-card)'">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
          <span style="font-size:15px">${ch.icon||'📘'}</span>
          <span style="font-size:11px;font-weight:800;color:var(--text);flex:1;line-height:1.3">${ch.title}</span>
          ${chPct>0?`<span style="font-size:9px;color:#10B981;font-weight:700">${chPct}%</span>`:''}
        </div>
        <div style="font-size:10px;color:var(--text-muted);margin-bottom:${chPct>0?5:0}px">${ch.topics.length} topics</div>
        ${chPct>0?`<div style="height:2px;background:var(--border);border-radius:1px"><div style="height:100%;width:${chPct}%;background:#10B981;border-radius:1px"></div></div>`:''}
      </div>`;
    }).join('');

    // Unique topics not in other boards (rough count by title)
    const allOtherTopicTitles = new Set(
      boardStats.filter(x=>x.key!==b.key).flatMap(x=>x.chs.flatMap(c=>c.topics.map(t=>t.title.toLowerCase())))
    );
    const uniqueTopics = b.chs.flatMap(c=>c.topics).filter(t=>!allOtherTopicTitles.has(t.title.toLowerCase())).length;

    return `
    <div style="flex:1;min-width:240px">
      <!-- Board Header -->
      <div style="background:${b.color};border-radius:14px;padding:14px;margin-bottom:12px;text-align:center">
        <div style="font-size:22px;margin-bottom:4px">${b.icon}</div>
        <div style="font-size:14px;font-weight:900;color:#fff">${b.short}</div>
        <div style="font-size:10px;color:#ffffffcc;margin-top:1px">${b.label}</div>
      </div>
      <!-- Stats row -->
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-bottom:12px">
        <div style="text-align:center;padding:8px 4px;background:var(--bg-card);border-radius:10px;border:1px solid var(--border)">
          <div style="font-size:16px;font-weight:900;color:${b.color}">${b.chs.length}</div>
          <div style="font-size:9px;color:var(--text-muted);font-weight:700">chapters</div>
        </div>
        <div style="text-align:center;padding:8px 4px;background:var(--bg-card);border-radius:10px;border:1px solid var(--border)">
          <div style="font-size:16px;font-weight:900;color:${b.color}">${b.topicCount}</div>
          <div style="font-size:9px;color:var(--text-muted);font-weight:700">topics</div>
        </div>
        <div style="text-align:center;padding:8px 4px;background:var(--bg-card);border-radius:10px;border:1px solid var(--border)">
          <div style="font-size:16px;font-weight:900;color:${uniqueTopics>0?b.color:'var(--text-muted)'}">${uniqueTopics}</div>
          <div style="font-size:9px;color:var(--text-muted);font-weight:700">unique</div>
        </div>
      </div>
      <!-- Progress -->
      <div style="margin-bottom:12px;padding:10px 12px;background:var(--bg-card);border-radius:12px;border:1px solid var(--border)">
        <div style="display:flex;justify-content:space-between;margin-bottom:5px">
          <span style="font-size:10px;color:var(--text-muted);font-weight:700">YOUR PROGRESS</span>
          <span style="font-size:10px;color:${b.color};font-weight:800">${b.doneCount}/${b.topicCount} · ${b.pct}%</span>
        </div>
        <div style="height:5px;background:var(--border);border-radius:3px">
          <div style="height:100%;width:${b.pct}%;background:${b.pct===100?'#10B981':b.color};border-radius:3px;transition:.5s"></div>
        </div>
      </div>
      <!-- Switch to this board button -->
      <button onclick="S.igcseBoard='${b.key}';S.igcseView='list';render()"
        style="width:100%;padding:9px;margin-bottom:12px;border-radius:10px;border:2px solid ${b.color};background:${S.igcseBoard===b.key?b.color:'transparent'};color:${S.igcseBoard===b.key?'#fff':b.color};cursor:pointer;font-family:Cairo,sans-serif;font-weight:800;font-size:11px;transition:.15s">
        ${S.igcseBoard===b.key?'✓ Currently Selected':'Switch to '+b.short}
      </button>
      <!-- Chapter list -->
      <div style="font-size:9px;color:var(--text-muted);font-weight:800;letter-spacing:1px;margin-bottom:8px">CHAPTERS (click to study)</div>
      ${rows || '<div style="text-align:center;padding:20px;color:var(--text-muted);font-size:12px">Same as CIE (fallback)</div>'}
    </div>`;
  }).join('');

  return `
<div style="max-width:980px;margin:0 auto;padding:0 0 80px">
  <!-- Header -->
  <div style="background:linear-gradient(135deg,${subj.color},${subj.color}99);padding:18px 16px 22px;border-radius:0 0 24px 24px;margin-bottom:20px">
    <button onclick="S.igcseView='list';render()"
      style="background:#ffffff25;border:1px solid #ffffff35;border-radius:10px;padding:5px 12px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700;margin-bottom:12px">
      ← Back to ${subj.label}
    </button>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="font-size:36px">${subj.icon}</div>
      <div>
        <div style="font-size:20px;font-weight:900;color:#fff">${subj.label}</div>
        <div style="font-size:11px;color:#ffffffcc">⚖️ Board Comparison · ${availableBoards.length} boards available</div>
      </div>
    </div>
  </div>

  <!-- Comparison tip -->
  <div style="margin:0 14px 16px;padding:10px 14px;background:var(--bg-card);border-radius:12px;border:1px solid var(--border);font-size:11px;color:var(--text-muted)">
    💡 Click any chapter to switch to that board and start studying. <strong style="color:var(--text)">"Unique"</strong> = topics exclusive to that board not found in others.
  </div>

  <!-- Board columns -->
  <div style="padding:0 14px;display:flex;gap:14px;align-items:flex-start;overflow-x:auto">
    ${columns}
  </div>
</div>`;
}

function printTopicNotes(sk, ci, ti) {
  const subj = IGCSE_SUBJECTS[sk];
  if (!subj) return;
  const chapters = subj.chapters[S.igcseBoard] || [];
  const ch = chapters[ci];
  if (!ch) return;
  const tp = ch.topics[ti];
  if (!tp) return;
  const board = IGCSE_BOARDS[S.igcseBoard];

  const pointsHtml = tp.points.map((p, i) => `
    <div class="point">
      <span class="num">${i + 1}</span>
      <span>${p}</span>
    </div>`).join('');

  const workedHtml = tp.workedExample ? `
    <div class="section worked">
      <div class="section-title">✏️ Worked Example</div>
      <pre>${tp.workedExample}</pre>
    </div>` : '';

  const tipsHtml = tp.examTips && tp.examTips.length ? `
    <div class="section tips">
      <div class="section-title">⭐ Exam Tips</div>
      ${tp.examTips.map(t => `<div class="tip">✓ ${t}</div>`).join('')}
    </div>` : '';

  const mistakesHtml = tp.commonMistakes && tp.commonMistakes.length ? `
    <div class="section mistakes">
      <div class="section-title">⚠️ Common Mistakes</div>
      ${tp.commonMistakes.map(m => `<div class="mistake">✗ ${m}</div>`).join('')}
    </div>` : '';

  const win = window.open('', '_blank');
  win.document.write(`<!DOCTYPE html><html><head>
  <meta charset="UTF-8">
  <title>${subj.label} — ${tp.title}</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: Arial, sans-serif; font-size: 13px; color: #1a1a1a; padding: 30px 40px; max-width: 800px; margin: 0 auto; }
    .header { border-bottom: 3px solid ${subj.color}; padding-bottom: 14px; margin-bottom: 20px; }
    .board-badge { display: inline-block; background: ${board.color}; color: #fff; padding: 2px 10px; border-radius: 20px; font-size: 11px; font-weight: bold; margin-bottom: 6px; }
    .subject { font-size: 13px; color: #666; margin-bottom: 4px; }
    .chapter { font-size: 12px; color: #999; }
    h1 { font-size: 22px; color: ${subj.color}; margin: 6px 0 2px; }
    .meta { font-size: 11px; color: #aaa; margin-top: 4px; }
    .section { margin-bottom: 18px; }
    .section-title { font-size: 11px; font-weight: bold; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 8px; padding: 4px 10px; border-radius: 6px; display: inline-block; }
    .point { display: flex; gap: 10px; align-items: flex-start; padding: 7px 10px; border-left: 3px solid ${subj.color}; margin-bottom: 6px; background: ${subj.color}08; border-radius: 0 6px 6px 0; line-height: 1.6; }
    .num { min-width: 22px; height: 22px; background: ${subj.color}; color: #fff; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: bold; flex-shrink: 0; }
    .worked { background: #EFF6FF; border-radius: 8px; padding: 14px; }
    .worked .section-title { color: #2563EB; background: #DBEAFE; }
    .worked pre { font-family: monospace; font-size: 12px; white-space: pre-wrap; line-height: 1.7; margin-top: 8px; color: #1e3a5f; }
    .tips { background: #F0FDF4; border-radius: 8px; padding: 14px; }
    .tips .section-title { color: #059669; background: #D1FAE5; }
    .tip { padding: 5px 0; border-bottom: 1px solid #D1FAE5; font-size: 12px; line-height: 1.6; color: #065f46; }
    .mistakes { background: #FFF5F5; border-radius: 8px; padding: 14px; }
    .mistakes .section-title { color: #DC2626; background: #FEE2E2; }
    .mistake { padding: 5px 0; border-bottom: 1px solid #FEE2E2; font-size: 12px; line-height: 1.6; color: #7f1d1d; }
    .footer { margin-top: 30px; padding-top: 10px; border-top: 1px solid #eee; font-size: 10px; color: #bbb; display: flex; justify-content: space-between; }
    @media print {
      body { padding: 15px 20px; }
      .no-print { display: none; }
    }
    .print-btn { position: fixed; bottom: 20px; right: 20px; padding: 10px 20px; background: ${subj.color}; color: #fff; border: none; border-radius: 10px; cursor: pointer; font-size: 13px; font-weight: bold; box-shadow: 0 4px 12px ${subj.color}55; }
  </style>
  </head><body>
  <div class="header">
    <div class="board-badge">${board.label}</div>
    <div class="subject">${subj.icon} ${subj.label}</div>
    <div class="chapter">Chapter: ${ch.title}</div>
    <h1>${tp.title}</h1>
    <div class="meta">Generated by Ostazzi · ${new Date().toLocaleDateString('en-GB', {day:'numeric',month:'long',year:'numeric'})}</div>
  </div>
  <div class="section">
    <div class="section-title" style="color:${subj.color};background:${subj.color}18">📖 Key Notes (${tp.points.length} points)</div>
    ${pointsHtml}
  </div>
  ${workedHtml}
  ${tipsHtml}
  ${mistakesHtml}
  <div class="footer">
    <span>Ostazzi — IGCSE Revision Platform</span>
    <span>${subj.label} · ${board.short} · ${tp.title}</span>
  </div>
  <button class="print-btn no-print" onclick="window.print();this.style.display='none'">🖨️ Print / Save PDF</button>
  </body></html>`);
  win.document.close();
}

function tplIGCSEFormulas() {
  // Allow browsing any subject that has formulas
  const formulaSubjects = Object.entries(IGCSE_FORMULAS||{});
  if(!S.igcseSubject || !IGCSE_FORMULAS[S.igcseSubject]) {
    // Show subject picker
    return `<div style="max-width:860px;margin:0 auto;padding:0 0 80px">
      <div style="background:linear-gradient(135deg,#7C3AED,#5B21B6);padding:18px 16px 22px;border-radius:0 0 22px 22px;margin-bottom:18px">
        <button onclick="S.igcseView='list';render()" style="background:#ffffff25;border:1px solid #ffffff35;border-radius:10px;padding:5px 12px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700;margin-bottom:12px">← Back</button>
        <div style="font-size:30px;margin-bottom:6px">📐</div>
        <div style="font-size:20px;font-weight:900;color:#fff">Formula Sheets</div>
        <div style="font-size:12px;color:#ffffffbb;margin-top:4px">Select a subject to view its formula sheet</div>
      </div>
      <div style="padding:0 14px;display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px">
        ${formulaSubjects.map(([sk])=>{
          const s = IGCSE_SUBJECTS[sk];
          if(!s) return '';
          return `<div onclick="S.igcseSubject='${sk}';S.igcseView='formulas';render()"
            style="padding:16px 12px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;cursor:pointer;text-align:center;transition:.15s;border-top:3px solid ${s.color}"
            onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform=''">
            <div style="font-size:26px;margin-bottom:6px">${s.icon}</div>
            <div style="font-size:11px;font-weight:900;color:var(--text)">${s.label}</div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
  }
  const subj = IGCSE_SUBJECTS[S.igcseSubject];
  const formulas = IGCSE_FORMULAS[S.igcseSubject];
  if (!subj || !formulas) {
    return `<div style="padding:40px;text-align:center;color:var(--text-muted)">
      <div style="font-size:36px;margin-bottom:12px">📐</div>
      <div style="font-size:15px;font-weight:700">No formula sheet for this subject yet</div>
      <button onclick="S.igcseSubject=null;S.igcseView='formulas';render()" style="margin-top:16px;padding:10px 20px;border-radius:10px;border:1px solid var(--border);background:var(--bg-card);cursor:pointer;font-family:Cairo,sans-serif;font-size:13px;color:var(--text);font-weight:700">← All Subjects</button>
    </div>`;
  }
  const sections = formulas.map(sec => `
    <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:16px;margin-bottom:14px;overflow:hidden">
      <div style="padding:12px 16px;background:${subj.color}0f;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px">
        <span style="font-size:18px">${sec.icon}</span>
        <span style="font-size:13px;font-weight:900;color:${subj.color}">${sec.title}</span>
      </div>
      <div style="padding:12px 16px">
        ${sec.items.map(f => `
        <div style="padding:8px 12px;border-radius:8px;margin-bottom:6px;background:var(--bg);border:1px solid var(--border);font-size:12px;font-family:monospace,Cairo,sans-serif;color:var(--text);line-height:1.6">
          ${f}
        </div>`).join('')}
      </div>
    </div>`).join('');
  return `
<div style="max-width:860px;margin:0 auto;padding:0 0 80px">
  <div style="background:linear-gradient(135deg,${subj.color},${subj.color}bb);padding:18px 16px 22px;border-radius:0 0 22px 22px;margin-bottom:18px">
    <div style="display:flex;gap:8px;margin-bottom:12px">
      <button onclick="S.igcseView='list';render()"
        style="background:#ffffff25;border:1px solid #ffffff35;border-radius:10px;padding:5px 12px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700">
        ← Back
      </button>
      <button onclick="S.igcseSubject=null;S.igcseView='formulas';render()"
        style="background:#ffffff15;border:1px solid #ffffff25;border-radius:10px;padding:5px 12px;color:#ffffffcc;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700">
        📐 All Subjects
      </button>
    </div>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="font-size:36px">${subj.icon}</div>
      <div>
        <div style="font-size:18px;font-weight:900;color:#fff">📐 Formula Sheet</div>
        <div style="font-size:11px;color:#ffffffaa">${subj.label} — IGCSE · ${formulas.length} sections · ${formulas.reduce((a,s)=>a+s.items.length,0)} formulas</div>
      </div>
    </div>
  </div>
  <div style="padding:0 12px">
    <div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap">
      <button onclick="chatWith('${subj.label} IGCSE','Explain how to use the key formulas for IGCSE ${subj.label} with worked examples for each')"
        style="padding:8px 14px;border-radius:10px;border:none;background:var(--primary);color:#fff;cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif">
        🤖 AI: Walk me through these formulas
      </button>
      <button onclick="S.screen='flashcards';S.subject='${subj.label} IGCSE formulas';doGenerateFlashcards()"
        style="padding:8px 14px;border-radius:10px;border:1px solid var(--border);background:var(--bg-card);color:var(--text);cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif">
        🗂️ Formula Flashcards
      </button>
    </div>
    ${sections}
    <div style="padding:14px;background:#F59E0B0f;border-radius:12px;border:1px solid #F59E0B25;font-size:12px;color:var(--text-muted)">
      ⚠️ <strong>Exam note:</strong> Some formulas are given in the exam — always check your syllabus formula sheet. Learn which ones you must memorise.
    </div>
  </div>
</div>`;
}


/* ═══════════════════════════════════════════════════════════════════
   Revision Planner
   ═══════════════════════════════════════════════════════════════════ */
function tplIGCSEPlanner() {
  const examDate = S.igcseExamDate || '';
  const today = new Date(); today.setHours(0,0,0,0);
  const daysLeft = examDate
    ? Math.max(0, Math.round((new Date(examDate) - today) / 86400000))
    : 0;

  const allPending = [];
  for (const [sk, subj] of Object.entries(IGCSE_SUBJECTS)) {
    for (const b of subj.boards) {
      const chs = subj.chapters[b] || [];
      chs.forEach((ch, ci) => {
        ch.topics.forEach((tp, ti) => {
          const pk = sk + '|' + b + '|' + tp.title;
          const status = (S.igcseProgress || {})[pk] || '';
          if (status !== 'mastered') allPending.push({ sk, b, subj, ch, ci, tp, ti, status, pk });
        });
      });
    }
  }

  const total  = allPending.length;
  const perDay = daysLeft > 0 ? Math.ceil(total / daysLeft) : 0;
  const reviewFirst = allPending.filter(x => x.status === 'review');
  const unstudied   = allPending.filter(x => !x.status);
  const studied     = allPending.filter(x => x.status === 'studied');
  const masteredCnt = Object.values(S.igcseProgress || {}).filter(v => v === 'mastered').length;

  let scheduleRows = '';
  if (daysLeft > 0 && total > 0) {
    const ordered = [...reviewFirst, ...unstudied, ...studied];
    const days = Math.min(7, daysLeft);
    let ptr = 0;
    for (let d = 0; d < days; d++) {
      const date = new Date(today); date.setDate(today.getDate() + d);
      const slice = ordered.slice(ptr, ptr + perDay); ptr += perDay;
      if (!slice.length) break;
      const dayLabel = d === 0 ? 'Today' : d === 1 ? 'Tomorrow'
        : date.toLocaleDateString('en-GB', { weekday:'short', month:'short', day:'numeric' });
      scheduleRows += '<div style="margin-bottom:14px">'
        + '<div style="font-size:10px;font-weight:900;color:var(--text-muted);letter-spacing:1.5px;margin-bottom:6px">' + dayLabel.toUpperCase() + '</div>'
        + slice.map(x => {
            const sc = x.status==='review'?'#EF4444':x.status==='studied'?'#3B82F6':'var(--text-muted)';
            const si = x.status==='review'?'⚠️':x.status==='studied'?'📖':'○';
            return '<div onclick="S.igcseSubject=\'' + x.sk + '\';S.igcseBoard=\'' + x.b + '\';S.igcseChapter=' + x.ci + ';S.igcseTopic=' + x.ti + ';S.igcseTab=\'notes\';S.igcseView=\'list\';render()"'
              + ' style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--bg-card);border-radius:10px;margin-bottom:5px;cursor:pointer;border:1px solid var(--border);border-left:4px solid ' + x.subj.color + '">'
              + '<span style="font-size:16px">' + x.subj.icon + '</span>'
              + '<div style="flex:1;min-width:0"><div style="font-size:12px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + x.tp.title + '</div>'
              + '<div style="font-size:10px;color:var(--text-muted)">' + x.subj.label + ' · ' + x.b.toUpperCase() + '</div></div>'
              + '<span style="font-size:12px;color:' + sc + '">' + si + '</span></div>';
          }).join('')
        + '</div>';
    }
  }

  const urgency = '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">'
    + '<div style="flex:1;min-width:80px;padding:10px;border-radius:12px;background:#EF444418;border:1px solid #EF444430;text-align:center"><div style="font-size:20px;font-weight:900;color:#EF4444">' + reviewFirst.length + '</div><div style="font-size:9px;color:#EF4444;font-weight:700">⚠️ REVIEW</div></div>'
    + '<div style="flex:1;min-width:80px;padding:10px;border-radius:12px;background:var(--bg-card);border:1px solid var(--border);text-align:center"><div style="font-size:20px;font-weight:900;color:var(--text)">' + unstudied.length + '</div><div style="font-size:9px;color:var(--text-muted);font-weight:700">○ NOT STARTED</div></div>'
    + '<div style="flex:1;min-width:80px;padding:10px;border-radius:12px;background:#3B82F618;border:1px solid #3B82F630;text-align:center"><div style="font-size:20px;font-weight:900;color:#3B82F6">' + studied.length + '</div><div style="font-size:9px;color:#3B82F6;font-weight:700">📖 STUDIED</div></div>'
    + '<div style="flex:1;min-width:80px;padding:10px;border-radius:12px;background:#10B98118;border:1px solid #10B98130;text-align:center"><div style="font-size:20px;font-weight:900;color:#10B981">' + masteredCnt + '</div><div style="font-size:9px;color:#10B981;font-weight:700">🏆 MASTERED</div></div>'
    + '</div>';

  const dateMin = new Date().toISOString().split('T')[0];
  const daysHtml = daysLeft > 0
    ? '<div style="display:flex;gap:10px;margin-top:12px">'
      + '<div style="flex:1;text-align:center;padding:12px;background:' + (daysLeft<14?'#EF444418':'#10B98118') + ';border-radius:12px;border:1px solid ' + (daysLeft<14?'#EF444430':'#10B98130') + '"><div style="font-size:24px;font-weight:900;color:' + (daysLeft<14?'#EF4444':'#10B981') + '">' + daysLeft + '</div><div style="font-size:10px;color:var(--text-muted)">days left</div></div>'
      + '<div style="flex:1;text-align:center;padding:12px;background:var(--bg);border-radius:12px;border:1px solid var(--border)"><div style="font-size:24px;font-weight:900;color:var(--text)">' + perDay + '</div><div style="font-size:10px;color:var(--text-muted)">topics / day</div></div>'
      + '<div style="flex:1;text-align:center;padding:12px;background:var(--bg);border-radius:12px;border:1px solid var(--border)"><div style="font-size:24px;font-weight:900;color:var(--text)">' + total + '</div><div style="font-size:10px;color:var(--text-muted)">to revise</div></div>'
      + '</div>'
    : '';

  const schedHtml = daysLeft > 0
    ? '<div style="font-size:10px;font-weight:900;color:var(--text-muted);letter-spacing:1.5px;margin-bottom:12px">7-DAY PREVIEW — tap any topic to study it now</div>'
      + (scheduleRows || '<div style="text-align:center;padding:30px;color:var(--text-muted)">🎉 All topics mastered!</div>')
    : '<div style="text-align:center;padding:40px 20px;background:var(--bg-card);border-radius:16px;border:1px solid var(--border)"><div style="font-size:44px;margin-bottom:12px">📅</div><div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:6px">Set your exam date above</div><div style="font-size:12px;color:var(--text-muted)">Your personalised revision schedule will appear here</div></div>';

  return '<div style="max-width:620px;margin:0 auto;padding:0 0 80px">'
    + '<div style="display:flex;align-items:center;gap:10px;padding:14px;margin-bottom:6px">'
    + '<button onclick="S.igcseView=\'list\';render()" style="width:34px;height:34px;border-radius:50%;border:none;background:var(--bg-card);cursor:pointer;font-size:18px;color:var(--text)">←</button>'
    + '<div style="flex:1"><div style="font-size:16px;font-weight:900;color:var(--text)">📅 Revision Planner</div>'
    + '<div style="font-size:11px;color:var(--text-muted)">Smart daily schedule based on your progress</div></div></div>'
    + '<div style="padding:0 14px">'
    + '<div style="background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:16px;margin-bottom:14px">'
    + '<div style="font-size:10px;font-weight:900;color:var(--text-muted);letter-spacing:1px;margin-bottom:8px">📅 YOUR EXAM DATE</div>'
    + '<input type="date" value="' + (S.igcseExamDate||'') + '" min="' + dateMin + '" onchange="S.igcseExamDate=this.value;saveLocal();render()" style="width:100%;padding:10px 14px;border-radius:10px;border:1.5px solid var(--border);background:var(--bg);color:var(--text);font-size:14px;font-family:Cairo,sans-serif;box-sizing:border-box"/>'
    + daysHtml
    + '</div>'
    + urgency
    + schedHtml
    + '</div></div>';
}

/* ═══════════════════════════════════════════════════════════════════
   Bookmarks
   ═══════════════════════════════════════════════════════════════════ */
function tplIGCSEBookmarks() {
  const bkKeys = Object.keys(S.igcseProgress || {}).filter(k => k.startsWith('bk|'));
  const bookmarks = bkKeys.map(k => {
    const parts = k.split('|');
    const sk = parts[1], b = parts[2], title = parts.slice(3).join('|');
    const subj = IGCSE_SUBJECTS[sk];
    if (!subj) return null;
    const chs = subj.chapters[b] || [];
    let ci = -1, ti = -1;
    chs.forEach((ch, _ci) => ch.topics.forEach((tp, _ti) => { if (tp.title === title) { ci=_ci; ti=_ti; } }));
    if (ci === -1) return null;
    return { sk, b, title, subj, ci, ti, k };
  }).filter(Boolean);

  const items = bookmarks.length
    ? bookmarks.map(bk =>
        '<div style="display:flex;align-items:center;gap:12px;padding:14px;background:var(--bg-card);border-radius:14px;margin-bottom:8px;border:1px solid var(--border);border-left:4px solid ' + bk.subj.color + '">'
        + '<span style="font-size:22px">' + bk.subj.icon + '</span>'
        + '<div style="flex:1;min-width:0;cursor:pointer" onclick="S.igcseSubject=\'' + bk.sk + '\';S.igcseBoard=\'' + bk.b + '\';S.igcseChapter=' + bk.ci + ';S.igcseTopic=' + bk.ti + ';S.igcseTab=\'notes\';S.igcseView=\'list\';render()">'
        + '<div style="font-size:13px;font-weight:800;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + bk.title + '</div>'
        + '<div style="font-size:10px;color:var(--text-muted)">' + bk.subj.label + ' · ' + bk.b.toUpperCase() + '</div></div>'
        + '<button onclick="S.igcseSubject=\'' + bk.sk + '\';S.igcseBoard=\'' + bk.b + '\';S.igcseChapter=' + bk.ci + ';S.igcseTopic=' + bk.ti + ';S.igcseTab=\'notes\';S.igcseView=\'list\';render()" style="padding:6px 12px;border-radius:8px;border:none;background:' + bk.subj.color + ';color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">Study →</button>'
        + '<button onclick="delete S.igcseProgress[\'' + bk.k + '\'];saveLocal();render()" style="padding:6px 10px;border-radius:8px;border:1px solid var(--border);background:var(--bg);color:var(--text-muted);cursor:pointer;font-size:14px;line-height:1">×</button>'
        + '</div>'
      ).join('')
    : '<div style="text-align:center;padding:50px 20px"><div style="font-size:52px;margin-bottom:12px">⭐</div>'
      + '<div style="font-size:15px;font-weight:700;color:var(--text);margin-bottom:6px">No bookmarks yet</div>'
      + '<div style="font-size:12px;color:var(--text-muted)">Tap ☆ on any topic page to save it here for quick access</div></div>';

  return '<div style="max-width:620px;margin:0 auto;padding:0 0 80px">'
    + '<div style="display:flex;align-items:center;gap:10px;padding:14px;margin-bottom:6px">'
    + '<button onclick="S.igcseView=\'list\';render()" style="width:34px;height:34px;border-radius:50%;border:none;background:var(--bg-card);cursor:pointer;font-size:18px;color:var(--text)">←</button>'
    + '<div style="flex:1"><div style="font-size:16px;font-weight:900;color:var(--text)">⭐ Bookmarks</div>'
    + '<div style="font-size:11px;color:var(--text-muted)">' + bookmarks.length + ' saved topic' + (bookmarks.length===1?'':'s') + '</div></div></div>'
    + '<div style="padding:0 14px">' + items + '</div></div>';
}

function tplIGCSEHub() {
  const board = IGCSE_BOARDS[S.igcseBoard];
  const q = (S.igcseSearch||'').toLowerCase().trim();

  // Stats
  const allSubjects = Object.values(IGCSE_SUBJECTS);
  const totalTopics = allSubjects.reduce((a,s)=>a+((s.chapters.cie||[]).reduce((b,c)=>b+c.topics.length,0)),0);
  const doneCnt = Object.keys(S.igcseDone||{}).length;

  // Board cards
  const boardCards = Object.entries(IGCSE_BOARDS).map(([k,b]) => {
    const active = S.igcseBoard === k;
    const cnt = Object.values(IGCSE_SUBJECTS).filter(s=>s.boards.includes(k)).length;
    return `
    <div onclick="S.igcseBoard='${k}';S.igcseSearch='';render()"
      style="flex:1;min-width:100px;padding:14px 10px;border-radius:16px;cursor:pointer;text-align:center;transition:.2s;
             ${active?`background:${b.color};box-shadow:0 4px 20px ${b.color}55;`:'background:var(--bg-card);border:2px solid var(--border);'}">
      <div style="font-size:22px;margin-bottom:4px">${b.icon}</div>
      <div style="font-size:12px;font-weight:900;color:${active?'#fff':'var(--text)'}">${b.short}</div>
      <div style="font-size:10px;color:${active?'#ffffff99':'var(--text-muted)'};margin-top:2px">${cnt} subjects</div>
    </div>`;
  }).join('');

  // Subject cards with search filter
  const filtered = Object.entries(IGCSE_SUBJECTS)
    .filter(([,s]) => s.boards.includes(S.igcseBoard))
    .filter(([,s]) => !q || s.label.toLowerCase().includes(q) || s.arabic.includes(q));

  // Topic-level search results
  let topicSearchResults = [];
  if (q && filtered.length === 0) {
    Object.entries(IGCSE_SUBJECTS).forEach(([sk,subj])=>{
      if(!subj.boards.includes(S.igcseBoard)) return;
      const chs = subj.chapters[S.igcseBoard]||[];
      chs.forEach((ch,ci)=>{
        ch.topics.forEach((tp,ti)=>{
          if(tp.title.toLowerCase().includes(q)||(tp.points&&tp.points.some(p=>p.toLowerCase().includes(q)))){
            topicSearchResults.push({sk,subj,ch,tp,ci,ti});
          }
        });
      });
    });
  }

  const subjectCards = filtered.map(([k,subj]) => {
    const chapters = subj.chapters[S.igcseBoard]||[];
    const topicCount = chapters.reduce((a,c)=>a+c.topics.length,0);
    const doneCount = chapters.reduce((a,c,ci)=>a+c.topics.filter((_,ti)=>S.igcseDone[`${k}-${ci}-${ti}`]).length,0);
    const pct = topicCount ? Math.round(doneCount/topicCount*100) : 0;
    const statusIcon = pct===100?'✅':pct>60?'🔥':pct>0?'📖':'🆕';
    const statusLabel = pct===100?'مكتمل':pct>0?pct+'%':'ابدأ الآن';
    // SVG ring
    const r=16,circ=2*Math.PI*r,dash=circ*pct/100,gap=circ-dash;
    const ringColor = pct===100?'#10B981':pct>0?subj.color:'#334155';
    return `
    <div onclick="S.igcseSubject='${k}';S.igcseChapter=null;S.igcseTopic=null;S.igcseSearch='';render()"
      style="background:linear-gradient(145deg,${subj.color}22,${subj.color}08);border:1.5px solid ${subj.color}33;
             border-radius:20px;padding:16px 14px;cursor:pointer;transition:.25s;position:relative;overflow:hidden;"
      onmouseover="this.style.transform='translateY(-4px) scale(1.02)';this.style.boxShadow='0 10px 30px ${subj.color}40';this.style.borderColor='${subj.color}'"
      onmouseout="this.style.transform='';this.style.boxShadow='';this.style.borderColor='${subj.color}33'">
      <!-- Decorative circle bg -->
      <div style="position:absolute;top:-20px;right:-20px;width:80px;height:80px;border-radius:50%;background:${subj.color}12;pointer-events:none"></div>
      <!-- Header row -->
      <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:10px">
        <div style="font-size:34px;line-height:1">${subj.icon}</div>
        <!-- Progress ring -->
        <svg width="40" height="40" style="transform:rotate(-90deg);flex-shrink:0">
          <circle cx="20" cy="20" r="${r}" fill="none" stroke="#1e293b" stroke-width="3"/>
          <circle cx="20" cy="20" r="${r}" fill="none" stroke="${ringColor}" stroke-width="3"
            stroke-dasharray="${dash.toFixed(1)} ${gap.toFixed(1)}" stroke-linecap="round"/>
        </svg>
      </div>
      <div style="font-size:14px;font-weight:900;color:var(--text);line-height:1.3;margin-bottom:2px">${subj.label}</div>
      <div style="font-size:11px;color:${subj.color};font-weight:700;margin-bottom:8px">${subj.arabic}</div>
      <div style="display:flex;justify-content:space-between;align-items:center">
        <span style="font-size:11px;background:${subj.color}20;color:${subj.color};padding:3px 9px;border-radius:20px;font-weight:800">${topicCount} مواضيع</span>
        <span style="font-size:11px;color:${pct===100?'#10B981':pct>0?subj.color:'var(--text-muted)'};font-weight:800">${statusIcon} ${statusLabel}</span>
      </div>
    </div>`;
  }).join('');

  return `
<div style="max-width:920px;margin:0 auto;padding:0 0 80px">
  <!-- Hero Header -->
  <div style="background:linear-gradient(135deg,${board.color} 0%,${board.accent} 100%);padding:24px 20px 28px;border-radius:0 0 28px 28px;margin-bottom:20px;position:relative;overflow:hidden">
    <div style="position:absolute;top:-30px;right:-30px;width:160px;height:160px;border-radius:50%;background:#ffffff0d"></div>
    <div style="position:absolute;bottom:-40px;left:-20px;width:120px;height:120px;border-radius:50%;background:#ffffff08"></div>
    <div style="position:relative;z-index:1">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
        <div style="display:inline-block;background:#ffffff20;border-radius:20px;padding:3px 12px;font-size:10px;color:#ffffffcc;font-weight:800;letter-spacing:2px">IGCSE REVISION PLATFORM</div>
        <button onclick="S.darkMode=!S.darkMode;document.getElementById('app').className=S.darkMode?'':'light';saveLocal();render()"
          title="Toggle dark/light mode"
          style="background:#ffffff25;border:none;border-radius:20px;padding:5px 12px;color:#fff;cursor:pointer;font-size:13px;font-weight:700;font-family:Cairo,sans-serif">
          ${S.darkMode?'☀️ Light':'🌙 Dark'}
        </button>
        <button onclick="toggleIGCSELang()"
          title="Toggle Arabic/English"
          style="background:#ffffff25;border:none;border-radius:20px;padding:5px 12px;color:#fff;cursor:pointer;font-size:13px;font-weight:700;font-family:Cairo,sans-serif">
          ${S.igcseLang==='ar'?'🇬🇧 EN':'🇦🇪 عربي'}
        </button>
      </div>
      <div style="font-size:26px;font-weight:900;color:#fff;margin-bottom:6px">🎓 IGCSE Hub</div>
      <div style="display:flex;gap:16px;flex-wrap:wrap">
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#fff">${Object.keys(IGCSE_SUBJECTS).length}</div><div style="font-size:10px;color:#ffffffaa">Subjects</div></div>
        <div style="width:1px;background:#ffffff30"></div>
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#fff">${totalTopics}+</div><div style="font-size:10px;color:#ffffffaa">Topics</div></div>
        <div style="width:1px;background:#ffffff30"></div>
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#fff">${doneCnt}</div><div style="font-size:10px;color:#ffffffaa">Done ✓</div></div>
        <div style="width:1px;background:#ffffff30"></div>
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#10B981">${Object.values(S.igcseProgress||{}).filter(v=>v==='mastered').length}</div><div style="font-size:10px;color:#ffffffaa">🏆 Mastered</div></div>
        <div style="width:1px;background:#ffffff30"></div>
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#F59E0B">${Object.values(S.igcseProgress||{}).filter(v=>v==='review').length}</div><div style="font-size:10px;color:#ffffffaa">⚠️ Review</div></div>
        <div style="width:1px;background:#ffffff30"></div>
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#fff">3</div><div style="font-size:10px;color:#ffffffaa">Boards</div></div>
        <div style="width:1px;background:#ffffff30"></div>
        <div style="text-align:center"><div style="font-size:20px;font-weight:900;color:#fff">🔥${(S.igcseStreak||{count:0}).count}</div><div style="font-size:10px;color:#ffffffaa">Day Streak</div></div>
      </div>
    </div>
  </div>

  <!-- Board Selector -->
  <div style="padding:0 14px;margin-bottom:18px">
    <div style="font-size:10px;color:var(--text-muted);font-weight:800;letter-spacing:1.5px;margin-bottom:10px">EXAM BOARD</div>
    <div style="display:flex;gap:10px">${boardCards}</div>
  </div>

  <!-- ══ PAST PAPERS BANNER ══ -->
  <div style="padding:0 14px;margin-bottom:18px">
    <div style="background:linear-gradient(135deg,#DC2626,#B91C1C);border-radius:18px;padding:18px 18px 14px;position:relative;overflow:hidden">
      <div style="position:absolute;top:-20px;right:-20px;width:100px;height:100px;border-radius:50%;background:#ffffff0d"></div>
      <div style="position:absolute;bottom:-30px;left:-10px;width:80px;height:80px;border-radius:50%;background:#ffffff08"></div>
      <div style="position:relative;z-index:1">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px">
          <div style="width:44px;height:44px;border-radius:12px;background:#ffffff20;display:flex;align-items:center;justify-content:center;font-size:24px;flex-shrink:0">📄</div>
          <div>
            <div style="font-size:17px;font-weight:900;color:#fff">Past Papers</div>
            <div style="font-size:11px;color:#ffaaaa;margin-top:1px">Official exam papers · CIE · Edexcel · Oxford AQA</div>
          </div>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:7px">
          ${Object.entries(IGCSE_SUBJECTS).filter(([,s])=>s.boards.includes(S.igcseBoard)).map(([sk,subj])=>`
          <button onclick="S.igcseSubject='${sk}';S.igcseView='papers';S.igcsePpFilter='all';S.igcsePpType='all';render()"
            style="display:flex;align-items:center;gap:5px;padding:6px 11px;border-radius:20px;border:1.5px solid #ffffff30;
                   background:#ffffff15;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif;
                   transition:.15s;white-space:nowrap"
            onmouseover="this.style.background='#ffffff30'" onmouseout="this.style.background='#ffffff15'">
            ${subj.icon} ${subj.label}
          </button>`).join('')}
        </div>
        <div style="margin-top:12px;padding-top:10px;border-top:1px solid #ffffff20;display:flex;gap:8px;flex-wrap:wrap">
          <a href="https://www.cambridgeinternational.org/exam-administration/cambridge-exams/past-papers/" target="_blank" rel="noopener"
            style="display:flex;align-items:center;gap:5px;padding:7px 14px;border-radius:10px;background:#ffffff20;border:1px solid #ffffff30;
                   color:#fff;text-decoration:none;font-size:11px;font-weight:800;font-family:Cairo,sans-serif">
            🎓 Cambridge (CIE)
          </a>
          <a href="https://qualifications.pearson.com/en/support/support-topics/exams/past-papers.html" target="_blank" rel="noopener"
            style="display:flex;align-items:center;gap:5px;padding:7px 14px;border-radius:10px;background:#ffffff20;border:1px solid #ffffff30;
                   color:#fff;text-decoration:none;font-size:11px;font-weight:800;font-family:Cairo,sans-serif">
            📘 Edexcel
          </a>
          <a href="https://www.oxfordaqaexams.org.uk/resources/past-papers/" target="_blank" rel="noopener"
            style="display:flex;align-items:center;gap:5px;padding:7px 14px;border-radius:10px;background:#ffffff20;border:1px solid #ffffff30;
                   color:#fff;text-decoration:none;font-size:11px;font-weight:800;font-family:Cairo,sans-serif">
            📙 Oxford AQA
          </a>
        </div>
      </div>
    </div>
  </div>

  <!-- Search -->
  <div style="padding:0 14px;margin-bottom:16px">
    <div style="display:flex;gap:8px;align-items:center">
      <div style="position:relative;flex:1">
        <input id="igcse-search" type="text" placeholder="Search subjects…" value="${S.igcseSearch||''}"
          oninput="S.igcseSearch=this.value;render()"
          style="width:100%;padding:10px 16px 10px 40px;border-radius:12px;border:1px solid var(--border);background:var(--bg-card);color:var(--text);font-size:13px;font-family:Cairo,sans-serif;box-sizing:border-box;outline:none">
        <span style="position:absolute;left:14px;top:50%;transform:translateY(-50%);font-size:16px;pointer-events:none">🔍</span>
        ${q?`<button onclick="S.igcseSearch='';render()" style="position:absolute;right:12px;top:50%;transform:translateY(-50%);background:none;border:none;cursor:pointer;font-size:16px;color:var(--text-muted)">✕</button>`:''}
      </div>
      <button onclick="S.igcseView='search';S.igcseSearchBoard='all';render()"
        style="white-space:nowrap;padding:10px 13px;border-radius:12px;border:1.5px solid #6366F1;background:#6366F118;
               color:#6366F1;cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:800;transition:.15s"
        onmouseover="this.style.background='#6366F1';this.style.color='#fff'"
        onmouseout="this.style.background='#6366F118';this.style.color='#6366F1'">
        🔎 All Boards
      </button>
      <button onclick="S.igcseView='planner';render()"
        style="white-space:nowrap;padding:10px 13px;border-radius:12px;border:1.5px solid #10B981;background:#10B98118;
               color:#10B981;cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:800;transition:.15s"
        onmouseover="this.style.background='#10B981';this.style.color='#fff'"
        onmouseout="this.style.background='#10B98118';this.style.color='#10B981'">
        📅 Revision Planner
      </button>
      <button onclick="S.igcseView='bookmarks';render()"
        style="white-space:nowrap;padding:10px 13px;border-radius:12px;border:1.5px solid #F59E0B;background:#F59E0B18;
               color:#F59E0B;cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:800;transition:.15s"
        onmouseover="this.style.background='#F59E0B';this.style.color='#fff'"
        onmouseout="this.style.background='#F59E0B18';this.style.color='#F59E0B'">
        ⭐ Bookmarks
      </button>
      <button onclick="S.igcseView='mockexam';S.igcseMockExam=null;render()"
        style="white-space:nowrap;padding:10px 13px;border-radius:12px;border:1.5px solid #8B5CF6;background:#8B5CF618;
               color:#8B5CF6;cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:800;transition:.15s"
        onmouseover="this.style.background='#8B5CF6';this.style.color='#fff'"
        onmouseout="this.style.background='#8B5CF618';this.style.color='#8B5CF6'">
        🎓 Mock Exam
      </button>
      <button onclick="S.igcseSubject=null;S.igcseView='formulas';render()"
        style="white-space:nowrap;padding:10px 13px;border-radius:12px;border:1.5px solid #EC4899;background:#EC489918;
               color:#EC4899;cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:800;transition:.15s"
        onmouseover="this.style.background='#EC4899';this.style.color='#fff'"
        onmouseout="this.style.background='#EC489918';this.style.color='#EC4899'">
        📐 Formulas
      </button>
      <button onclick="S.igcseView='stats';render()"
        style="white-space:nowrap;padding:10px 13px;border-radius:12px;border:1.5px solid #0EA5E9;background:#0EA5E918;
               color:#0EA5E9;cursor:pointer;font-family:Cairo,sans-serif;font-size:11px;font-weight:800;transition:.15s"
        onmouseover="this.style.background='#0EA5E9';this.style.color='#fff'"
        onmouseout="this.style.background='#0EA5E918';this.style.color='#0EA5E9'">
        📊 My Stats
      </button>
    </div>
  </div>

  <!-- Subject Grid -->
  <div style="padding:0 14px">
    <div style="font-size:10px;color:var(--text-muted);font-weight:800;letter-spacing:1.5px;margin-bottom:12px">
      ${q?`Results for "${q}" — ${filtered.length} subject(s)`:`ALL SUBJECTS · ${filtered.length} available`}
    </div>
    ${filtered.length?`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:12px">${subjectCards}</div>`
      : topicSearchResults.length ? `
        <div style="font-size:10px;color:var(--text-muted);margin-bottom:8px">Showing topics matching "${q}"</div>
        <div style="display:flex;flex-direction:column;gap:6px">
          ${topicSearchResults.slice(0,12).map(({sk,subj,ch,tp,ci,ti})=>`
          <div onclick="S.igcseSubject='${sk}';S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='notes';S.igcseSearch='';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
            style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;cursor:pointer;transition:.15s;border-left:4px solid ${subj.color}"
            onmouseover="this.style.background='${subj.color}0a'" onmouseout="this.style.background=''">
            <span style="font-size:20px">${subj.icon}</span>
            <div style="flex:1;min-width:0">
              <div style="font-size:12px;font-weight:800;color:var(--text)">${tp.title}</div>
              <div style="font-size:10px;color:var(--text-muted)">${subj.label} › ${ch.title}</div>
            </div>
            <span style="font-size:10px;color:${subj.color};font-weight:800">→</span>
          </div>`).join('')}
          ${topicSearchResults.length>12?`<div style="font-size:11px;color:var(--text-muted);text-align:center;padding:8px">+ ${topicSearchResults.length-12} more results — refine your search</div>`:''}
        </div>`
      :`<div style="text-align:center;padding:40px;color:var(--text-muted)">No results for "${q}"</div>`}
  </div>

  <!-- Exam Countdown + Quick Actions Row -->
  <div style="padding:0 14px;margin-top:20px;display:flex;gap:10px;flex-wrap:wrap">
    <!-- Exam Countdown -->
    <div id="igcse-countdown-card" style="flex:1;min-width:160px;background:linear-gradient(135deg,#7C3AED,#5B21B6);border-radius:14px;padding:14px 16px;color:#fff">
      <div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:#ffffffaa;margin-bottom:6px">📅 EXAM COUNTDOWN</div>
      <div id="igcse-days" style="font-size:28px;font-weight:900">${(()=>{const d=S.igcseExamDate?Math.max(0,Math.ceil((new Date(S.igcseExamDate)-new Date())/(1000*60*60*24))):null;return d!==null?d:'—';})()}</div>
      <div style="font-size:11px;color:#ffffffbb">${S.igcseExamDate?'days until exams':'Set your exam date'}</div>
      <input type="date" value="${S.igcseExamDate||''}" onchange="S.igcseExamDate=this.value;render()"
        style="margin-top:8px;width:100%;padding:4px 8px;border-radius:8px;border:1px solid #ffffff30;background:#ffffff15;color:#fff;font-size:11px;box-sizing:border-box;outline:none;font-family:Cairo,sans-serif">
    </div>
    <!-- Overall Progress -->
    <div style="flex:1;min-width:160px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;padding:14px 16px">
      <div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:var(--text-muted);margin-bottom:6px">📊 OVERALL PROGRESS</div>
      <div style="font-size:28px;font-weight:900;color:${board.color}">${doneCnt}</div>
      <div style="font-size:11px;color:var(--text-muted)">topics completed</div>
      <div style="margin-top:8px;height:6px;background:var(--border);border-radius:3px">
        <div style="height:100%;width:${totalTopics?Math.min(100,Math.round(doneCnt/totalTopics*100)):0}%;background:${board.color};border-radius:3px;transition:.5s"></div>
      </div>
      <div style="font-size:10px;color:var(--text-muted);margin-top:4px">${totalTopics?Math.min(100,Math.round(doneCnt/totalTopics*100)):0}% of ${totalTopics} total topics</div>
    </div>
    <!-- Quick Links -->
    <div style="flex:1;min-width:160px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;padding:14px 16px">
      <div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:var(--text-muted);margin-bottom:10px">⚡ QUICK ACTIONS</div>
      <div style="display:flex;flex-direction:column;gap:7px">
        <button onclick="S.igcseView='mockexam';S.igcseMockExam=null;render()"
          style="padding:7px 10px;border-radius:8px;border:1.5px solid #8B5CF6;background:#8B5CF618;color:#8B5CF6;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif;text-align:left">
          🎓 Mock Exam
        </button>
        <button onclick="chatWith('IGCSE Study Plan','Create a 4-week IGCSE revision plan for: Maths, Physics, Chemistry, Biology, and English. I have 2 hours per day. Include what to revise each week and past paper practice schedule.')"
          style="padding:7px 10px;border-radius:8px;border:1px solid var(--border);background:var(--bg);color:var(--text);cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif;text-align:left">
          📅 AI Study Plan
        </button>
        <button onclick="chatWith('IGCSE Examiner Tips','Give me the top 10 examiner tips that apply to ALL IGCSE subjects — what do Cambridge examiners look for?')"
          style="padding:7px 10px;border-radius:8px;border:1px solid var(--border);background:var(--bg);color:var(--text);cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif;text-align:left">
          💡 Examiner Tips
        </button>
        <button onclick="exportIGCSEProgress()"
          style="padding:7px 10px;border-radius:8px;border:1.5px solid #10B981;background:#10B98118;color:#10B981;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif;text-align:left">
          📊 Export Progress PDF
        </button>
      </div>
    </div>
  </div>

  <!-- Recently Studied -->
  ${(S.igcseRecent&&S.igcseRecent.length)?`
  <div style="padding:0 14px;margin-top:20px">
    <div style="font-size:10px;color:var(--text-muted);font-weight:800;letter-spacing:1.5px;margin-bottom:10px">🕐 RECENTLY STUDIED</div>
    <div style="display:flex;gap:8px;overflow-x:auto;padding-bottom:4px">
      ${(S.igcseRecent||[]).map(r=>`
      <div onclick="S.igcseSubject='${r.sk}';S.igcseChapter=${r.ci};S.igcseTopic=${r.ti};S.igcseTab='notes';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
        style="flex-shrink:0;width:130px;padding:12px 10px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;cursor:pointer;transition:.15s;border-top:3px solid ${r.color}"
        onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform=''">
        <div style="font-size:20px;margin-bottom:4px">${r.icon}</div>
        <div style="font-size:10px;font-weight:900;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${r.topicTitle}</div>
        <div style="font-size:9px;color:var(--text-muted);margin-top:2px">${r.label}</div>
      </div>`).join('')}
    </div>
  </div>
  `:''}

  <!-- Spaced Repetition Panel -->
  ${(()=>{
    const today = new Date().toISOString().slice(0,10);
    const ls = S.igcseLastStudied || {};
    const due = [];
    Object.entries(IGCSE_SUBJECTS).forEach(([sk,subj])=>{
      if(!subj.boards.includes(S.igcseBoard)) return;
      const chs = subj.chapters[S.igcseBoard]||[];
      chs.forEach((ch,ci)=>{
        ch.topics.forEach((tp,ti)=>{
          const key = `${sk}|${S.igcseBoard}|${tp.title}`;
          const lastDate = ls[key];
          if(!lastDate) return;
          const daysSince = Math.floor((new Date(today)-new Date(lastDate))/(1000*60*60*24));
          const prog = (S.igcseProgress||{})[key] || '';
          const threshold = prog==='mastered' ? 14 : prog==='studied' ? 7 : 3;
          if(daysSince >= threshold) due.push({sk,subj,ch,tp,ci,ti,daysSince,key});
        });
      });
    });
    if(!due.length) return '';
    due.sort((a,b)=>b.daysSince-a.daysSince);
    return `
    <div style="margin:16px 14px 0;background:var(--bg-card);border:1px solid #F59E0B44;border-radius:14px;padding:14px 16px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:#F59E0B">🔁 DUE FOR REVIEW (${due.length})</div>
        <div style="font-size:9px;color:var(--text-muted)">Spaced repetition</div>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px">
        ${due.slice(0,5).map(({sk,subj,tp,ci,ti,daysSince})=>`
        <div onclick="S.igcseSubject='${sk}';S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='notes';render()"
          style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:10px;cursor:pointer;background:var(--bg);border:1px solid #F59E0B33;transition:.15s"
          onmouseover="this.style.borderColor='#F59E0B'" onmouseout="this.style.borderColor='#F59E0B33'">
          <span style="font-size:16px">${subj.icon}</span>
          <div style="flex:1;min-width:0">
            <div style="font-size:11px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${tp.title}</div>
            <div style="font-size:10px;color:var(--text-muted)">${subj.label}</div>
          </div>
          <span style="font-size:10px;color:#F59E0B;font-weight:800;white-space:nowrap">${daysSince}d ago</span>
        </div>`).join('')}
        ${due.length>5?`<div style="text-align:center;font-size:10px;color:var(--text-muted);padding:4px">+${due.length-5} more due for review</div>`:''}
      </div>
    </div>`;
  })()}

  <!-- Weak Spots Panel -->
  ${(()=>{
    const done = S.igcseDone||{};
    const weak = [];
    Object.entries(IGCSE_SUBJECTS).forEach(([sk,subj])=>{
      if(!subj.boards.includes(S.igcseBoard)) return;
      const chs = subj.chapters[S.igcseBoard]||[];
      chs.forEach((ch,ci)=>{
        ch.topics.forEach((tp,ti)=>{
          if(!done[`${sk}-${ci}-${ti}`]) weak.push({sk,subj,ch,tp,ci,ti});
        });
      });
    });
    if(!weak.length) return `
    <div style="margin:16px 14px 0;padding:14px 16px;background:#10B98118;border-radius:14px;border:1px solid #10B98140;display:flex;align-items:center;gap:12px">
      <div style="font-size:28px">🎉</div>
      <div>
        <div style="font-size:13px;font-weight:900;color:#10B981">All topics completed!</div>
        <div style="font-size:11px;color:var(--text-muted);margin-top:2px">Outstanding work — you've covered everything. Focus on past papers now!</div>
      </div>
    </div>`;
    const items = weak.slice(0,6).map(({sk,subj,tp,ci,ti})=>`
      <div onclick="S.igcseSubject='${sk}';S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='notes';render()"
        style="display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:10px;cursor:pointer;background:var(--bg);border:1px solid var(--border);transition:.15s"
        onmouseover="this.style.borderColor='${subj.color}'" onmouseout="this.style.borderColor=''">
        <span style="font-size:16px">${subj.icon}</span>
        <div style="flex:1;min-width:0">
          <div style="font-size:11px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${tp.title}</div>
          <div style="font-size:10px;color:var(--text-muted)">${subj.label}</div>
        </div>
        <span style="font-size:10px;color:${subj.color};font-weight:800">→</span>
      </div>`).join('');
    return `
    <div style="margin:16px 14px 0;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;padding:14px 16px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:var(--text-muted)">📌 TOPICS TO STUDY (${weak.length} remaining)</div>
        ${weak.length>6?`<span style="font-size:10px;color:${board.color};font-weight:700">${weak.length-6} more...</span>`:''}
      </div>
      <div style="display:flex;flex-direction:column;gap:6px">${items}</div>
    </div>`;
  })()}

  <!-- Study Planner -->
  ${(()=>{
    if (!S.igcseExamDate) return `
    <div style="margin:16px 14px 0;padding:14px 16px;background:var(--bg-card);border:1px dashed var(--border);border-radius:14px;text-align:center">
      <div style="font-size:20px;margin-bottom:4px">📅</div>
      <div style="font-size:12px;font-weight:800;color:var(--text);margin-bottom:2px">Study Planner</div>
      <div style="font-size:11px;color:var(--text-muted)">Set your exam date above to get a personalised daily study plan</div>
    </div>`;
    const daysLeft = Math.max(0, Math.ceil((new Date(S.igcseExamDate) - new Date()) / 86400000));
    const done = S.igcseDone || {};
    const remaining = [];
    Object.entries(IGCSE_SUBJECTS).forEach(([sk, subj]) => {
      if (!subj.boards.includes(S.igcseBoard)) return;
      const chs = subj.chapters[S.igcseBoard] || [];
      chs.forEach((ch, ci) => ch.topics.forEach((tp, ti) => {
        if (!done[`${sk}-${ci}-${ti}`]) remaining.push({sk, subj, ch, tp, ci, ti});
      }));
    });
    const total = remaining.length;
    if (total === 0) return '';
    // How many topics per day needed
    const perDay = daysLeft > 0 ? Math.ceil(total / daysLeft) : total;
    // Today's recommended topics — first perDay from remaining
    const todayTopics = remaining.slice(0, Math.min(perDay, 4));
    const urgency = daysLeft <= 7 ? '#EF4444' : daysLeft <= 21 ? '#F59E0B' : '#10B981';
    const urgencyLabel = daysLeft <= 7 ? '🚨 Final stretch!' : daysLeft <= 21 ? '⚡ Keep pushing' : '✅ On track';
    return `
    <div style="margin:16px 14px 0;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;padding:14px 16px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:var(--text-muted)">📅 STUDY PLANNER</div>
        <span style="font-size:10px;color:${urgency};font-weight:800;padding:2px 8px;background:${urgency}18;border-radius:6px">${urgencyLabel}</span>
      </div>
      <div style="display:flex;gap:10px;margin-bottom:10px">
        <div style="flex:1;text-align:center;padding:8px;background:${urgency}0f;border-radius:10px;border:1px solid ${urgency}25">
          <div style="font-size:20px;font-weight:900;color:${urgency}">${daysLeft}</div>
          <div style="font-size:9px;color:var(--text-muted);font-weight:700">DAYS LEFT</div>
        </div>
        <div style="flex:1;text-align:center;padding:8px;background:var(--bg);border-radius:10px;border:1px solid var(--border)">
          <div style="font-size:20px;font-weight:900;color:var(--text)">${total}</div>
          <div style="font-size:9px;color:var(--text-muted);font-weight:700">TOPICS LEFT</div>
        </div>
        <div style="flex:1;text-align:center;padding:8px;background:${board.color}0f;border-radius:10px;border:1px solid ${board.color}25">
          <div style="font-size:20px;font-weight:900;color:${board.color}">${perDay}</div>
          <div style="font-size:9px;color:var(--text-muted);font-weight:700">PER DAY</div>
        </div>
      </div>
      <div style="font-size:10px;font-weight:800;color:var(--text-muted);letter-spacing:1px;margin-bottom:6px">TODAY'S TOPICS</div>
      <div style="display:flex;flex-direction:column;gap:5px">
        ${todayTopics.map(({sk,subj,tp,ci,ti}) => `
        <div onclick="S.igcseSubject='${sk}';S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='notes';render()"
          style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;cursor:pointer;background:${subj.color}08;border:1px solid ${subj.color}25;transition:.15s"
          onmouseover="this.style.background='${subj.color}18'" onmouseout="this.style.background='${subj.color}08'">
          <span style="font-size:16px">${subj.icon}</span>
          <div style="flex:1;min-width:0">
            <div style="font-size:11px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${tp.title}</div>
            <div style="font-size:10px;color:var(--text-muted)">${subj.label}</div>
          </div>
          <span style="font-size:18px;color:${subj.color}">▶</span>
        </div>`).join('')}
      </div>
      ${perDay > 4 ? `<div style="margin-top:8px;font-size:10px;color:var(--text-muted);text-align:center">+${perDay-4} more topics needed today · <span style="color:${urgency};font-weight:700">Study ${perDay}/day to finish on time</span></div>` : ''}
    </div>`;
  })()}

  <!-- Tips Banner -->
  <div style="margin:16px 14px 0;padding:14px 16px;background:${board.color}0c;border-radius:14px;border:1px solid ${board.color}25;display:flex;align-items:center;gap:12px">
    <div style="font-size:24px">💡</div>
    <div>
      <div style="font-size:12px;font-weight:800;color:var(--text)">How to use this platform</div>
      <div style="font-size:11px;color:var(--text-muted);margin-top:2px">Pick a subject → study chapters & topics → use 📐 Formula Sheet → practice with AI → mark topics Done ✓ → past papers</div>
    </div>
  </div>
</div>`;
}

/* Toggle a topic done, and clap when that completes the whole chapter.
   Replaces the inline onclick that used to do this, so the completion check has
   somewhere to live. Only claps on the transition into complete -- not when a
   finished chapter is re-rendered, and never when un-ticking a topic. */
function igcseToggleTopic(ci, ti) {
  S.igcseDone = S.igcseDone || {};
  const key    = `${S.igcseSubject}-${ci}-${ti}`;
  const wasDone = !!S.igcseDone[key];
  if (wasDone) delete S.igcseDone[key]; else S.igcseDone[key] = true;

  if (!wasDone) {
    const subj = IGCSE_SUBJECTS[S.igcseSubject];
    const ch   = ((subj && subj.chapters[S.igcseBoard]) || [])[ci];
    if (ch && ch.topics.every((_, i) => S.igcseDone[`${S.igcseSubject}-${ci}-${i}`])) {
      kareemSay('clap');
    }
  }
  saveLocal();
  try { checkIGCSEAchievements(); } catch (_) {}
  render();
}

function tplIGCSESubject() {
  const subj = IGCSE_SUBJECTS[S.igcseSubject];
  if (!subj) return tplIGCSEHub();
  const board = IGCSE_BOARDS[S.igcseBoard];
  const chapters = subj.chapters[S.igcseBoard] || [];
  const totalTopics = chapters.reduce((a,c)=>a+c.topics.length,0);
  const doneTopics = chapters.reduce((a,c,ci)=>a+c.topics.filter((_,ti)=>S.igcseDone[`${S.igcseSubject}-${ci}-${ti}`]).length,0);
  const pct = totalTopics ? Math.round(doneTopics/totalTopics*100) : 0;

  // igcseProgress breakdown for this subject+board
  const _progKeys = Object.keys(S.igcseProgress||{}).filter(k=>k.startsWith(S.igcseSubject+'|'+S.igcseBoard+'|'));
  const _masteredCnt = _progKeys.filter(k=>S.igcseProgress[k]==='mastered').length;
  const _studiedCnt  = _progKeys.filter(k=>S.igcseProgress[k]==='studied').length;
  const _reviewCnt   = _progKeys.filter(k=>S.igcseProgress[k]==='review').length;
  const _progressPct = totalTopics ? Math.round(_progKeys.length/totalTopics*100) : 0;

  const chapterList = chapters.map((ch, ci) => {
    const isOpen = S.igcseChapter === ci;
    const chDone = ch.topics.filter((_,ti)=>S.igcseDone[`${S.igcseSubject}-${ci}-${ti}`]).length;
    const topicItems = ch.topics.map((tp, ti) => {
      const done = !!S.igcseDone[`${S.igcseSubject}-${ci}-${ti}`];
      return `
      <div style="display:flex;align-items:center;gap:0;margin-bottom:4px">
        <div onclick="S.igcseChapter=${ci};S.igcseTopic=${ti};S.igcseTab='notes';render()"
          style="flex:1;padding:10px 14px;border-radius:10px 0 0 10px;cursor:pointer;display:flex;align-items:center;gap:10px;transition:.15s;
                 background:${done?'#10B98108':'transparent'};border:1px solid ${done?'#10B98130':'var(--border)'};border-right:none"
          onmouseover="this.style.background='${subj.color}11';this.style.borderColor='${subj.color}44'"
          onmouseout="this.style.background='${done?'#10B98108':'transparent'}';this.style.borderColor='${done?'#10B98130':'var(--border)'}'">
          <span style="font-size:14px">${(()=>{const _s=((S.igcseProgress||{})[S.igcseSubject+'|'+S.igcseBoard+'|'+tp.title]);return _s==='mastered'?'🏆':_s==='studied'?'📖':_s==='review'?'⚠️':'○';})()}</span>
          <span style="font-size:13px;font-weight:${done?'600':'500'};color:${(()=>{const _s=((S.igcseProgress||{})[S.igcseSubject+'|'+S.igcseBoard+'|'+tp.title]);return _s==='mastered'?'#10B981':_s==='review'?'#F59E0B':'var(--text)'})()}">${tp.title}</span>
          <span style="margin-right:auto;font-size:10px;color:var(--text-muted)">${tp.points.length} pts</span>
          <span style="font-size:11px;color:${subj.color}">›</span>
        </div>
        <button onclick="igcseToggleTopic(${ci},${ti})"
          title="${done?'Mark as not done':'Mark as done'}"
          style="padding:10px 10px;border-radius:0 10px 10px 0;border:1px solid ${done?'#10B98130':'var(--border)'};border-left:none;
                 background:${done?'#10B98115':'var(--bg-card)'};cursor:pointer;font-size:14px;transition:.15s">
          ${done?'✓':'○'}
        </button>
      </div>`;
    }).join('');
    return `
    <div style="border:1px solid var(--border);border-radius:16px;margin-bottom:10px;overflow:hidden;transition:.15s">
      <div onclick="S.igcseChapter=${isOpen?'null':ci};render()"
        style="padding:14px 16px;cursor:pointer;display:flex;align-items:center;gap:12px;
               background:${isOpen?`${subj.color}0f`:'var(--bg-card)'};transition:.15s">
        ${(()=>{
          const _r=16,_c=2*Math.PI*_r,_pct=ch.topics.length?chDone/ch.topics.length:0,_dash=_c*_pct,_gap=_c-_dash;
          const _col=_pct===1?'#10B981':_pct>0?subj.color:'var(--border)';
          return `<div style="position:relative;width:40px;height:40px;flex-shrink:0">
            <svg width="40" height="40" style="transform:rotate(-90deg)">
              <circle cx="20" cy="20" r="${_r}" fill="${subj.color}18" stroke="var(--border)" stroke-width="2.5"/>
              <circle cx="20" cy="20" r="${_r}" fill="none" stroke="${_col}" stroke-width="2.5"
                stroke-dasharray="${_dash.toFixed(1)} ${_gap.toFixed(1)}" stroke-linecap="round" style="transition:.5s"/>
            </svg>
            <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:11px">${ch.icon||'📘'}</div>
          </div>`;
        })()}
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:800;color:var(--text)">${ch.title}</div>
          <div style="font-size:10px;color:var(--text-muted);margin-top:1px">${ch.topics.length} topics${chDone>0?` · <span style="color:#10B981;font-weight:800">${chDone} done ✓</span>`:''}</div>
        </div>
        <span style="font-size:16px;color:var(--text-muted);transition:transform .2s;transform:${isOpen?'rotate(90deg)':'rotate(0deg)'};display:inline-block">›</span>
      </div>
      ${isOpen?`<div style="padding:8px 12px 12px;background:var(--bg);border-top:1px solid var(--border)">${topicItems}</div>`:''}
    </div>`;
  }).join('');

  const ppLink = subj.pastPapers[S.igcseBoard] || '#';
  return `
<div style="max-width:880px;margin:0 auto;padding:0 0 80px">
  <!-- Subject Header -->
  <div style="background:linear-gradient(135deg,${subj.color},${subj.color}bb);padding:20px 16px 24px;border-radius:0 0 24px 24px;margin-bottom:18px;position:relative;overflow:hidden">
    <div style="position:absolute;top:-20px;right:-20px;width:100px;height:100px;border-radius:50%;background:#ffffff0d"></div>
    <button onclick="S.igcseSubject=null;S.igcseChapter=null;S.igcseTopic=null;render()"
      style="background:#ffffff25;border:1px solid #ffffff35;border-radius:10px;padding:5px 12px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700;margin-bottom:14px;display:flex;align-items:center;gap:6px">
      ← ${L('All Subjects','كل المواد')}
    </button>
    <div style="display:flex;align-items:center;gap:14px;margin-bottom:14px">
      <div style="width:56px;height:56px;border-radius:16px;background:#ffffff25;display:flex;align-items:center;justify-content:center;font-size:30px;flex-shrink:0">${subj.icon}</div>
      <div>
        <div style="font-size:21px;font-weight:900;color:#fff">${subj.label}</div>
        <div style="font-size:11px;color:#ffffffbb;margin-top:2px">${board.icon} ${board.label} · IGCSE · ${chapters.length} chapters · ${totalTopics} topics</div>
      </div>
    </div>
    <!-- Progress bar -->
    <div style="margin-bottom:14px">
      <div style="display:flex;justify-content:space-between;margin-bottom:5px">
        <span style="font-size:10px;color:#ffffffbb;font-weight:700">PROGRESS</span>
        <span style="font-size:10px;color:#fff;font-weight:900">${doneTopics}/${totalTopics} topics · ${pct}%</span>
      </div>
      <div style="height:6px;background:#ffffff25;border-radius:3px">
        <div style="height:100%;width:${pct}%;background:#fff;border-radius:3px;transition:.5s"></div>
      </div>
    </div>
    <!-- Progress breakdown chips -->
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">
      ${_masteredCnt ? `<div style="padding:4px 10px;border-radius:20px;background:#10B98130;color:#10B981;font-size:10px;font-weight:800">🏆 ${_masteredCnt} Mastered</div>` : ''}
      ${_studiedCnt  ? `<div style="padding:4px 10px;border-radius:20px;background:#3B82F630;color:#93C5FD;font-size:10px;font-weight:800">📖 ${_studiedCnt} Studied</div>` : ''}
      ${_reviewCnt   ? `<div style="padding:4px 10px;border-radius:20px;background:#F59E0B30;color:#FCD34D;font-size:10px;font-weight:800">⚠️ ${_reviewCnt} Needs Review</div>` : ''}
      ${!_progKeys.length ? `<div style="padding:4px 10px;border-radius:20px;background:#ffffff15;color:#ffffffaa;font-size:10px;font-weight:700">No progress marked yet</div>` : ''}
    </div>
    <!-- Quick actions -->
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <a href="${ppLink}" target="_blank" rel="noopener"
        style="background:#DC2626;border:2px solid #ffffff40;border-radius:10px;padding:8px 16px;color:#fff;text-decoration:none;font-size:12px;font-weight:900;font-family:Cairo,sans-serif;
               box-shadow:0 3px 12px #DC262655;display:flex;align-items:center;gap:6px">
        📄 Past Papers ↗
      </a>
      <button onclick="S.igcseView='papers';S.igcsePpFilter='all';S.igcsePpType='all';render()"
        style="background:#ffffff20;border:2px solid #ffffff40;border-radius:10px;padding:8px 16px;color:#fff;cursor:pointer;font-size:12px;font-weight:900;font-family:Cairo,sans-serif;display:flex;align-items:center;gap:6px">
        📊 Topic Analysis
      </button>
      <button onclick="S.screen='chat';S.subject='${subj.label} IGCSE';S.messages=[];render()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        💬 AI Tutor
      </button>
      <button onclick="S.screen='flashcards';S.subject='${subj.label} IGCSE';doGenerateFlashcards()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        🗂️ Flashcards
      </button>
      ${IGCSE_FORMULAS[S.igcseSubject]?`<button onclick="S.igcseView='formulas';render()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        📐 Formula Sheet
      </button>`:''}
      ${subj.boards.length>1?`<button onclick="S.igcseView='compare';render()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        ⚖️ Compare Boards
      </button>`:''}
      <button onclick="S.igcseView='papers';S.igcsePpFilter='all';S.igcsePpType='all';render()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        📋 Past Papers
      </button>
      <button onclick="S.igcseView='mindmap';render()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        🗺️ Mind Map
      </button>
      <button onclick="S.screen='textbook';S.textbookUrl='home';S.textbookSubjFilter='${esc(subj.label)}';S.textbookViewUrl=null;render()"
        style="background:#ffffff20;border:1px solid #ffffff35;border-radius:10px;padding:7px 14px;color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
        📚 Textbook
      </button>
    </div>
  </div>

  <!-- Chapter List -->
  <div style="padding:0 12px">
    <div style="font-size:10px;color:var(--text-muted);font-weight:800;letter-spacing:1.5px;margin-bottom:14px">${L('CHAPTERS & TOPICS','الفصول والمواضيع')}</div>
    ${chapterList||'<div style="text-align:center;padding:40px;color:var(--text-muted)">No chapters available for this board yet</div>'}
  </div>
</div>`;
}

function tplIGCSETopic() {
  const subj = IGCSE_SUBJECTS[S.igcseSubject];
  if (!subj) return tplIGCSEHub();
  const board = IGCSE_BOARDS[S.igcseBoard];
  const chapters = subj.chapters[S.igcseBoard] || [];
  const ch = chapters[S.igcseChapter];
  if (!ch) return tplIGCSESubject();
  const tp = ch.topics[S.igcseTopic];
  if (!tp) return tplIGCSESubject();

  // Navigation between topics
  const allTopics = chapters.flatMap((c,ci) => c.topics.map((_,ti) => ({ci,ti})));
  const curIdx = allTopics.findIndex(x => x.ci===S.igcseChapter && x.ti===S.igcseTopic);
  const prevT = allTopics[curIdx-1] || null;
  const nextT = allTopics[curIdx+1] || null;

  const isDone = !!(S.igcseDone||{})[`${S.igcseSubject}-${S.igcseChapter}-${S.igcseTopic}`];
  // Track recently studied + spaced repetition last-studied date
  (()=>{
    const key = `${S.igcseSubject}-${S.igcseChapter}-${S.igcseTopic}`;
    const rec = {sk:S.igcseSubject,ci:S.igcseChapter,ti:S.igcseTopic,label:subj.label,icon:subj.icon,topicTitle:tp.title,color:subj.color};
    S.igcseRecent = [rec,...(S.igcseRecent||[]).filter(r=>!(r.sk===rec.sk&&r.ci===rec.ci&&r.ti===rec.ti))].slice(0,6);
    const srKey = `${S.igcseSubject}|${S.igcseBoard}|${tp.title}`;
    const today = new Date().toISOString().slice(0,10);
    S.igcseLastStudied = S.igcseLastStudied || {};
    if(!S.igcseLastStudied[srKey]) {
      S.igcseLastStudied[srKey] = today;
      // Update daily log
      S.igcseDailyLog = S.igcseDailyLog || {};
      S.igcseDailyLog[today] = (S.igcseDailyLog[today] || 0) + 1;
      saveLocal();
      checkIGCSEAchievements();
    }
  })();

  const tabs = ['notes','flashcards','quiz','questions','papers'].map(tab => {
    const labels = {notes:'📖 '+L('Notes','ملاحظات'), flashcards:'🃏 '+L('Cards','بطاقات'), quiz:'🎯 '+L('Quiz','اختبار'), questions:'❓ '+L('Practice','تدريب'), papers:'📄 '+L('Papers','أوراق')};
    return `<button onclick="S.igcseTab='${tab}';S.igcseQuizIdx=0;S.igcseQuizAnswered=null;S.igcseQuizScore=0;S.igcseQuizDone=false;render()"
      style="flex:1;padding:9px 2px;border:none;cursor:pointer;font-family:Cairo,sans-serif;font-size:10px;font-weight:800;transition:.15s;border-radius:10px;letter-spacing:.2px;
             ${S.igcseTab===tab?`background:${subj.color};color:#fff;box-shadow:0 2px 8px ${subj.color}44`:'background:var(--bg);color:var(--text-muted);border:1px solid var(--border)'}">
      ${labels[tab]}
    </button>`;
  }).join('');

  let tabContent = '';
  if (S.igcseTab === 'notes') {
    const keyPoints = tp.points.map((p,i) => `
      <div style="display:flex;gap:14px;padding:14px 16px;background:var(--bg-card);border-radius:14px;margin-bottom:8px;border:1px solid var(--border);border-left:4px solid ${subj.color}">
        <div style="min-width:26px;height:26px;border-radius:8px;background:${subj.color};color:#fff;font-size:11px;font-weight:900;display:flex;align-items:center;justify-content:center;flex-shrink:0">${i+1}</div>
        <div style="font-size:13px;color:var(--text);line-height:1.75">${p}</div>
      </div>`).join('');
    tabContent = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;padding:10px 14px;background:${subj.color}0f;border-radius:12px;border:1px solid ${subj.color}25">
        <div>
          <div style="font-size:10px;color:${subj.color};font-weight:900;letter-spacing:1px">KEY REVISION NOTES</div>
          <div style="font-size:11px;color:var(--text-muted);margin-top:1px">${tp.points.length} points · ${board.short}</div>
        </div>
        <!-- Bookmark + Progress Tracker -->
        ${(()=>{
          const _bk = `bk|${S.igcseSubject}|${S.igcseBoard}|${tp.title}`;
          const _isBookmarked = !!(S.igcseProgress||{})[_bk];
          return `<button onclick="S.igcseProgress=S.igcseProgress||{};
            if(S.igcseProgress['${_bk}']){delete S.igcseProgress['${_bk}'];}
            else{S.igcseProgress['${_bk}']='1';}
            saveLocal();render()"
            title="${_isBookmarked?'Remove bookmark':'Bookmark topic'}"
            style="padding:6px 10px;border-radius:9px;border:none;cursor:pointer;font-size:15px;transition:.15s;
                   ${_isBookmarked?'background:#F59E0B30;color:#F59E0B':'background:var(--bg);border:1px solid var(--border);color:var(--text-muted)'}">
            ${_isBookmarked?'⭐':'☆'}
          </button>`;
        })()}
        <!-- Progress Tracker -->
        ${(()=>{
          const _pk = `${S.igcseSubject}|${S.igcseBoard}|${tp.title}`;
          const _cur = (S.igcseProgress||{})[_pk] || '';
          const _statuses = [
            { id:'studied',  icon:'📖', label:'Studied',      bg:'#3B82F6' },
            { id:'review',   icon:'⚠️', label:'Needs Review', bg:'#F59E0B' },
            { id:'mastered', icon:'🏆', label:'Mastered',     bg:'#10B981' },
          ];
          return `<div style="display:flex;gap:5px;align-items:center">
            ${_statuses.map(st => `
            <button onclick="S.igcseProgress=S.igcseProgress||{};
              if(S.igcseProgress['${_pk}']==='${st.id}'){delete S.igcseProgress['${_pk}'];}
              else{S.igcseProgress['${_pk}']='${st.id}';}
              saveLocal();render()"
              title="${st.label}"
              style="padding:6px 10px;border-radius:9px;border:none;cursor:pointer;font-size:11px;font-weight:800;font-family:Cairo,sans-serif;transition:.15s;white-space:nowrap;
                     ${_cur===st.id?'background:'+st.bg+';color:#fff;box-shadow:0 2px 8px '+st.bg+'44':'background:var(--bg);color:var(--text-muted);border:1px solid var(--border)'}">
              ${st.icon} ${st.label}
            </button>`).join('')}
          </div>`;
        })()}
      </div>
      ${keyPoints}
      ${tp.workedExample ? `
      <div style="margin-top:12px;background:#3B82F60f;border:1px solid #3B82F625;border-radius:14px;overflow:hidden">
        <div style="padding:10px 14px;background:#3B82F610;border-bottom:1px solid #3B82F620;font-size:11px;font-weight:900;color:#3B82F6;letter-spacing:.5px">✏️ WORKED EXAMPLE</div>
        <div style="padding:12px 14px;font-size:12px;color:var(--text);line-height:1.8;white-space:pre-wrap;font-family:monospace,Cairo,sans-serif">${tp.workedExample}</div>
      </div>` : ''}
      ${tp.examTips && tp.examTips.length ? `
      <div style="margin-top:12px;background:#10B9810f;border:1px solid #10B98125;border-radius:14px;overflow:hidden">
        <div style="padding:10px 14px;background:#10B98110;border-bottom:1px solid #10B98120;font-size:11px;font-weight:900;color:#10B981;letter-spacing:.5px">⭐ EXAM TIPS</div>
        <div style="padding:10px 14px">
          ${tp.examTips.map(t=>`<div style="display:flex;gap:8px;padding:6px 0;border-bottom:1px solid #10B98115;font-size:12px;color:var(--text);line-height:1.6"><span style="color:#10B981;flex-shrink:0">✓</span>${t}</div>`).join('')}
        </div>
      </div>` : ''}
      ${tp.commonMistakes && tp.commonMistakes.length ? `
      <div style="margin-top:12px;background:#EF44440f;border:1px solid #EF444425;border-radius:14px;overflow:hidden">
        <div style="padding:10px 14px;background:#EF444410;border-bottom:1px solid #EF444420;font-size:11px;font-weight:900;color:#EF4444;letter-spacing:.5px">⚠️ COMMON MISTAKES</div>
        <div style="padding:10px 14px">
          ${tp.commonMistakes.map(m=>`<div style="display:flex;gap:8px;padding:6px 0;border-bottom:1px solid #EF444415;font-size:12px;color:var(--text);line-height:1.6"><span style="color:#EF4444;flex-shrink:0">✗</span>${m}</div>`).join('')}
        </div>
      </div>` : ''}
      <!-- Personal Notes -->
      ${(()=>{
        const _nk = `${S.igcseSubject}|${S.igcseBoard}|${tp.title}`;
        const _note = (S.igcseTopicNotes||{})[_nk] || '';
        return `
        <div style="margin-top:14px;background:var(--bg-card);border:1px solid var(--border);border-radius:14px;overflow:hidden">
          <div style="padding:10px 14px;background:var(--bg);border-bottom:1px solid var(--border);font-size:11px;font-weight:900;color:var(--text-muted);letter-spacing:.5px;display:flex;justify-content:space-between;align-items:center">
            <span>📝 MY NOTES</span>
            ${_note?`<span style="font-size:9px;color:#10B981;font-weight:700">✓ Saved</span>`:'<span style="font-size:9px;color:var(--text-muted)">Personal notes for this topic</span>'}
          </div>
          <textarea id="topic-note-${_nk.replace(/[^a-z0-9]/gi,'_')}"
            placeholder="Write your own notes here... (auto-saved)"
            oninput="S.igcseTopicNotes=S.igcseTopicNotes||{};S.igcseTopicNotes['${_nk}']=this.value;saveLocal()"
            style="width:100%;min-height:80px;padding:12px 14px;border:none;background:transparent;color:var(--text);font-size:12px;font-family:Cairo,sans-serif;line-height:1.7;resize:vertical;outline:none;box-sizing:border-box">${_note}</textarea>
        </div>`;
      })()}
      <div style="display:flex;gap:8px;margin-top:14px">
        <button onclick="teachTopicOnBoard('${S.igcseSubject}',${S.igcseChapter},${S.igcseTopic})"
          style="flex:1;padding:11px;background:var(--primary);color:#fff;border:none;border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:12px">
          🎬 ${L('Teach on board','اشرح على السبورة')}
        </button>
        <button onclick="chatWith('${subj.label} IGCSE — ${tp.title}','Explain ${tp.title.replace(/'/g,"\\'")} for IGCSE ${subj.label} in detail with worked examples and exam tips')"
          style="padding:11px 14px;background:var(--bg-card);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-size:12px;font-weight:700"
          title="Explain with AI">
          🤖
        </button>
        <button onclick="shareIGCSETopic('${S.igcseSubject}','${S.igcseBoard}',${S.igcseChapter},${S.igcseTopic})"
          style="padding:11px 14px;background:var(--bg-card);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-size:12px;font-weight:700"
          title="Share this topic">
          🔗
        </button>
        <button onclick="printTopicNotes('${S.igcseSubject}',${S.igcseChapter},${S.igcseTopic})"
          style="padding:11px 14px;background:var(--bg-card);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-size:12px;font-weight:700"
          title="Print / Save as PDF">
          🖨️
        </button>
        <button onclick="S.screen='flashcards';S.subject='${subj.label} — ${tp.title.replace(/'/g,"\\'")}';doGenerateFlashcards()"
          style="padding:11px 14px;background:var(--bg-card);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-size:12px;font-weight:700">
          🗂️
        </button>
      </div>`;
  } else if (S.igcseTab === 'flashcards') {
    const cards = tp.points.map((p,i)=>{
      const parts = p.split(/:\s+|—\s+/);
      const front = parts.length>1 ? parts[0].trim() : `Point ${i+1}`;
      const back = p.trim();
      return {front, back};
    });
    const totalCards = cards.length;
    S.igcseFcRatings = S.igcseFcRatings || {};
    const fcKey = `${S.igcseSubject}|${S.igcseBoard}|${tp.title}`;
    const ratings = S.igcseFcRatings[fcKey] || {};
    const fcIdx = Math.min(S.igcseFcIdx||0, totalCards-1);
    const card = cards[fcIdx];
    const flipped = S.igcseFcFlipped||false;
    const knownCount = Object.values(ratings).filter(v=>v==='know').length;
    const unsureCount = Object.values(ratings).filter(v=>v==='unsure').length;
    const forgotCount = Object.values(ratings).filter(v=>v==='forgot').length;
    const dots = cards.map((_,i) => {
      const r = ratings[i];
      const col = r==='know'?'#10B981':r==='unsure'?'#F59E0B':r==='forgot'?'#EF4444':'var(--border)';
      const sz = i===fcIdx ? '10px' : '7px';
      return `<div style="width:${sz};height:${sz};border-radius:50%;background:${col};transition:.2s;flex-shrink:0"></div>`;
    }).join('');
    tabContent = `
      <style>
        .fc-scene{perspective:800px;width:100%;min-height:200px;margin-bottom:14px;cursor:pointer}
        .fc-card{position:relative;width:100%;min-height:200px;transform-style:preserve-3d;transition:transform .45s cubic-bezier(.4,0,.2,1)}
        .fc-card.flipped{transform:rotateY(180deg)}
        .fc-face{position:absolute;width:100%;min-height:200px;backface-visibility:hidden;-webkit-backface-visibility:hidden;border-radius:20px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:28px 20px;text-align:center;box-sizing:border-box}
        .fc-front{background:var(--bg-card);border:2px solid ${subj.color}55;box-shadow:0 4px 20px ${subj.color}18}
        .fc-back{background:${subj.color}0f;border:2px solid ${subj.color}88;transform:rotateY(180deg);box-shadow:0 4px 20px ${subj.color}28}
      </style>
      <!-- Progress dots -->
      <div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:center;margin-bottom:10px;padding:0 8px">${dots}</div>
      <!-- Score row -->
      <div style="display:flex;justify-content:center;gap:12px;margin-bottom:12px">
        <span style="font-size:10px;font-weight:800;color:#10B981">✅ ${knownCount}</span>
        <span style="font-size:10px;font-weight:800;color:#F59E0B">🤔 ${unsureCount}</span>
        <span style="font-size:10px;font-weight:800;color:#EF4444">❌ ${forgotCount}</span>
        <span style="font-size:10px;font-weight:800;color:var(--text-muted)">${fcIdx+1}/${totalCards}</span>
      </div>
      <!-- 3D Flip Card -->
      <div class="fc-scene" onclick="S.igcseFcFlipped=!S.igcseFcFlipped;render()">
        <div class="fc-card ${flipped?'flipped':''}">
          <div class="fc-face fc-front">
            <div style="font-size:10px;color:var(--text-muted);font-weight:900;letter-spacing:1.5px;margin-bottom:14px">TAP TO FLIP</div>
            <div style="font-size:17px;font-weight:900;color:var(--text);line-height:1.5;max-width:300px">${card.front}</div>
            <div style="margin-top:14px;font-size:24px;opacity:.35">🃏</div>
          </div>
          <div class="fc-face fc-back">
            <div style="font-size:10px;color:${subj.color};font-weight:900;letter-spacing:1.5px;margin-bottom:12px">ANSWER</div>
            <div style="font-size:13px;color:var(--text);line-height:1.8;max-width:340px">${card.back}</div>
          </div>
        </div>
      </div>
      <!-- Self-rating (shown after flip) -->
      ${flipped ? `
      <div style="margin-bottom:14px">
        <div style="font-size:10px;color:var(--text-muted);font-weight:800;text-align:center;margin-bottom:8px;letter-spacing:1px">HOW WELL DID YOU KNOW IT?</div>
        <div style="display:flex;gap:8px">
          <button onclick="event.stopPropagation();S.igcseFcRatings=S.igcseFcRatings||{};(S.igcseFcRatings['${fcKey}']=S.igcseFcRatings['${fcKey}']||{})[${fcIdx}]='forgot';S.igcseFcFlipped=false;S.igcseFcIdx=Math.min(${totalCards-1},(S.igcseFcIdx||0)+1);render()"
            style="flex:1;padding:11px 6px;border-radius:12px;border:2px solid #EF444433;background:#EF444410;color:#EF4444;cursor:pointer;font-weight:800;font-size:12px;font-family:Cairo,sans-serif">❌ Forgot</button>
          <button onclick="event.stopPropagation();S.igcseFcRatings=S.igcseFcRatings||{};(S.igcseFcRatings['${fcKey}']=S.igcseFcRatings['${fcKey}']||{})[${fcIdx}]='unsure';S.igcseFcFlipped=false;S.igcseFcIdx=Math.min(${totalCards-1},(S.igcseFcIdx||0)+1);render()"
            style="flex:1;padding:11px 6px;border-radius:12px;border:2px solid #F59E0B33;background:#F59E0B10;color:#F59E0B;cursor:pointer;font-weight:800;font-size:12px;font-family:Cairo,sans-serif">🤔 Unsure</button>
          <button onclick="event.stopPropagation();S.igcseFcRatings=S.igcseFcRatings||{};(S.igcseFcRatings['${fcKey}']=S.igcseFcRatings['${fcKey}']||{})[${fcIdx}]='know';S.igcseFcFlipped=false;S.igcseFcIdx=Math.min(${totalCards-1},(S.igcseFcIdx||0)+1);render()"
            style="flex:1;padding:11px 6px;border-radius:12px;border:2px solid #10B98133;background:#10B98110;color:#10B981;cursor:pointer;font-weight:800;font-size:12px;font-family:Cairo,sans-serif">✅ Know It!</button>
        </div>
      </div>` : ''}
      <!-- Controls -->
      <div style="display:flex;gap:8px;justify-content:center">
        <button onclick="S.igcseFcIdx=Math.max(0,(S.igcseFcIdx||0)-1);S.igcseFcFlipped=false;render()"
          ${fcIdx===0?'disabled':''} style="padding:9px 18px;border-radius:12px;border:1px solid var(--border);background:var(--bg-card);color:var(--text);cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif;${fcIdx===0?'opacity:.4;cursor:default':''}">
          ‹ Prev
        </button>
        <button onclick="S.igcseFcRatings=S.igcseFcRatings||{};S.igcseFcRatings['${fcKey}']={};S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
          style="padding:9px 14px;border-radius:12px;border:1px solid var(--border);background:var(--bg);color:var(--text-muted);cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif">
          ↺ Reset
        </button>
        <button onclick="S.igcseFcIdx=Math.min(${totalCards-1},(S.igcseFcIdx||0)+1);S.igcseFcFlipped=false;render()"
          ${fcIdx===totalCards-1?'disabled':''} style="padding:9px 18px;border-radius:12px;border:1px solid var(--border);background:var(--bg-card);color:var(--text);cursor:pointer;font-size:12px;font-weight:700;font-family:Cairo,sans-serif;${fcIdx===totalCards-1?'opacity:.4;cursor:default':''}">
          Next ›
        </button>
      </div>
      ${knownCount+unsureCount+forgotCount===totalCards ? `
      <div style="margin-top:12px;padding:14px 16px;background:#10B98110;border:1px solid #10B98130;border-radius:14px;text-align:center">
        <div style="font-size:16px;margin-bottom:4px">${knownCount===totalCards?'🏆 Perfect!':'🎯 Round complete!'}</div>
        <div style="font-size:12px;color:var(--text-muted)">You know <strong style="color:#10B981">${knownCount}</strong> · unsure <strong style="color:#F59E0B">${unsureCount}</strong> · forgot <strong style="color:#EF4444">${forgotCount}</strong></div>
        ${forgotCount>0?`<button onclick="S.igcseFcRatings=S.igcseFcRatings||{};const r=S.igcseFcRatings['${fcKey}']||{};const fi=Object.keys(r).filter(k=>r[k]==='forgot'||r[k]==='unsure');S.igcseFcRatings['${fcKey}']={};fi.forEach((k,i)=>{}),S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
          style="margin-top:8px;padding:8px 16px;border-radius:10px;border:none;background:${subj.color};color:#fff;cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
          🔄 Retry missed cards
        </button>`:''}
      </div>` : ''}
      <div style="margin-top:10px;text-align:center">
        <button onclick="chatWith('${subj.label} Flashcards','Create 10 Q&A flashcards for IGCSE ${subj.label} topic: ${tp.title.replace(/'/g,"\\'")}. Format each as Q: ... / A: ...')"
          style="padding:8px 16px;border-radius:10px;border:1px solid ${subj.color}44;background:${subj.color}10;color:${subj.color};cursor:pointer;font-size:11px;font-weight:700;font-family:Cairo,sans-serif">
          🤖 AI Flashcards (×10)
        </button>
      </div>`;
  } else if (S.igcseTab === 'quiz') {
    // Build MCQ questions from tp.points — each point becomes a question
    // Format: strip the point into a "what is X?" style, generate 3 wrong answers from other points
    const pts = tp.points;
    // Generate questions: use each point as the answer; partial text as question
    const quizQs = pts.map((p, i) => {
      // Create a question stem by taking first clause up to colon/dash
      const parts = p.split(/:\s+|—\s+|–\s+/);
      const concept = parts[0].trim();
      const answer = p.trim();
      const question = `What is the correct statement about "${concept}"?`;
      // Wrong answers: pick 2-3 other points
      const others = pts.filter((_,j) => j!==i);
      // shuffle others
      const shuffled = others.sort(()=>Math.random()-0.5).slice(0,3);
      // put correct answer in random position
      const pos = Math.floor(Math.random()*4);
      const opts = [...shuffled];
      opts.splice(pos, 0, answer);
      return { question, opts, correct: pos };
    });
    const totalQs = quizQs.length;
    const qIdx = Math.min(S.igcseQuizIdx||0, totalQs-1);
    const answered = S.igcseQuizAnswered;
    const score = S.igcseQuizScore||0;
    const done = S.igcseQuizDone||false;

    if (done) {
      const pct = Math.round(score/totalQs*100);
      const grade = pct>=80?'🏆 Excellent!':pct>=60?'👍 Good':pct>=40?'📚 Keep studying':'💪 Review notes first';
      tabContent = `
        <div style="text-align:center;padding:30px 16px;background:var(--bg-card);border-radius:20px;border:1px solid var(--border)">
          <div style="font-size:52px;margin-bottom:10px">${pct>=80?'🏆':pct>=60?'⭐':'📚'}</div>
          <div style="font-size:22px;font-weight:900;color:${subj.color};margin-bottom:6px">${score}/${totalQs} correct</div>
          <div style="font-size:28px;font-weight:900;color:var(--text);margin-bottom:4px">${pct}%</div>
          <div style="font-size:14px;color:var(--text-muted);margin-bottom:20px">${grade}</div>
          <div style="height:8px;background:var(--border);border-radius:4px;margin:0 20px 20px;overflow:hidden">
            <div style="height:100%;width:${pct}%;background:${pct>=80?'#10B981':pct>=60?subj.color:'#EF4444'};border-radius:4px;transition:1s"></div>
          </div>
          <div style="display:flex;gap:10px;justify-content:center">
            <button onclick="S.igcseQuizIdx=0;S.igcseQuizAnswered=null;S.igcseQuizScore=0;S.igcseQuizDone=false;render()"
              style="padding:12px 24px;background:${subj.color};color:#fff;border:none;border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:13px">
              🔁 Retry Quiz
            </button>
            <button onclick="S.igcseTab='notes';render()"
              style="padding:12px 24px;background:var(--bg);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:13px">
              📖 Review Notes
            </button>
          </div>
        </div>`;
    } else {
      const q = quizQs[qIdx];
      tabContent = `
        <div style="margin-bottom:10px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
            <div style="font-size:10px;color:var(--text-muted);font-weight:800;letter-spacing:1px">QUESTION ${qIdx+1} OF ${totalQs}</div>
            <div style="font-size:10px;color:${subj.color};font-weight:800">Score: ${score}/${qIdx}</div>
          </div>
          <div style="height:4px;background:var(--border);border-radius:2px;margin-bottom:14px;overflow:hidden">
            <div style="height:100%;width:${Math.round(qIdx/totalQs*100)}%;background:${subj.color};border-radius:2px;transition:.3s"></div>
          </div>
          <div style="font-size:14px;font-weight:900;color:var(--text);line-height:1.5;margin-bottom:16px;padding:14px;background:var(--bg-card);border-radius:14px;border:1px solid var(--border)">
            ${q.question}
          </div>
          <div style="display:flex;flex-direction:column;gap:8px">
            ${q.opts.map((opt,oi)=>{
              let bg='var(--bg-card)', border='var(--border)', col='var(--text)', badge='';
              if (answered!==null) {
                if (oi===q.correct) { bg='#10B98115'; border='#10B981'; col='#10B981'; badge='✓ '; }
                else if (oi===answered && answered!==q.correct) { bg='#EF444415'; border='#EF4444'; col='#EF4444'; badge='✗ '; }
              }
              const clickable = answered===null;
              return `<button onclick="${clickable?`S.igcseQuizAnswered=${oi};if(${oi}===${q.correct})S.igcseQuizScore=(S.igcseQuizScore||0)+1;render()`:''})"
                style="text-align:left;padding:12px 14px;background:${bg};border:2px solid ${border};color:${col};border-radius:12px;cursor:${clickable?'pointer':'default'};font-family:Cairo,sans-serif;font-size:12px;line-height:1.5;transition:.15s">
                ${badge}${opt}
              </button>`;
            }).join('')}
          </div>
          ${answered!==null ? `
          <button onclick="${qIdx<totalQs-1?`S.igcseQuizIdx=${qIdx+1};S.igcseQuizAnswered=null;render()`:`S.igcseQuizDone=true;render()`}"
            style="width:100%;margin-top:14px;padding:12px;background:${subj.color};color:#fff;border:none;border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:13px">
            ${qIdx<totalQs-1?'Next Question →':'See Results 🏆'}
          </button>` : ''}
        </div>`;
    }
  } else if (S.igcseTab === 'questions') {
    tabContent = `
      <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:24px 16px;text-align:center;margin-bottom:12px">
        <div style="font-size:36px;margin-bottom:10px">❓</div>
        <div style="font-size:15px;font-weight:900;color:var(--text);margin-bottom:6px">AI Practice Questions</div>
        <div style="font-size:12px;color:var(--text-muted);margin-bottom:18px;line-height:1.6">Get 5 IGCSE-style exam questions on <strong>${tp.title}</strong> with full mark schemes</div>
        <button onclick="chatWith('IGCSE '+${JSON.stringify(subj.label)},'Generate 5 IGCSE-style exam questions on the topic: '+${JSON.stringify(tp.title)}+' ('+${JSON.stringify(subj.label)}+'). Include: 2 short answer (2-4 marks), 2 structured (4-6 marks), 1 extended response (6-8 marks). Provide full mark schemes for each.')"
          style="width:100%;padding:12px;background:${subj.color};color:#fff;border:none;border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:13px;margin-bottom:10px">
          🤖 Generate 5 Exam Questions
        </button>
        <button onclick="S.screen='quiz';S.subject='IGCSE '+${JSON.stringify(subj.label+' — '+tp.title)};doGenerateQuiz()"
          style="width:100%;padding:12px;background:var(--bg);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:13px">
          📝 Quick MCQ Quiz
        </button>
      </div>
      <div style="padding:12px 14px;background:#F59E0B0f;border-radius:12px;border:1px solid #F59E0B25;font-size:12px;color:var(--text-muted)">
        💡 <strong>Exam tip:</strong> ~1 minute per mark. Read question carefully — note key command words: <em>state, describe, explain, calculate, evaluate, discuss</em>
      </div>`;
  } else {
    const ppLink = subj.pastPapers[S.igcseBoard] || '#';
    tabContent = `
      <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:24px 16px;text-align:center;margin-bottom:12px">
        <div style="font-size:36px;margin-bottom:10px">📄</div>
        <div style="font-size:15px;font-weight:900;color:var(--text);margin-bottom:4px">Official Past Papers</div>
        <div style="font-size:12px;color:var(--text-muted);margin-bottom:18px">${board.label} · ${subj.label}</div>
        <a href="${ppLink}" target="_blank" rel="noopener"
          style="display:block;padding:12px;background:${board.color};color:#fff;border-radius:12px;text-decoration:none;font-family:Cairo,sans-serif;font-weight:700;font-size:13px;margin-bottom:8px">
          📥 Open Official Past Papers
        </a>
        <button onclick="chatWith('IGCSE '+${JSON.stringify(subj.label)},'Give me 3 typical past paper questions about '+${JSON.stringify(tp.title)}+' from '+${JSON.stringify(board.label)}+' IGCSE exams, with example answers and examiner tips')"
          style="width:100%;padding:12px;background:var(--bg);border:1px solid var(--border);color:var(--text);border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;font-weight:700;font-size:13px">
          💬 Ask AI for Past Paper Questions
        </button>
      </div>
      <div style="padding:12px 14px;background:var(--bg-card);border-radius:12px;border:1px solid var(--border)">
        <div style="font-size:11px;font-weight:800;color:var(--text);margin-bottom:8px">📌 Exam Strategy for ${tp.title}</div>
        <div style="display:flex;flex-direction:column;gap:6px;font-size:12px;color:var(--text-muted)">
          <div>✦ Read command words carefully — "state" (1-2 words), "explain" (reason needed), "discuss" (both sides)</div>
          <div>✦ Show all working in calculations — method marks available even if final answer wrong</div>
          <div>✦ Time management: ~1 minute per mark; move on if stuck</div>
        </div>
      </div>`;
  }

  return `
<div style="max-width:860px;margin:0 auto;padding:0 0 80px">
  <!-- Breadcrumb + Topic Header -->
  <div style="background:linear-gradient(135deg,${subj.color}ee,${subj.color}aa);padding:16px 16px 20px;border-radius:0 0 22px 22px;margin-bottom:14px">
    <!-- Breadcrumb -->
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;flex-wrap:wrap">
      <button onclick="S.igcseSubject=null;S.igcseTopic=null;S.igcseChapter=null;render()"
        style="background:#ffffff20;border:none;border-radius:8px;padding:3px 10px;color:#ffffffdd;cursor:pointer;font-size:10px;font-family:Cairo,sans-serif;font-weight:700">Hub</button>
      <span style="color:#ffffff55;font-size:10px">›</span>
      <button onclick="S.igcseTopic=null;render()"
        style="background:#ffffff20;border:none;border-radius:8px;padding:3px 10px;color:#ffffffdd;cursor:pointer;font-size:10px;font-family:Cairo,sans-serif;font-weight:700">${subj.label}</button>
      <span style="color:#ffffff55;font-size:10px">›</span>
      <span style="font-size:10px;color:#ffffffbb">${ch.title}</span>
    </div>
    <!-- Topic title + progress -->
    <div style="font-size:18px;font-weight:900;color:#fff;margin-bottom:4px;line-height:1.3">${tp.title}</div>
    <div style="display:flex;align-items:center;justify-content:space-between;margin-top:2px">
      <div style="font-size:10px;color:#ffffffaa">${subj.icon} ${subj.label} · ${board.icon} ${board.short} · Topic ${curIdx+1} of ${allTopics.length}</div>
      <button onclick="window.print()" title="Print / Save as PDF"
        style="background:#ffffff25;border:none;border-radius:8px;padding:4px 10px;color:#fff;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif;font-weight:700">
        🖨️ Print
      </button>
    </div>
    <!-- Mini progress bar -->
    <div style="margin-top:10px;height:3px;background:#ffffff25;border-radius:2px">
      <div style="height:100%;width:${Math.round((curIdx+1)/allTopics.length*100)}%;background:#fff;border-radius:2px;transition:.4s"></div>
    </div>
  </div>
  <!-- Tabs -->
  <div style="display:flex;gap:6px;padding:0 12px;margin-bottom:14px">${tabs}</div>
  <!-- Tab Content -->
  <div style="padding:0 12px">${tabContent}</div>
  <!-- Next / Prev navigation -->
  <div style="display:flex;gap:10px;padding:16px 12px 0;justify-content:space-between">
    ${prevT?`<button onclick="S.igcseChapter=${prevT.ci};S.igcseTopic=${prevT.ti};S.igcseTab='notes';render()"
      style="padding:10px 16px;border:1px solid var(--border);border-radius:12px;background:var(--bg-card);cursor:pointer;font-size:12px;color:var(--text);font-family:Cairo,sans-serif;font-weight:700;display:flex;align-items:center;gap:6px">
      ‹ Previous
    </button>`:'<div></div>'}
    ${nextT?`<div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end">
      <button onclick="S.igcseDone=S.igcseDone||{};S.igcseDone['${S.igcseSubject}-${S.igcseChapter}-${S.igcseTopic}']=true;S.igcseChapter=${nextT.ci};S.igcseTopic=${nextT.ti};S.igcseTab='notes';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
        style="padding:11px 16px;border:none;border-radius:12px;background:#10B981;cursor:pointer;font-size:12px;color:#fff;font-family:Cairo,sans-serif;font-weight:700;box-shadow:0 2px 10px #10B98144;display:flex;align-items:center;gap:6px;white-space:nowrap">
        ✅ Mark Done &amp; Next →
      </button>
      <button onclick="S.igcseChapter=${nextT.ci};S.igcseTopic=${nextT.ti};S.igcseTab='notes';S.igcseFcIdx=0;S.igcseFcFlipped=false;render()"
        style="padding:8px 14px;border:1px solid ${subj.color}66;border-radius:10px;background:transparent;cursor:pointer;font-size:11px;color:${subj.color};font-family:Cairo,sans-serif;font-weight:600;display:flex;align-items:center;gap:4px">
        Skip →
      </button>
    </div>`:'<div></div>'}
  </div>
</div>`;
}

function tplTextbook() {
  const curData   = CURRICULA[S.curriculum] || CURRICULA.egypt;
  const gradeData = (curData.grades && (curData.grades[S.grade] || Object.values(curData.grades)[0])) || { label:'' };

  // ── If viewing a PDF ─────────────────────────────────────────────
  if (S.textbookUrl && S.textbookUrl !== 'home' && S.textbookUrl !== 'explain') {
    const viewUrl = S.textbookViewUrl || S.textbookUrl;
    const dlUrl   = S.textbookUrl;
    const isGdrive = viewUrl.includes('drive.google.com');
    // Mobile browsers can't render PDFs inline via <embed> — use Google's PDF viewer there
    const isMobile = /Android|iPhone|iPad|Mobile/i.test(navigator.userAgent) || window.innerWidth < 769;
    const isPdf    = /\.pdf(\?|$)/i.test(viewUrl);
    let viewer;
    if (isGdrive) {
      viewer = `<iframe src="${viewUrl}" allowfullscreen style="width:100%;height:calc(100vh - 110px);border:none;display:block"></iframe>`;
    } else if (isPdf && isMobile) {
      // Mobile browsers can't embed PDFs and Google's gview blocks iframes —
      // open the book in the browser tab (Chrome Android has a built-in PDF viewer)
      viewer = `
      <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;padding:40px 24px;text-align:center">
        <div style="font-size:64px">📖</div>
        <div style="font-size:16px;font-weight:900;color:var(--text)">${S.textbookActiveTitle ? esc(S.textbookActiveTitle) : 'الكتاب جاهز'}</div>
        <div style="font-size:13px;color:var(--text-muted);line-height:1.8">اضغط الزر لفتح الكتاب في المتصفح<br/>يمكنك القراءة والتكبير والتنقل بين الصفحات</div>
        <div style="font-size:12px;color:#F59E0B;background:#F59E0B18;border:1px solid #F59E0B44;border-radius:10px;padding:10px 16px;line-height:1.7">⏳ بعض الكتب حجمها كبير (60+ ميجا)<br/>قد تظهر صفحة بيضاء لدقيقة أثناء التحميل — انتظر قليلاً</div>
        <a href="${viewUrl}" target="_blank" rel="noopener"
          style="background:var(--primary);color:#fff;border-radius:14px;padding:14px 36px;font-size:16px;font-weight:900;text-decoration:none;font-family:Cairo,sans-serif;box-shadow:0 4px 14px #3B82F655">
          📖 ${S.lang==='en'?'Open the book':'فتح الكتاب'}
        </a>
        <button onclick="downloadBook('${dlUrl}','${esc(S.textbookActiveTitle||'كتاب')}')"
          style="background:var(--bg-card);border:1.5px solid var(--border);color:var(--text);border-radius:12px;padding:10px 26px;font-size:13px;font-weight:700;cursor:pointer;font-family:Cairo,sans-serif">
          ⬇️ ${S.lang==='en'?'Download':'تحميل الكتاب'}
        </button>
      </div>`;
    } else if (isPdf) {
      viewer = `<embed src="${viewUrl}" type="application/pdf" style="width:100%;height:calc(100vh - 110px);display:block">`;
    } else {
      viewer = `<iframe src="${viewUrl}" allowfullscreen style="width:100%;height:calc(100vh - 110px);border:none;display:block"></iframe>`;
    }
    return `
<div class="screen-header" style="gap:8px">
  <button id="tb-home" style="background:none;border:1px solid var(--border);border-radius:8px;padding:6px 12px;cursor:pointer;font-family:Cairo,sans-serif;font-size:12px;color:var(--text)">← رجوع</button>
  <div class="screen-title" style="font-size:13px">📖 ${S.textbookActiveTitle ? esc(S.textbookActiveTitle) : (S.lang==='en'?'Book Viewer':'عارض الكتاب')}</div>
  <button onclick="chatWith('${esc(curData.label)} — ${esc(S.textbookActiveSubj||'الكتاب المدرسي')}','أنت أستاذ متخصص في مادة ${esc(S.textbookActiveSubj||'هذه المادة')} وفق منهج ${esc(curData.label)}. الطالب يقرأ الكتاب المدرسي الرسمي الآن. اسأله: ما الموضوع أو الفصل الذي تريد شرحه أو تفسيره؟')"
    style="background:#10B981;color:#fff;border:none;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:800;cursor:pointer;font-family:Cairo,sans-serif;white-space:nowrap">
    🤖 ${S.lang==='en'?'Ask AI':'اسأل AI'}
  </button>
  <button onclick="downloadBook('${dlUrl}','${esc(S.textbookActiveTitle||'كتاب')}')"
    style="background:var(--primary);color:#fff;border:none;border-radius:8px;padding:6px 14px;font-size:12px;font-weight:700;cursor:pointer;font-family:Cairo,sans-serif">⬇️</button>
</div>
${viewer}`;
  }

  // ── Chapter Picker (Explain Mode) ────────────────────────────────
  if (S.textbookUrl === 'explain' && S.textbookExplainSubj) {
    const es = S.textbookExplainSubj;
    const chapters = S.textbookExplainChapters || [];
    const isEn = ['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);
    return `
<div class="screen-header" style="gap:8px">
  <button onclick="S.textbookUrl='home';S.textbookExplainSubj=null;S.textbookExplainChapters=null;render()"
    style="background:none;border:1px solid var(--border);border-radius:8px;padding:6px 12px;cursor:pointer;font-family:Cairo,sans-serif;font-size:12px;color:var(--text)">← ${isEn?'Back':'رجوع'}</button>
  <div class="screen-title" style="font-size:14px">${es.icon} ${esc(es.subj)}</div>
</div>
<div class="screen-body">
  <div style="background:linear-gradient(135deg,${es.color}22,${es.color}08);border:1px solid ${es.color}44;border-radius:16px;padding:16px;margin-bottom:20px;text-align:center">
    <div style="font-size:36px;margin-bottom:6px">${es.icon}</div>
    <div style="font-size:16px;font-weight:900;color:var(--text)">${esc(es.subj)}</div>
    <div style="font-size:12px;color:var(--text-muted);margin-top:4px">${esc(S.textbookExplainCurric||'')} · ${S.textbookExplainMode==='summary'?(isEn?'Choose a lesson to summarise':'اختر درساً للتلخيص'):(isEn?'Choose a lesson to explain':'اختر درساً للشرح')}</div>
  </div>

  ${S.textbookExplainLoading ? `
  <div style="text-align:center;padding:40px 20px">
    <div style="font-size:32px;margin-bottom:12px">⏳</div>
    <div style="font-size:14px;font-weight:700;color:var(--text-muted)">${isEn?'Loading lessons...':'جاري تحميل الدروس...'}</div>
  </div>` : S.textbookExplainError ? `
  <div style="text-align:center;padding:30px">
    <div style="color:#EF4444;font-size:14px;font-weight:700;margin-bottom:16px">${esc(S.textbookExplainError)}</div>
    <button onclick="openTextbookExplain(S.textbookExplainSubj,S.textbookExplainCurric,S.textbookExplainMode)"
      style="background:var(--primary);color:#fff;border:none;border-radius:12px;padding:12px 28px;font-size:14px;font-weight:800;cursor:pointer;font-family:Cairo,sans-serif">
      🔄 ${isEn?'Retry':'إعادة المحاولة'}
    </button>
  </div>` : `
  <div style="font-size:11px;font-weight:800;color:var(--text-muted);letter-spacing:1px;margin-bottom:12px">${isEn?'📋 LESSONS & CHAPTERS':'📋 الدروس والفصول'}</div>
  <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:20px">
    ${chapters.map((ch,i) => `
    <button class="tb-chapter-btn" data-ch="${esc(ch)}"
      style="display:flex;align-items:center;gap:14px;padding:14px 16px;background:var(--bg-card);
             border:1.5px solid var(--border);border-radius:14px;cursor:pointer;text-align:right;
             width:100%;font-family:Cairo,sans-serif;transition:.15s"
      onmouseover="this.style.borderColor='${es.color}';this.style.background='${es.color}08'"
      onmouseout="this.style.borderColor='var(--border)';this.style.background='var(--bg-card)'">
      <div style="width:34px;height:34px;border-radius:10px;background:${es.color}22;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:900;color:${es.color};flex-shrink:0">${i+1}</div>
      <div style="flex:1;text-align:right">
        <div style="font-size:13px;font-weight:800;color:var(--text)">${esc(ch)}</div>
      </div>
      <span style="color:${es.color};font-size:16px">&#x2190;</span>
    </button>`).join('')}
  </div>
  <button class="tb-chapter-btn" data-ch=""
    style="width:100%;padding:12px;margin-bottom:90px;background:${es.color}18;border:1.5px dashed ${es.color}55;border-radius:12px;
           cursor:pointer;font-family:Cairo,sans-serif;font-size:13px;font-weight:700;color:${es.color}">
    ✏️ ${isEn?'Ask about any other topic':'اسأل عن موضوع آخر'}
  </button>`}
</div>`;
  }

  // ── Book Library ─────────────────────────────────────────────────
  // Map S.grade to TEXTBOOK_DB key
  const gradeMap = { high:'high', middle:'middle', primary:'primary',
    prim1:'primary', prim2:'primary', prim3:'primary', prim4:'primary', prim5:'primary', prim6:'primary',
    prep1:'middle', prep2:'middle', prep3:'middle',
    high_med:'high', high_eng:'high', high_biz:'high', high_arts:'high',
    high1:'high1', high2:'high2', kg1:'primary', kg2:'primary',
    high2_sci:'high2', high2_lit:'high2', high3_sci:'high', high3_math:'high', high3_lit:'high',
    y1:'primary', y2:'primary', y3:'primary', y4:'primary', y5:'primary', y6:'primary',
    y7:'middle', y8:'middle', y9:'middle',
    k:'primary', g1:'primary', g2:'primary', g3:'primary', g4:'primary', g5:'primary',
    g6:'middle', g7:'middle', g8:'middle',
    c1:'primary', c2:'primary', c3:'primary', c4:'primary', c5:'primary',
    c6:'middle', c7:'middle', c8:'middle', c9:'middle', c10:'middle', c11:'high', c12:'high',
    az_p1:'primary', az_p2:'primary', az_p3:'primary', az_p4:'primary', az_p5:'primary', az_p6:'primary',
    az_m1:'middle', az_m2:'middle', az_m3:'middle', az_s1:'high', az_s2_sci:'high', az_s2_lit:'high', az_s3_sci:'high', az_s3_lit:'high',
    kl1:'primary', kl2:'primary', kl3:'primary', kl4:'primary', kl5:'middle', kl6:'middle', kl7:'middle', kl8:'middle', kl9:'middle', kl10:'high', kl11:'high', kl12:'high',
    pyp:'primary', myp1:'middle', myp2:'middle', myp3:'middle', myp4:'middle', myp5:'middle', dp1:'high', dp2:'high' };
  const dbEntry  = TEXTBOOK_DB[S.curriculum] || {};  // no Egyptian fallback — other countries shouldn't show Egyptian books
  // Per-year curricula (IGCSE y1–y9, American k–g12/ap) may have a shelf of their own; else the stage bucket.
  const gradeKey = (/^(y[0-9]|g[0-9]|k$|ap$|as$|a2$|olevel$|igcse$|ias$|ia2$|pyp$|myp[0-9]|dp[0-9]|c[0-9]|f$|cp$|ce[12]$|cm[12]$|sixieme$|cinquieme$|quatrieme$|troisieme$|seconde$|premiere$|terminale$|kl[0-9]|az_|prim[1-6]$|prep[1-3]$|high)/.test(S.grade) && S.grade in dbEntry) ? S.grade : (gradeMap[S.grade] || 'high');
  // A curriculum that declares a bucket means it, even an empty one: that shows the
  // "Books coming soon" panel instead of falling through to `high`. `american` declares
  // primary and middle empty on purpose -- OpenStax is college/high-school only, and this
  // fallback was offering College Algebra, Calculus and University Physics to 7-year-olds.
  let allGradeBooks = (gradeKey in dbEntry) ? dbEntry[gradeKey] : (dbEntry.high || []);
  // External (المعاصر / Archive.org) books — shown on website + Android, hidden inside the iOS app (Apple 3.1.1)
  if (!IS_IOS_APP && S.curriculum === 'egypt') {
    const extEntry = TEXTBOOK_DB.egypt_ext || {};
    // No fallback to .high here: egypt_ext is split per secondary year, and falling
    // back showed a third-secondary student 15 books from years 1 and 2 (and showed
    // each of high1/high2 the other year's). A missing bucket should show nothing.
    const extBooks = extEntry[gradeKey] || [];
    if (extBooks.length) allGradeBooks = allGradeBooks.concat(extBooks);
  }
  const subjFilter = (S.textbookSubjFilter||'').toLowerCase().trim();
  const gradeBooks = subjFilter
    ? allGradeBooks.filter(s => s.subj.toLowerCase().includes(subjFilter) || subjFilter.includes(s.subj.toLowerCase()))
    : allGradeBooks;

  const isAr = !['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);

  const q = encodeURIComponent(gradeData.label + ' ' + curData.label);

  const categories = [
    {
      title: '📚 كتب الوزارة والمناهج الرسمية',
      color: '#3B82F6',
      links: [
        { name:'بوابة التعليم المصري', url:'https://www.moe.gov.eg', icon:'🏛️', desc:'وزارة التربية والتعليم' },
        { name:'كتب مجانية PDF', url:`https://www.google.com/search?q=${q}+كتاب+وزارة+PDF`, icon:'📄', desc:'بحث عن كتاب الوزارة' },
        { name:'منصة حصص', url:'https://www.hessesplatform.com', icon:'🎯', desc:'منصة تعليم مصر الرسمية' },
        { name:'مكتبة الإسكندرية', url:'https://www.bibalex.org', icon:'📖', desc:'مكتبة رقمية عربية' },
      ]
    },
    {
      title: '🎬 فيديوهات وشروحات',
      color: '#EF4444',
      links: [
        { name:'YouTube — شرح المنهج', url:`https://www.youtube.com/results?search_query=${q}+شرح`, icon:'▶️', desc:'شروحات المدرسين' },
        { name:'Khan Academy عربي', url:`https://ar.khanacademy.org/search?page_search_query=${encodeURIComponent(S.subject)}`, icon:'🎓', desc:'دروس مجانية تفاعلية' },
        { name:'Nafham', url:`https://www.nafham.com/search?q=${encodeURIComponent(S.subject)}`, icon:'💡', desc:'منصة نفهم العربية' },
      ]
    },
    {
      title: '📝 ملخصات ومذكرات',
      color: '#10B981',
      links: [
        { name:'ملخصات PDF', url:`https://www.google.com/search?q=${q}+ملخص+PDF+مذكرة`, icon:'📋', desc:'ملخصات جاهزة للطباعة' },
        { name:'SlideShare', url:`https://www.slideshare.net/search/slideshow?searchfrom=header&q=${encodeURIComponent(S.subject+' '+gradeData.label)}`, icon:'📊', desc:'عروض تقديمية' },
        { name:'Docsity', url:`https://www.docsity.com/ar/search#url=/?query=${encodeURIComponent(S.subject)}`, icon:'📑', desc:'ملاحظات الطلاب' },
      ]
    },
    {
      title: '🔬 أدوات وتطبيقات',
      color: '#8B5CF6',
      links: [
        { name:'Wolfram Alpha', url:`https://www.wolframalpha.com/input?i=${encodeURIComponent(S.subject)}`, icon:'🧮', desc:'حل المسائل الرياضية' },
        { name:'GeoGebra', url:`https://www.geogebra.org/search/${encodeURIComponent(S.subject)}`, icon:'📐', desc:'هندسة تفاعلية' },
        { name:'Wikipedia عربي', url:`https://ar.wikipedia.org/wiki/${encodeURIComponent(S.subject)}`, icon:'🌐', desc:'موسوعة حرة' },
        { name:'Quizlet', url:`https://quizlet.com/search?query=${encodeURIComponent(S.subject+' '+gradeData.label)}&type=all`, icon:'🗂️', desc:'بطاقات تعليمية جاهزة' },
      ]
    },
  ];

  return `
<div class="screen-header" style="gap:8px">
  <button onclick="S.screen='home';render()" style="background:none;border:1px solid var(--border);border-radius:8px;padding:6px 12px;cursor:pointer;font-family:Cairo,sans-serif;font-size:12px;color:var(--text)">🏠 ${S.lang==='en'?'Home':'الرئيسية'}</button>
  <div class="screen-title">📚 ${S.lang==='en'?'Books':'مكتبة الكتب'}</div>
  ${subjFilter ? `<button onclick="S.textbookSubjFilter='';render()" style="margin-right:auto;background:#6366F120;border:1px solid #6366F155;border-radius:8px;padding:4px 10px;font-size:11px;font-weight:700;color:#818CF8;cursor:pointer;font-family:Cairo,sans-serif">✕ ${S.lang==='en'?'All Books':'كل الكتب'}</button>` : ''}
</div>
<div class="screen-body">

  <!-- Header -->
  <div style="background:linear-gradient(135deg,#1E293B,#253047);border:1px solid #3B82F633;border-radius:16px;padding:16px;margin-bottom:20px;display:flex;align-items:center;gap:14px">
    <div style="font-size:40px">📚</div>
    <div>
      <div style="font-size:16px;font-weight:900;color:var(--text)">${S.lang==='en'?'Official Textbook Library':'مكتبة كتب الوزارة'}</div>
      <div style="font-size:12px;color:var(--text-muted);margin-top:2px">${curData.label} · ${gradeData.label} · ${S.lang==='en'?'Read or download the book in the app':'اقرأ الكتاب مباشرة داخل التطبيق'}</div>
    </div>
  </div>

  <!-- Books for current grade -->
  ${gradeBooks.length > 0 ? `
  <div style="margin-bottom:24px">
    <div style="font-size:13px;font-weight:800;color:var(--text-muted);margin-bottom:12px">📖 ${S.lang==='en'?'Books':'كتب'} ${gradeData.label}</div>
    <div style="display:flex;flex-direction:column;gap:10px">
      ${gradeBooks.map((subj) => `
      <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:14px;overflow:hidden">
        <div style="display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid var(--border);background:${subj.color}11">
          <span style="font-size:22px">${subj.icon}</span>
          <span style="flex:1;font-size:14px;font-weight:900;color:var(--text)">${esc(subj.subj)}</span>
          <div style="display:flex;gap:5px;flex-shrink:0">
            <button class="tb-explain-btn" data-subj="${esc(subj.subj)}" data-curric="${esc(curData.label)}" data-mode="explain"
              style="background:${subj.color};color:#fff;border:none;border-radius:8px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:Cairo,sans-serif;white-space:nowrap">
              🤖 ${S.lang==='en'?'Explain':'اشرح'}
            </button>
            <button class="tb-explain-btn" data-subj="${esc(subj.subj)}" data-curric="${esc(curData.label)}" data-mode="summary"
              style="background:#10B981;color:#fff;border:none;border-radius:8px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:Cairo,sans-serif;white-space:nowrap">
              📋 ${S.lang==='en'?'Summary':'ملخص'}
            </button>
          </div>
        </div>
        <div style="display:flex;flex-direction:column;gap:0">
          ${subj.books.filter(b => !IS_IOS_APP || !b.external).map((book,bi) => `
          <div style="display:flex;align-items:center;gap:12px;padding:12px 16px;${bi>0?'border-top:1px solid var(--border);':''}">
            <div style="width:40px;height:52px;border-radius:6px;background:${subj.color}22;display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0">📄</div>
            <div style="flex:1;text-align:right">
              <div style="font-size:13px;font-weight:800;color:var(--text)">${esc(book.title)}</div>
              <div style="font-size:11px;color:var(--text-muted);margin-top:2px">${esc(book.term||'')}</div>
              <div style="display:inline-block;margin-top:4px;background:${subj.color}22;color:${subj.color};font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px">${book.badge||(S.lang==='en'?'📚 Ministry of Education':'📚 وزارة التعليم')}</div>
            </div>
            <div style="display:flex;flex-direction:column;gap:5px;flex-shrink:0">
              ${book.external ? `
              <a href="${book.url}" target="_blank" rel="noopener"
                style="background:${subj.color};color:#fff;font-size:11px;font-weight:700;padding:6px 12px;border-radius:8px;border:none;cursor:pointer;font-family:Cairo,sans-serif;display:block;text-decoration:none;text-align:center;white-space:nowrap">
                📖 ${S.lang==='en'?'Read':'اقرأ الكتاب'}
              </a>` : `
              <button onclick="downloadBook('${book.url}','${esc(book.title)}')"
                style="background:${subj.color};color:#fff;font-size:11px;font-weight:700;padding:6px 12px;border-radius:8px;border:none;cursor:pointer;font-family:Cairo,sans-serif;display:block;text-align:center;white-space:nowrap">
                ⬇️ ${S.lang==='en'?'Download':'تحميل'}
              </button>
              <a href="${book.viewUrl || book.url}" target="_blank" rel="noopener"
                style="background:transparent;color:${subj.color};font-size:11px;font-weight:700;padding:5px 12px;border-radius:8px;border:1px solid ${subj.color};cursor:pointer;font-family:Cairo,sans-serif;display:block;text-decoration:none;text-align:center;white-space:nowrap">
                📖 ${S.lang==='en'?'Open':'فتح'}
              </a>`}
            </div>
          </div>`).join('')}
        </div>
      </div>`).join('')}
    </div>
  </div>` : `
  <div style="background:var(--bg-card);border:1px dashed var(--border);border-radius:14px;padding:32px;text-align:center;margin-bottom:20px">
    <div style="font-size:40px;margin-bottom:8px">📚</div>
    <div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:4px">${S.lang==='en'?'Books coming soon':'الكتب قيد الإضافة'}</div>
    <div style="font-size:12px;color:var(--text-muted)">${S.lang==='en'?`${curData.label} books are being added gradually`:`يتم إضافة كتب ${curData.label} تدريجياً`}</div>
  </div>`}

  <!-- Online Resources -->
  <div>
    <div style="font-size:13px;font-weight:800;color:var(--text-muted);margin-bottom:12px">🌐 ${S.lang==='en'?'More learning resources':'مصادر تعليمية إضافية'}</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px">
      ${[
        { name:'Khan Academy', icon:'🎓', color:'#14BF96', url:'https://ar.khanacademy.org' },
        { name:'نفهم', icon:'💡', color:'#3B82F6', url:'https://www.nafham.com' },
        { name:'GeoGebra', icon:'📐', color:'#9B4DCA', url:'https://www.geogebra.org' },
        { name:'Wolfram Alpha', icon:'🧮', color:'#F59E0B', url:'https://www.wolframalpha.com' },
      ].map(r=>`
      <a href="${r.url}" target="_blank" rel="noopener"
        style="display:flex;flex-direction:column;align-items:center;gap:8px;padding:16px 10px;background:var(--bg-card);border:1px solid var(--border);border-radius:12px;text-decoration:none;cursor:pointer;transition:.2s"
        onmouseover="this.style.borderColor='${r.color}'" onmouseout="this.style.borderColor='var(--border)'">
        <span style="font-size:26px">${r.icon}</span>
        <span style="font-size:12px;font-weight:700;color:var(--text)">${r.name}</span>
        <span style="font-size:10px;color:${r.color};font-weight:700">↗ ${S.lang==='en'?'Open':'فتح'}</span>
      </a>`).join('')}
    </div>
  </div>

</div>`;
}

