// ── Textbook Explain: chapter picker ─────────────────────────────
function openTextbookExplainByName(subjName, curricLabel, mode) {
  const gradeMap = { high:'high', middle:'middle', primary:'primary',
    prim1:'primary', prim2:'primary', prim3:'primary', prim4:'primary', prim5:'primary', prim6:'primary',
    prep1:'middle', prep2:'middle', prep3:'middle',
    high_med:'high', high_eng:'high', high_biz:'high', high_arts:'high',
    high1:'high1', high2:'high2', kg1:'primary', kg2:'primary',
    high2_sci:'high2', high2_lit:'high2', high3_sci:'high', high3_math:'high', high3_lit:'high',
    y1:'primary', y2:'primary', y3:'primary', y4:'primary', y5:'primary', y6:'primary',
    y7:'middle', y8:'middle', y9:'middle',
    k:'primary', g1:'primary', g2:'primary', g3:'primary', g4:'primary', g5:'primary',
    g6:'middle', g7:'middle', g8:'middle',
    c1:'primary', c2:'primary', c3:'primary', c4:'primary', c5:'primary',
    c6:'middle', c7:'middle', c8:'middle', c9:'middle', c10:'middle', c11:'high', c12:'high',
    az_p1:'primary', az_p2:'primary', az_p3:'primary', az_p4:'primary', az_p5:'primary', az_p6:'primary',
    az_m1:'middle', az_m2:'middle', az_m3:'middle', az_s1:'high', az_s2_sci:'high', az_s2_lit:'high', az_s3_sci:'high', az_s3_lit:'high',
    kl1:'primary', kl2:'primary', kl3:'primary', kl4:'primary', kl5:'middle', kl6:'middle', kl7:'middle', kl8:'middle', kl9:'middle', kl10:'high', kl11:'high', kl12:'high',
    pyp:'primary', myp1:'middle', myp2:'middle', myp3:'middle', myp4:'middle', myp5:'middle', dp1:'high', dp2:'high' };
  const dbEntry  = TEXTBOOK_DB[S.curriculum] || {};  // no Egyptian fallback — other countries shouldn't show Egyptian books
  // Per-year curricula (IGCSE y1–y9, American k–g12/ap) may have a shelf of their own; else the stage bucket.
  const gradeKey = (/^(y[0-9]|g[0-9]|k$|ap$|as$|a2$|olevel$|igcse$|ias$|ia2$|pyp$|myp[0-9]|dp[0-9]|c[0-9]|f$|cp$|ce[12]$|cm[12]$|sixieme$|cinquieme$|quatrieme$|troisieme$|seconde$|premiere$|terminale$|kl[0-9]|az_|prim[1-6]$|prep[1-3]$|high)/.test(S.grade) && S.grade in dbEntry) ? S.grade : (gradeMap[S.grade] || 'high');
  const books    = (gradeKey in dbEntry) ? dbEntry[gradeKey] : (dbEntry.high || []);  // declared bucket wins, even if empty
  const subj     = books.find(s => s.subj === subjName) || books.find(s => s.subj.toLowerCase() === subjName.toLowerCase());
  if (!subj) return;
  openTextbookExplain(subj, curricLabel, mode);
}

function openTextbookExplain(subj, curricLabel, mode) {
  S.textbookUrl             = 'explain';
  S.textbookExplainSubj     = subj;
  S.textbookExplainCurric   = curricLabel;
  S.textbookExplainMode     = mode || 'explain';
  S.textbookExplainChapters = null;
  S.textbookExplainLoading  = true;
  S.textbookExplainError    = null;
  render();
  loadTextbookChapters(subj, curricLabel);
}

async function loadTextbookChapters(subj, curricLabel) {
  const bookTitle0 = (subj.books && subj.books[0] && subj.books[0].title) || subj.subj;
  const cacheKey = 'tbch_' + S.curriculum + '_' + bookTitle0;
  // Cached chapter list — avoid re-asking the server for the same book
  try {
    const cached = localStorage.getItem(cacheKey);
    if (cached) {
      S.textbookExplainChapters = JSON.parse(cached);
      S.textbookExplainLoading = false;
      render();
      return;
    }
  } catch(_) {}
  try {
    const bookTitle = bookTitle0;
    const isEn = ['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);
    const prompt = isEn
      ? `List the main chapters or units of "${bookTitle}" (${subj.subj}, ${curricLabel} curriculum). Return ONLY a valid JSON array of chapter/unit names as strings, nothing else. Maximum 15 items. Keep names concise. Example: ["Chapter 1: Forces and Motion","Chapter 2: Energy","Chapter 3: Waves"]`
      : `اذكر الفصول والدروس الرئيسية في كتاب "${bookTitle}" (مادة ${subj.subj}، منهج ${curricLabel}). أرجع فقط مصفوفة JSON صالحة من أسماء الدروس كنصوص، بدون أي شيء آخر. الحد الأقصى 15 درساً. مثال: ["الفصل الأول: القوى والحركة","الفصل الثاني: الطاقة"]`;
    const { stage, grade, curriculum } = gradeToAPI();
    const body = {
      messages:   [{ role: 'user', content: prompt }],
      subject:    subj.subj,
      country:    S.curriculum,
      curriculum,
      stage,
      grade,
    };
    // Retry up to 3 times on rate-limit, waiting between attempts
    let d, lastErr;
    for (let attempt = 0; attempt < 3; attempt++) {
      try { d = await req('/chat', 'POST', body); lastErr = null; break; }
      catch(e) {
        lastErr = e;
        const isRate = /الحد الأقصى|rate|429|كثرة/i.test(e.message || '');
        if (!isRate || attempt === 2) throw e;
        await new Promise(r => setTimeout(r, 6000 * (attempt + 1)));
        if (S.textbookUrl !== 'explain') return; // user left the screen
      }
    }
    const raw = (d.content || d.reply || d.message || d.response || '').trim();
    const match = raw.match(/\[[\s\S]*\]/);
    S.textbookExplainChapters = match ? JSON.parse(match[0]) : [raw];
    if (match) { try { localStorage.setItem(cacheKey, match[0]); } catch(_) {} }
  } catch(e) {
    S.textbookExplainError = (e.message && /الحد الأقصى|rate|429/i.test(e.message))
      ? (S.lang==='en' ? '⏳ Server is busy — wait a few seconds then tap "Retry"' : '⏳ الخادم مشغول — انتظر ثوانٍ ثم اضغط "إعادة المحاولة"')
      : e.message;
  } finally {
    S.textbookExplainLoading = false;
    render();
  }
}

function explainTextbookChapter(subj, curricLabel, chapter, mode) {
  const isEn = ['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);
  const isSummary = mode === 'summary';
  if (!chapter) {
    chatWith(`${subj} — ${curricLabel}`, isEn
      ? `You are an expert teacher for ${subj} (${curricLabel} curriculum). The student is using the official textbook. Respond ONLY in English — do not use any Arabic words. Ask them: "Which chapter or topic would you like me to ${isSummary?'summarise':'explain in detail'}?"`
      : `أنت أستاذ متخصص في مادة ${subj} وفق منهج ${curricLabel}. الطالب يدرس من الكتاب المدرسي الرسمي. اسأله: "ما الدرس أو الموضوع الذي تريد ${isSummary?'تلخيصه':'أن أشرحه لك بالتفصيل'}؟"`);
    return;
  }
  let prompt;
  if (isSummary) {
    prompt = isEn
      ? `You are an expert ${subj} teacher using the ${curricLabel} official textbook. Respond ONLY in English — do not use any Arabic words.\n\nWrite a comprehensive smart summary for "${chapter}":\n\n## Key Points\n## Important Definitions\n## Core Formulas / Rules (if applicable)\n## Quick Examples\n## What to Remember for the Exam\n\nMake it concise, well-structured, and easy to revise from.`
      : `أنت أستاذ متخصص في مادة ${subj} وفق منهج ${curricLabel}، تلخص من الكتاب المدرسي الرسمي.\n\nاكتب ملخصاً ذكياً شاملاً لـ "${chapter}" يتضمن:\n\n## النقاط الأساسية\n## التعريفات المهمة\n## القوانين والقواعد الأساسية (إن وجدت)\n## أمثلة سريعة\n## ما يجب حفظه للامتحان\n\nاجعله مختصراً ومنظماً وسهل المراجعة.`;
  } else {
    prompt = isEn
      ? `You are an expert ${subj} teacher (${curricLabel} official textbook). Respond ONLY in English — do not use any Arabic words. Write a COMPLETE textbook-chapter lesson on "${chapter}" so the student needs NO other source. Start immediately, no questions.\n\nIdentify only the 5-6 MAIN sub-topics (do NOT over-fragment). For EACH main sub-topic you MUST write at least 250 words: (1) clear definition, (2) everyday analogy, (3) how & why it works step by step from first principles, (4) TWO worked examples (basic + harder), each step by step, (5) the common misconception, (6) a real-world use.\n\nThen add: Common Mistakes, 5 practice questions WITH full worked solutions, and a short summary.\n\nThe whole lesson MUST be at least 2500 words — mandatory. Clear flowing paragraphs. Do not stop until every sub-topic is fully covered; always finish.`
      : `أنت أستاذ متخصص في ${subj} (الكتاب الرسمي لمنهج ${curricLabel}). اكتب درساً كاملاً بعمق فصل من كتاب مدرسي عن "${chapter}" بحيث لا يحتاج الطالب لأي مصدر آخر. ابدأ فوراً دون أسئلة.\n\nحدّد الأجزاء الفرعية الرئيسية فقط (٥ إلى ٦ — لا تُفرّط في التقسيم). ولكل جزء فرعي رئيسي اكتب ٢٥٠ كلمة على الأقل: ١) تعريف واضح، ٢) تشبيه من الحياة، ٣) كيف ولماذا يعمل خطوة بخطوة من الأساس، ٤) مثالان محلولان (بسيط وأصعب) خطوة بخطوة، ٥) الخطأ الشائع، ٦) استخدام واقعي.\n\nثم أضف: الأخطاء الشائعة، و٥ أسئلة تدريبية مع حلولها الكاملة، وملخصاً قصيراً.\n\nيجب ألا يقل الدرس عن ٢٥٠٠ كلمة — إلزامي. فقرات واضحة متصلة. لا تتوقف حتى تغطي كل جزء فرعي بالكامل، وأنهِ الدرس كاملاً.`;
  }
  // Show a clean label in chat (not the long instruction prompt); the AI still receives `prompt`.
  const cleanLabel = (isSummary ? (isEn ? '📋 Summarize: ' : '📋 لخّص لي: ') : (isEn ? '📖 Explain: ' : '📖 اشرح لي: ')) + chapter;
  chatWith(`${subj} — ${chapter}`, prompt, !isSummary, cleanLabel);  // full lesson = long-form; summaries stay normal length
}

function gradeToAPI() {
  const map = {
    // Arab grades
    primary:    { stage:'ابتدائي',  grade:'المرحلة الابتدائية' },
    prim1:      { stage:'ابتدائي',  grade:'الصف الأول الابتدائي' },
    prim2:      { stage:'ابتدائي',  grade:'الصف الثاني الابتدائي' },
    prim3:      { stage:'ابتدائي',  grade:'الصف الثالث الابتدائي' },
    prim4:      { stage:'ابتدائي',  grade:'الصف الرابع الابتدائي' },
    prim5:      { stage:'ابتدائي',  grade:'الصف الخامس الابتدائي' },
    prim6:      { stage:'ابتدائي',  grade:'الصف السادس الابتدائي' },
    middle:     { stage:'إعدادي',   grade:'المرحلة الإعدادية / المتوسطة' },
    prep1:      { stage:'إعدادي',   grade:'الصف الأول الإعدادي' },
    prep2:      { stage:'إعدادي',   grade:'الصف الثاني الإعدادي' },
    prep3:      { stage:'إعدادي',   grade:'الصف الثالث الإعدادي' },
    high:       { stage:'ثانوي',    grade:'المرحلة الثانوية' },
    high1:      { stage:'ثانوي',    grade:'الصف الأول الثانوي (تمهيدي)' },
    high_sci:   { stage:'ثانوي',    grade:'الفرع العلمي' },
    high_arts:  { stage:'ثانوي',    grade:'الفرع الأدبي' },
    high_med:   { stage:'ثانوي',    grade:'مسار الطب وعلوم الحياة' },
    high_eng:   { stage:'ثانوي',    grade:'مسار الهندسة والحاسب' },
    high_biz:   { stage:'ثانوي',    grade:'مسار الأعمال والتجارة' },
    high_arts2: { stage:'ثانوي',    grade:'مسار الآداب والفنون' },
    // International grades
    'Year 7-9':     { stage:'Lower Secondary', grade:'Year 7–9' },
    'Year 10-11':   { stage:'GCSE',            grade:'Year 10–11 (GCSE)' },
    'AS/A2':        { stage:'A-Level',         grade:'AS & A2 Level' },
    'Grade 6-10':   { stage:'Middle School',   grade:'Grade 6–10' },
    'Grade 11-12':  { stage:'High School',     grade:'Grade 11–12' },
    'MYP':          { stage:'IB',              grade:'MYP (Years 7–11)' },
    'DP':           { stage:'IB',              grade:'IB Diploma' },
  };
  const { stage, grade } = map[S.grade] || {
    stage: CURRICULA[S.curriculum]?.grades[S.grade]?.label || S.grade || 'Secondary',
    grade: CURRICULA[S.curriculum]?.grades[S.grade]?.label || S.grade || ''
  };
  const curriculum = CURRICULUM_LABELS[S.curriculum] || CURRICULA[S.curriculum]?.label || 'العام';
  return { stage, grade, curriculum };
}

function continueExplanation() {
  const inp = ge('f-msg');
  if (!inp || S.thinking) return;
  const isEn = ['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum);
  inp.value = isEn
    ? 'Continue the explanation exactly from where you stopped. Do not repeat anything you already said.'
    : 'أكمل الشرح من النقطة التي توقفت عندها بالضبط، ولا تعد أي شيء قلته سابقاً.';
  sendMsg();
}

async function sendMsg(opts) {
  // opts = { content, display } lets callers (e.g. chatWith) send a full instruction to the AI
  // while showing a clean, human-friendly label in the chat. Normal typing passes no opts.
  const hasOverride = opts && typeof opts === 'object' && typeof opts.content === 'string';
  const inp = ge('f-msg');
  const typed = inp ? inp.value.trim() : '';
  const txt   = hasOverride ? opts.content : typed;                       // sent to the AI
  const shown = hasOverride ? (opts.display || opts.content) : typed;     // shown in the chat bubble
  if (!txt || S.thinking) return;
  if (inp && !hasOverride) inp.value = '';

  const nowTime = new Date().toLocaleTimeString('ar-EG', { hour:'2-digit', minute:'2-digit' });
  S.messages.push({ role: 'user', content: txt, display: shown, time: nowTime });
  S.thinking = true; render();
  scrollChat();

  const { stage, grade, curriculum } = gradeToAPI();

  try {
    const d = await req('/chat', 'POST', {
      messages:   S.messages.slice(-12).map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: (m.content||'').substring(0,2000) })),
      country:    S.curriculum,
      curriculum,
      stage,
      grade,
      subject:    S.subject,
      userName:   S.user?.name || '',
      topics:     (() => {
        try {
          const cur = CURRICULA[S.curriculum];
          if (!cur) return [];
          const gradeData = cur.grades[S.grade] || Object.values(cur.grades)[0];
          if (!gradeData) return [];
          const subj = (gradeData.subjects || []).find(s => s.name === S.subject);
          return (subj && subj.topics) ? subj.topics.slice(0, 8) : [];
        } catch(e) { return []; }
      })(),
      longForm:   !!S._longFormNext,   // set by chatWith(...,true) for full lesson explanations
    });
    S._longFormNext = false;   // one-shot: only the triggering message is long-form

    const reply = (d.content || d.message || d.reply || '').trim()
      || (S.lang === 'en' ? '⚠️ No response — please try again.' : '⚠️ لم يصل رد — حاول مرة أخرى من فضلك.');
    const replyTime = new Date().toLocaleTimeString('ar-EG', { hour:'2-digit', minute:'2-digit' });
    S.messages.push({ role: 'assistant', content: reply, time: replyTime, truncated: !!d.truncated });
    // A short silent nod acknowledges the answer. Silent on purpose -- this fires on
    // every message, and the clip's spoken "تمام، ممتاز" would talk over the student
    // as they start reading. Skipped for error replies, which are not something to nod at.
    if (!reply.startsWith('⚠️')) kareemSay('nod', { silent: true });

    // XP + history + streak
    S.stats = S.stats || { xp:0, streak:1, totalChats:0, weeklyActivity:[0,0,0,0,0,0,0] };
    S.stats.xp += 10; S.stats.totalChats++;
    const day = new Date().getDay();
    S.stats.weeklyActivity[day] = (S.stats.weeklyActivity[day]||0)+1;
    // Update chat streak
    const todayDate = new Date().toDateString();
    const yesterdayDate = new Date(Date.now()-86400000).toDateString();
    if (S.stats.lastChatDate !== todayDate) {
      S.stats.streak = S.stats.lastChatDate === yesterdayDate ? (S.stats.streak||1)+1 : 1;
      S.stats.lastChatDate = todayDate;
      // Milestones only. Celebrating every single day would make it meaningless,
      // and these are the streak lengths worth actually marking.
      if ([3, 7, 14, 30, 50, 100].indexOf(S.stats.streak) !== -1) kareemSay('celebrate');
    }

    S.history.unshift({ date: new Date().toLocaleDateString('ar'), subject: S.subject, preview: txt.slice(0,60) });
    if (S.history.length > 50) S.history.pop();

  } catch(e) {
    const msg = e.message;
    if (msg.includes('daily_limit')) {
      S.messages.push({ role: 'assistant', content: '⚠️ وصلت للحد اليومي المجاني (5 أسئلة). سجّل الدخول أو اشترك في Pro للاستمرار.' });
    } else {
      S.messages.push({ role: 'assistant', content: `⚠️ ${msg}` });
    }
  }
  S.thinking = false; render(); scrollChat();
}

function scrollChat() {
  const c = ge('chat-msgs');
  if (c) setTimeout(() => { c.scrollTop = c.scrollHeight; }, 50);
}

/* ════════════════════════════════════════════════════════════
   GENERATION HELPERS
   ════════════════════════════════════════════════════════════ */
async function genFlashcards() {
  const en = S.lang === 'en';
  const { stage, grade, curriculum } = gradeToAPI();
  S.fcLoading = true; render();
  try {
    const d = await req('/study/flashcards', 'POST', {
      subject:    S.subject,
      topic:      S.subject,
      count:      10,
      country:    S.curriculum,
      curriculum,
      stage,
      grade,
    });
    // Server returns { cards: [{q, a}] } — map to {front, back}
    const raw = d.cards || d.flashcards || d;
    S.flashcards = Array.isArray(raw)
      ? raw.map(c => ({ front: c.q || c.front || c.question || '', back: c.a || c.back || c.answer || '' }))
          .filter(c => c.front && c.back)
      : [];
    S.fcIndex = 0; S.fcFlipped = false;
    if (S.flashcards.length) showToast(en ? `Generated ${S.flashcards.length} cards! 🗂️` : `تم توليد ${S.flashcards.length} بطاقة! 🗂️`, 'success');
    else showToast(en ? 'No cards generated — try again.' : 'لم يتم توليد بطاقات — حاول مرة أخرى.', 'error');
  } catch(e) { showToast(e.message, 'error'); }
  finally { S.fcLoading = false; render(); }
}

async function genQuiz() {
  const en = S.lang === 'en';
  const { stage, grade, curriculum } = gradeToAPI();
  S.quizLoading = true; render();
  try {
    const d = await req('/study/quiz', 'POST', {
      subject:    S.subject,
      topic:      S.subject,
      count:      10,
      country:    S.curriculum,
      curriculum,
      stage,
      grade,
    });
    // Server returns { questions: [{q, options, correct, explain}] }.
    // `correct` may be a numeric index, a letter (A–D), or the answer text — normalise all to an index.
    const raw = d.questions || d.quiz || d;
    S.quiz = Array.isArray(raw)
      ? raw.map(q => {
          const options = q.options || q.choices || [];
          let correct = q.correct;
          if (typeof correct === 'string') {
            const s = correct.trim();
            if (/^[A-Da-d]$/.test(s)) correct = s.toUpperCase().charCodeAt(0) - 65;      // "A" → 0
            else { const i = options.findIndex(o => String(o).trim() === s); correct = i >= 0 ? i : 0; }
          }
          if (typeof correct !== 'number' || correct < 0 || correct >= options.length) correct = 0;
          return {
            question:    q.q || q.question || '',
            options,
            correct,
            explanation: q.explain || q.explanation || '',
          };
        }).filter(q => q.question && q.options.length >= 2)
      : [];
    S.quizIndex = 0; S.quizAnswer = null; S.quizScore = 0;
    if (S.quiz.length) showToast(en ? `Generated ${S.quiz.length} questions! 📝` : `تم توليد ${S.quiz.length} سؤال! 📝`, 'success');
    else showToast(en ? 'No questions generated — try again.' : 'لم يتم توليد أسئلة — حاول مرة أخرى.', 'error');
  } catch(e) { showToast(e.message, 'error'); }
  finally { S.quizLoading = false; render(); }
}

async function doGenSummary() {
  const topic = ge('sum-topic')?.value?.trim() || S.subject;
  const { stage, grade, curriculum } = gradeToAPI();
  S.summaryLoading = true; S.summaryText = ''; render();
  try {
    const d = await req('/chat', 'POST', {
      messages: [{ role: 'user', content: `اكتب ملخصاً شاملاً وكاملاً ومنظماً لموضوع "${topic}" في مادة ${S.subject}. اجعله وافياً ومتعدد الأقسام: ## المقدمة، ## النقاط الأساسية (بالتفصيل)، ## التعريفات المهمة، ## القوانين والقواعد، ## أمثلة محلولة، ## الأخطاء الشائعة، ## أسئلة للمراجعة، ## خلاصة سريعة. استخدم عناوين ## وقوائم وتنسيق واضح. اكتب الأرقام والمعادلات كنص عادي فقط — بدون علامات $ أو رموز LaTeX إطلاقاً. اكتب ملخصاً مطوّلاً لا يقل عن ٨٠٠ كلمة.` }],
      country: S.curriculum, curriculum,
      stage, grade, subject: S.subject,
      userName: S.user?.name || '',
      longForm: true,
    });
    // Strip LaTeX $ delimiters the model adds (summaries should be plain text): "$152$" → 152, "$x^2$" → x^2.
    S.summaryText = (d.content || d.message || '')
      .replace(/\$\$([\s\S]*?)\$\$/g, '$1')       // $$ block $$ → block
      .replace(/\$([^\$\n]{1,200}?)\$/g, '$1')     // $ inline $ → inline
      .replace(/\$/g, '');                         // any stray $ left over
  } catch(e) { S.summaryText = `⚠️ ${e.message}`; }
  S.summaryLoading = false; render();
}

async function doGenMindMap() {
  const topic = ge('mm-topic')?.value?.trim() || S.subject;
  S.mindMapTopic = topic;
  const { stage, grade, curriculum } = gradeToAPI();
  try {
    showToast(S.lang==='en'?'Generating mind map…':'جارٍ توليد الخريطة...', 'info');
    const d = await req('/chat', 'POST', {
      messages: [{ role: 'user', content: `اعمل خريطة ذهنية لموضوع "${topic}". أرجع JSON فقط بالشكل: {"title":"${topic}","branches":[{"title":"فرع 1","children":[{"title":"تفصيل"}]}]}` }],
      country: S.curriculum, curriculum,
      stage, grade, subject: S.subject,
      userName: S.user?.name || '',
    });
    const text = d.content || d.message || '';
    const match = text.match(/\{[\s\S]*\}/);
    let parsed = null;
    if (match) {
      // AI JSON often has code fences / trailing commas / smart quotes — clean before parsing.
      const cleaned = match[0]
        .replace(/```[a-z]*\s*/gi, '')
        .replace(/,\s*([}\]])/g, '$1')
        .replace(/[""]/g, '"');
      try { parsed = JSON.parse(cleaned); } catch(_) { parsed = null; }
    }
    // Graceful fallback: never fail — build a simple one-level map from the text.
    S.mindMapData = (parsed && (parsed.branches || parsed.title))
      ? parsed
      : { title: topic, branches: [{ title: (text || topic).substring(0,120), children:[] }] };
    render(); showToast(S.lang==='en'?'Done! 🧠':'تم! 🧠', 'success');
  } catch(e) { showToast(e.message, 'error'); }
}


/* ════════════════════════════════════════════════════════════
   IMAGE SOLVING — Claude Vision
   ════════════════════════════════════════════════════════════ */
function triggerCamera() {
  const inp = document.getElementById('img-upload');
  if (inp) inp.click();
}

async function solveImage(file) {
  if (!file) return;
  const MAX = 4 * 1024 * 1024; // 4MB limit
  if (file.size > MAX) { showToast('الصورة كبيرة جداً (الحد 4MB)', 'error'); return; }

  // Convert to base64
  const reader = new FileReader();
  reader.onload = async (e) => {
    const dataUrl  = e.target.result;
    const base64   = dataUrl.split(',')[1];
    const mimeType = file.type || 'image/jpeg';

    // Show preview in chat
    S.messages.push({ role: 'user', content: '📸 صورة مرفقة — جارٍ الحل...' });
    S.imageThinking = true;
    render(); scrollChat();

    const { stage, grade, curriculum } = gradeToAPI();
    try {
      const d = await req('/chat/solve-image', 'POST', {
        imageBase64: base64,
        mediaType:   mimeType,
        country:     S.curriculum,
        curriculum,
        stage, grade,
        subject:     S.subject,
        userName:    S.user?.name || '',
        instruction: `اقرأ المسألة في الصورة وحلّها خطوة بخطوة في مادة ${S.subject}`,
      });
      const reply = d.content || d.message || d.reply || '';
      S.messages[S.messages.length - 1] = { role: 'user', content: '📸 حل مسألة بالصورة' };
      S.messages.push({ role: 'assistant', content: reply });
      S.stats = S.stats || { xp:0, streak:1, totalChats:0, weeklyActivity:[0,0,0,0,0,0,0] };
      S.stats.xp += 15; S.stats.totalChats++;
      saveLocal();
    } catch(e) {
      S.messages[S.messages.length - 1] = { role: 'user', content: '📸 حل مسألة بالصورة' };
      S.messages.push({ role: 'assistant', content: `⚠️ ${e.message}` });
    }
    S.imageThinking = false;
    render(); scrollChat();
  };
  reader.readAsDataURL(file);
}

/* ════════════════════════════════════════════════════════════
   VOICE INPUT — Whisper STT
   ════════════════════════════════════════════════════════════ */
let _mediaRecorder = null;
let _audioChunks   = [];

async function toggleRecording() {
  if (S.recording) {
    stopRecording();
  } else {
    await startRecording();
  }
}

async function startRecording() {
  // Try Web Speech API first (instant, no upload) — iOS/Safari support it
  const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (SpeechRec && !navigator.mediaDevices) {
    startSpeechRecognition();
    return;
  }
  try {
    const mimeType = MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm'
                   : MediaRecorder.isTypeSupported('audio/mp4')  ? 'audio/mp4'
                   : '';
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    _audioChunks = [];
    _mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : {});
    _mediaRecorder.ondataavailable = e => { if (e.data.size > 0) _audioChunks.push(e.data); };
    _mediaRecorder.onstop = transcribeAudio;
    _mediaRecorder.start();
    S.recording = true;
    render();
    showToast(S.lang==='en'?'🎤 Recording... tap again to stop':'🎤 جارٍ التسجيل... اضغط مرة ثانية للإيقاف', 'info');
    // Auto-stop after 30s
    setTimeout(() => { if (S.recording) stopRecording(); }, 30000);
  } catch(e) {
    // MediaRecorder failed — try Web Speech API as fallback
    const SpeechRecFallback = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecFallback) {
      startSpeechRecognition();
    } else {
      showToast(S.lang==='en'?'Microphone access denied: '+e.message:'تعذّر الوصول للميكروفون: ' + e.message, 'error');
    }
  }
}

let _speechRec = null;
function startSpeechRecognition() {
  const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRec) { showToast('الميكروفون غير مدعوم في هذا المتصفح', 'error'); return; }
  _speechRec = new SpeechRec();
  _speechRec.lang = S.lang === 'en' ? 'en-US' : 'ar-EG';
  _speechRec.continuous = false;
  _speechRec.interimResults = false;
  _speechRec.onresult = e => {
    const text = e.results[0][0].transcript;
    const inp = document.getElementById('f-msg');
    if (inp && text) { inp.value = text; inp.focus(); }
    showToast('✅ ' + (S.lang==='en'?'Done!':'تم!'), 'success');
  };
  _speechRec.onerror = e => showToast('⚠️ ' + (e.error||'error'), 'error');
  _speechRec.onend = () => { S.recording = false; render(); };
  _speechRec.start();
  S.recording = true;
  render();
  showToast(S.lang==='en'?'🎤 Listening...':'🎤 جارٍ الاستماع...', 'info');
}

function stopRecording() {
  if (_mediaRecorder && _mediaRecorder.state !== 'inactive') {
    _mediaRecorder.stop();
    _mediaRecorder.stream.getTracks().forEach(t => t.stop());
  }
  if (_speechRec) { try { _speechRec.stop(); } catch {} _speechRec = null; }
  S.recording = false;
  render();
}

async function transcribeAudio() {
  if (!_audioChunks.length) return;
  showToast('جارٍ تحويل الصوت لنص...', 'info');
  const blob    = new Blob(_audioChunks, { type: 'audio/webm' });
  const formData = new FormData();
  formData.append('audio', blob, 'voice.webm');

  try {
    const h = {};
    if (S.token) h['Authorization'] = `Bearer ${S.token}`;
    const r = await fetch(API + '/study/transcribe', { method:'POST', headers:h, body:formData });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || 'فشل التحويل');
    const text = d.text || d.transcript || '';
    if (text) {
      const inp = document.getElementById('f-msg');
      if (inp) { inp.value = text; inp.focus(); }
      showToast('✅ تم التحويل!', 'success');
    }
  } catch(e) {
    showToast('⚠️ ' + e.message, 'error');
  }
}

/* ════════════════════════════════════════════════════════════
   PDF EXPORT
   ════════════════════════════════════════════════════════════ */
async function exportPDF() {
  const topic = ge('sum-topic')?.value?.trim() || S.subject;
  const type  = ge('pdf-type')?.value || 'summary';
  const { stage, grade, curriculum } = gradeToAPI();
  const typeLabel = { summary: 'ملخص شامل', formulas: 'قوانين ومعادلات', questions: 'أسئلة تدريبية', mindmap: 'خريطة ذهنية' }[type] || type;

  showToast(S.lang==='en'?'Preparing the file…':'جارٍ تجهيز الملف...', 'info');
  try {
    let html;
    const onScreen = (S.summaryText || '').trim();
    if (onScreen && !onScreen.startsWith('⚠️')) {
      // Use the COMPLETE on-screen summary (flows to multiple pages) instead of regenerating a short one.
      const t = onScreen.replace(/^```html?\s*/i, '').replace(/```\s*$/, '').trim();
      html = /<(div|h[1-6]|p|ul|ol|table)[\s>]/i.test(t) ? t : md(onScreen);
    } else {
      const d = await req('/pdf/summary', 'POST', {
        subject: S.subject, topic, grade, stage, curriculum,
        country: S.curriculum, type,
      });
      html = d.html || d.content || d.text || '';
    }
    const win = window.open('', '_blank', 'width=860,height=700');
    if (!win) { showToast('يرجى السماح بالنوافذ المنبثقة', 'error'); return; }
    const dateStr = new Date().toLocaleDateString('ar-EG', { year:'numeric', month:'long', day:'numeric' });
    win.document.write(`<!DOCTYPE html><html dir="rtl" lang="ar"><head>
      <meta charset="UTF-8"/>
      <title>${topic} — \u{623}\u{633}\u{62A}\u{627}\u{630} AI</title>
      <style>
        @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap');
        *{box-sizing:border-box;margin:0;padding:0}
        body{font-family:'Cairo',Arial,sans-serif;direction:rtl;background:#fff;color:#1E293B;font-size:14px;line-height:1.9}
        .page{max-width:760px;margin:0 auto;padding:40px 48px}
        /* Header */
        .pdf-header{display:flex;align-items:center;justify-content:space-between;padding-bottom:16px;border-bottom:3px solid #1E40AF;margin-bottom:28px}
        .pdf-logo{font-size:28px;font-weight:900;color:#1E40AF}
        .pdf-meta{font-size:11px;color:#64748B;text-align:left}
        /* Title */
        .pdf-title{font-size:22px;font-weight:900;color:#0F172A;margin-bottom:6px}
        .pdf-subtitle{font-size:13px;color:#64748B;margin-bottom:24px;padding-bottom:16px;border-bottom:1px solid #E2E8F0}
        /* Content */
        h1,h2{color:#1E40AF;margin:20px 0 10px}
        h1{font-size:18px} h2{font-size:16px}
        h3{color:#1E40AF;font-size:15px;margin:16px 0 8px}
        p{margin-bottom:12px;color:#334155}
        ul,ol{padding-right:20px;margin-bottom:12px}
        li{margin-bottom:6px;color:#334155}
        table{border-collapse:collapse;width:100%;margin-bottom:16px}
        th{background:#1E40AF;color:#fff;padding:8px 12px;font-size:13px;text-align:right}
        td{border:1px solid #E2E8F0;padding:8px 12px;font-size:13px}
        tr:nth-child(even) td{background:#F8FAFC}
        code{background:#F1F5F9;padding:2px 6px;border-radius:4px;font-size:12px;color:#7C3AED}
        pre{background:#F1F5F9;padding:14px;border-radius:8px;margin-bottom:14px;overflow:auto;font-size:12px;direction:ltr;text-align:left}
        strong{color:#0F172A}
        blockquote{border-right:4px solid #1E40AF;padding:10px 16px;background:#EFF6FF;margin:14px 0;border-radius:0 8px 8px 0}
        hr{border:none;border-top:1px solid #E2E8F0;margin:20px 0}
        /* Footer */
        .pdf-footer{margin-top:32px;padding-top:16px;border-top:1px solid #E2E8F0;font-size:11px;color:#94A3B8;display:flex;justify-content:space-between}
        /* Print */
        @media print{
          .pdf-header{page-break-inside:avoid}
          h2,h3{page-break-after:avoid}
          .no-print{display:none!important}
          body{font-size:13px}
        }
        /* Print button */
        .print-btn{position:fixed;bottom:24px;left:24px;background:#1E40AF;color:#fff;border:none;border-radius:50px;padding:12px 24px;font-family:'Cairo',sans-serif;font-size:15px;font-weight:700;cursor:pointer;box-shadow:0 4px 20px rgba(30,64,175,0.4);z-index:999}
        .print-btn:hover{background:#1D4ED8}
      </style>
    </head><body>
    <button class="print-btn no-print" onclick="window.print()">📥 طباعة / حفظ PDF</button>
    <div class="page">
      <div class="pdf-header">
        <div class="pdf-logo">🎓 \u{623}\u{633}\u{62A}\u{627}\u{630} AI</div>
        <div class="pdf-meta">${dateStr}<br/>${curriculum}</div>
      </div>
      <div class="pdf-title">${esc(topic)}</div>
      <div class="pdf-subtitle">${typeLabel} &nbsp;&bull;&nbsp; ${esc(S.subject)} &nbsp;&bull;&nbsp; ${grade}</div>
      ${html}
      <div class="pdf-footer">
        <span>\u{623}\u{633}\u{62A}\u{627}\u{630} AI &mdash; \u{645}\u{646}\u{635}\u{629} \u{627}\u{644}\u{62A}\u{639}\u{644}\u{64A}\u{645} \u{627}\u{644}\u{630}\u{643}\u{64A}</span>
        <span>${dateStr}</span>
      </div>
    </div>
    <script>
      // Auto-trigger print after fonts load
      window.onload = function() { setTimeout(function(){ window.print(); }, 1200); };
    </script>
    </body></html>`);
    win.document.close();
  } catch(e) { showToast('\u{26A0}️ ' + e.message, 'error'); }
}

