async function genPaper() {
  const subject    = ge('pp-subject')?.value?.trim();
  const topic      = ge('pp-topic')?.value?.trim() || '';
  const difficulty = ge('pp-difficulty')?.value || 'mixed';
  const numQ       = parseInt(ge('pp-num')?.value || '10');
  const btn        = ge('b-gen-paper');
  const outEl      = ge('paper-output');
  const contentEl  = ge('paper-content');
  const errEl      = ge('paper-error');

  if (!subject) { showToast('أدخل اسم المادة', 'error'); return; }
  if (errEl) errEl.style.display = 'none';
  outEl.style.display = 'none';
  btn.disabled = true;
  btn.textContent = '⏳ جاري التوليد... قد يأخذ دقيقة';

  try {
    const ctrl    = new AbortController();
    const tmr     = setTimeout(() => ctrl.abort(), 120000);
    const token   = S.token || localStorage.getItem('oa_token') || '';
    const resp = await fetch(API + '/papers/generate', {
      method:  'POST',
      headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: 'Bearer ' + token } : {}) },
      body: JSON.stringify({
        country: S.country || 'egypt', curriculum: S.curriculum || 'gov',
        grade: S.grade || '', subject, topic, difficulty, numQuestions: numQ, lang: S.lang || 'ar',
      }),
      signal: ctrl.signal,
    });
    clearTimeout(tmr);
    const data = await resp.json();
    if (!resp.ok || !data.paper) throw new Error(data.error || 'لم يتم توليد الامتحان');
    contentEl.innerHTML = md(data.paper);
    renderMath(contentEl);
    outEl.style.display = 'block';
    outEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } catch(e) {
    const msg = e.name === 'AbortError' ? 'انتهى الوقت — جرّب عدد أسئلة أقل' : e.message;
    if (errEl) { errEl.textContent = '❌ ' + msg; errEl.style.display = 'block'; }
    else showToast('❌ ' + msg, 'error');
  } finally {
    btn.disabled = false; btn.textContent = '✨ ولّد ورقة الامتحان';
  }
}

async function loadUploadedPapers() {
  const wrap = ge('pp-uploaded-list');
  if (!wrap) return;
  try {
    const params = new URLSearchParams({ country: S.country||'', curriculum: S.curriculum||'', subject: S.subject||'' });
    const r = await fetch(API + '/papers/list?' + params);
    const papers = await r.json();
    if (!Array.isArray(papers) || !papers.length) {
      wrap.innerHTML = '<div style="font-size:12px;color:var(--text-muted);text-align:center;padding:16px">لا توجد امتحانات رسمية مرفوعة بعد</div>';
      return;
    }
    wrap.innerHTML = papers.map(p => `
      <div style="padding:10px;background:var(--bg);border-radius:8px;margin-bottom:8px;display:flex;align-items:center;gap:10px">
        <div style="font-size:24px">📄</div>
        <div style="flex:1">
          <div style="font-weight:700;font-size:13px">${esc(p.title)}</div>
          <div style="font-size:11px;color:var(--text-muted)">${esc(p.subject)} — ${p.year||'بدون سنة'} — ${esc(p.curriculum)}</div>
        </div>
        <button onclick="usePaperInChat('${p._id}','${esc(p.title)}')"
          style="background:var(--primary);border:none;color:#fff;border-radius:8px;padding:6px 10px;cursor:pointer;font-size:11px;font-family:Cairo,sans-serif">
          💬 حلّ معي
        </button>
      </div>`).join('');
  } catch(e) {
    if (wrap) wrap.innerHTML = '<div style="font-size:12px;color:#EF4444">خطأ في التحميل: ' + esc(e.message) + '</div>';
  }
}

function usePaperInChat(id, title) {
  // Switch to chat with a prompt about the paper
  S.screen = 'chat';
  S.messages = S.messages || [];
  S.messages.push({ role: 'user', content: `أريد أن أحل أسئلة من امتحان: "${title}" — ساعدني في الحل خطوة بخطوة`, time: new Date().toLocaleTimeString('ar', { hour: '2-digit', minute: '2-digit' }) });
  render();
  setTimeout(() => sendMessage(), 200);
}

async function deleteBook(id) {
  if (!confirm('حذف هذا الكتاب؟')) return;
  const token = localStorage.getItem('oa_token') || '';
  await fetch(API + '/books/' + id, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } });
  const wrap = ge('books-list-wrap');
  if (wrap) wrap.innerHTML = '<div style="font-size:12px;color:var(--text-muted)">جاري إعادة التحميل...</div>';
  setTimeout(() => { if (S.screen === 'admin') render(); }, 500);
}

async function loadAdminData() {
  const key = ge('admin-key')?.value?.trim();
  if (!key) return showToast('أدخل المفتاح', 'error');
  adminKey = key;
  const btn = ge('b-admin-load');
  if (btn) { btn.disabled = true; btn.textContent = '...'; }
  try {
    const r = await fetch(API + '/admin/dashboard', {
      headers: { 'x-admin-key': key }
    });
    if (!r.ok) throw new Error('مفتاح خاطئ أو غير مصرح');
    adminData = await r.json();
    render();
  } catch(e) {
    showToast(e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = '📊 تحميل البيانات'; }
  }
}

/* ════════════════════════════════════════════════════════════
   PUSH NOTIFICATIONS — Web Push (works when app is closed)
   ════════════════════════════════════════════════════════════ */

// Convert base64url VAPID key to Uint8Array
function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) outputArray[i] = rawData.charCodeAt(i);
  return outputArray;
}

async function requestPushPermission() {
  if (!window.Notification || !('serviceWorker' in navigator)) {
    showToast(S.lang==='en'?'Your browser does not support notifications':'متصفحك لا يدعم الإشعارات', 'error');
    return;
  }
  const btn = ge('b-push');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ جارٍ التفعيل...'; }

  try {
    // Request browser permission
    const perm = await Notification.requestPermission();
    if (perm !== 'granted') {
      showToast(S.lang==='en'?'Notifications blocked':'تم رفض الإشعارات — غيّر الإعدادات من المتصفح', 'error');
      if (btn) { btn.disabled = false; btn.textContent = '🔔 ' + (S.lang==='en'?'Enable Daily Reminders':'تفعيل التذكير اليومي'); }
      return;
    }

    // Get VAPID public key from server
    const keyRes = await fetch(API + '/push/vapid-key');
    if (!keyRes.ok) throw new Error('Push server not configured');
    const { publicKey } = await keyRes.json();

    // Register / get service worker
    const reg = await navigator.serviceWorker.register('/sw.js');
    await navigator.serviceWorker.ready;

    // Subscribe to push
    const subscription = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(publicKey),
    });

    // Save subscription to server
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'Africa/Cairo';
    await fetch(API + '/push/subscribe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        subscription,
        reminderTime: S.reminderTime || '19:00',
        timezone: tz,
        lang: S.lang || 'ar',
      }),
    });

    // Save endpoint locally
    S.pushEndpoint = subscription.endpoint;
    saveLocal();

    showToast(S.lang==='en'?'✅ Daily reminders enabled!':'✅ تم تفعيل التذكير اليومي!', 'success');
    render(); // Refresh profile to show active state + time picker
  } catch(e) {
    console.error('[Push]', e);
    showToast(S.lang==='en'?'Failed: '+e.message:'فشل التفعيل: '+e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = '🔔 ' + (S.lang==='en'?'Enable Daily Reminders':'تفعيل التذكير اليومي'); }
  }
}

async function saveReminderTime(time) {
  S.reminderTime = time;
  saveLocal();
  if (!S.pushEndpoint) return;
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'Africa/Cairo';
    await fetch(API + '/push/update-time', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ endpoint: S.pushEndpoint, reminderTime: time, timezone: tz }),
    });
    showToast(S.lang==='en'?'⏰ Reminder time saved!':'⏰ تم حفظ وقت التذكير!', 'success');
  } catch(e) { console.warn('[Push] update-time failed:', e); }
}

async function disablePushNotifications() {
  try {
    if (S.pushEndpoint) {
      await fetch(API + '/push/unsubscribe', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ endpoint: S.pushEndpoint }),
      });
    }
    // Unsubscribe from service worker too
    if ('serviceWorker' in navigator) {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      if (sub) await sub.unsubscribe();
    }
    S.pushEndpoint = null;
    localStorage.removeItem('oa_push_endpoint');
    saveLocal();
    showToast(S.lang==='en'?'🔕 Notifications disabled':'🔕 تم إيقاف الإشعارات', 'success');
    render();
  } catch(e) { showToast(e.message, 'error'); }
}

function sendPushNotification(title, body) {
  // Fallback: local notification (when app is open).
  // Android WebView has no Notification API at all, so existence is checked before
  // permission — reading .permission on undefined is a ReferenceError, not a false.
  if (!window.Notification || Notification.permission !== 'granted') return;
  try {
    const n = new Notification(title, {
      body, icon: '/icon-192.png', badge: '/icon-192.png',
      dir: 'rtl', lang: 'ar', tag: 'ostazai-reminder',
    });
    n.onclick = () => { window.focus(); n.close(); };
  } catch(e) { console.warn('Notification failed:', e); }
}

function initPushNotifications() {
  // Re-register the service worker on load so push stays active.
  // This runs inside init(); it used to throw on Android WebView, which has no
  // Notification API, and took initStudyTimer() and the offline banner down with it.
  if (!('serviceWorker' in navigator)) return;
  if (!window.Notification || Notification.permission !== 'granted') return;
  navigator.serviceWorker.register('/sw.js').catch(()=>{});
}

/* ════════════════════════════════════════════════════════════
   STUDY TIMER — tracks active study minutes per day
   ════════════════════════════════════════════════════════════ */
let _studyTimerInterval = null;
let _studyScreenStart   = null;
const STUDY_SCREENS = new Set(['chat','flashcards','quiz','summary','mindmap','igcse','lessons','papers']);

function initStudyTimer() {
  // Track time every 30s while on a study screen
  _studyTimerInterval = setInterval(() => {
    if (STUDY_SCREENS.has(S.screen)) {
      S.studyMinutesToday = (S.studyMinutesToday || 0) + 0.5;
      S.studyMinutesTotal = (S.studyMinutesTotal || 0) + 0.5;
      // Update streak date
      const today = new Date().toDateString();
      S.studyDateToday = today;
      saveLocal();
    }
  }, 30 * 1000);

  // Pause timer when tab is hidden
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) saveLocal();
  });
  window.addEventListener('beforeunload', () => saveLocal());
}

function scheduleStudyReminders() {
  // Schedule reminders and send local notifications for today's schedule
  if (!S.schedule || !S.schedule.length) return;
  const now = new Date();
  const today = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'][now.getDay()];
  S.schedule.forEach(item => {
    if (item.day !== today) return;
    const [hours, mins] = (item.time || '16:00').split(':').map(Number);
    const target = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hours, mins, 0);
    const delay = target.getTime() - now.getTime();
    if (delay > 0 && delay < 24*60*60*1000) {
      setTimeout(() => sendPushNotification(
        'أستاذي 📅 — تذكير الجدول',
        'حان وقت مذاكرة ' + (item.subject || '') + '! 📚 ابدأ الآن'
      ), delay);
    }
  });
}

async function shareConversation() {
  if (!S.messages.length) { showToast('لا توجد محادثة لمشاركتها', 'error'); return; }
  const msgs = S.messages.slice(-6);
  const parts = msgs.map(function(m) {
    const prefix = m.role === 'user' ? '\n\u{1F9D1} \u{623}\u{646}\u{627}:\n' : '\n\u{1F393} \u{623}\u{633}\u{62A}\u{627}\u{630} AI:\n';
    return prefix + (m.content || '');
  });
  const shareText = parts.join('') + '\n\n\u{2014} \u{645}\u{646} \u{62A}\u{637}\u{628}\u{64A}\u{642} \u{623}\u{633}\u{62A}\u{627}\u{630} AI \u{1F393}\n' + window.location.origin;

  if (navigator.share) {
    try { await navigator.share({ title: '\u{623}\u{633}\u{62A}\u{627}\u{630} AI', text: shareText }); return; }
    catch(e) { if (e.name === 'AbortError') return; }
  }
  try {
    await navigator.clipboard.writeText(shareText);
    showToast('\u{62A}\u{645} \u{646}\u{633}\u{62E} \u{627}\u{644}\u{645}\u{62D}\u{627}\u{62F}\u{62B}\u{629} ✅', 'success');
  } catch {
    const ta = document.createElement('textarea');
    ta.value = shareText; document.body.appendChild(ta);
    ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
    showToast('\u{62A}\u{645} \u{646}\u{633}\u{62E} \u{627}\u{644}\u{645}\u{62D}\u{627}\u{62F}\u{62B}\u{629} ✅', 'success');
  }
}

